window.__ARXIV_DATA__ = {"papers":[{"id":"2609.19143v1","title":"PANORAMA: Panoptic Grounded Captioning via Mask Proposal Selection","abstract":"Intelligent systems that act in the world require image understanding that is both comprehensive and spatially grounded. Current vision-language models (VLMs) can generate fluent and detailed image captions, but reliably associating them with image pixels remains challenging. Existing methods that combine dense captioning with pixel-level grounding often produce either incomplete descriptions or inaccurate segmentation masks. We study this problem through panoptic grounded captioning, a task that requires a VLM to describe both foreground objects and background regions while grounding each referring phrase with pixel-level masks. We make three contributions. First, we introduce PanoCaps, a human-annotated benchmark constructed from panoptic segmentation datasets. It provides dense captions with near-complete pixel coverage and image-text alignments at the entity level, supporting both training and evaluation. We further propose a phrase-mask matching protocol and a generalized Panoptic Quality (gPQ) metric that jointly evaluates textual and mask agreement. Second, we formulate phrase grounding as selection from a phrase-conditioned pool of mask proposals and introduce PANORAMA, a VLM that conditions a pretrained segmenter on contextualized phrase representations to obtain candidate masks and learns to select those corresponding to each phrase. Training this interface jointly with caption generation enables PANORAMA to produce high-quality masks while allowing each phrase to refer to a single region or multiple instances. Third, PANORAMA achieves the best overall grounding on PanoCaps and matches or exceeds specialized models across several pixel-level grounding tasks. Experiments show that our method produces precise entity-level segmentations while maintaining detailed, mask-consistent captions. Code, data and models are available at https://www.di.ens.fr/willow/research/panorama/.","authors":["Sara Pieri","Evangelos Kazakos","Shizhe Chen","Josef Sivic","Cordelia Schmid"],"published":"2026-09-16T17:59:30Z","updated":"2026-09-16T17:59:30Z","abstract_url":"https://arxiv.org/abs/2609.19143v1","html_url":"https://arxiv.org/html/2609.19143v1","pdf_url":"https://arxiv.org/pdf/2609.19143v1.pdf","matched_keywords":["representation","instance"],"source_used":"html","source_text_chars":122178,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, instance 相关；摘要显示其主要贡献为：Intelligent systems that act in the world require image understanding that is both comprehensive and spatially grounded. Current vision-language models (VLMs) can generate fluent and detailed image captions, but reliably associating them with image pixels rem...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19142v1","title":"PointZero: 3D Point Track Completion for Learning Transferable 3D Dynamics","abstract":"World models endow perceptual systems with the ability to predict how scenes evolve under interaction. They are most beneficial when trained on diverse volumes of data, to instill a rich prior into downstream applications. Existing methods typically require robot action labels to learn action-conditioned 3D dynamics, which excludes web video data from the training pool. We study 3D point track completion as a pre-training objective for learning transferable 3D dynamics without robot data. Given a single RGB-D observation and sparse partial 3D trajectories (tracks), we predict future 3D tracks of all observed points. We show this objective produces a rich 3D dynamics prior, without requiring robot action labels. We contribute a diverse dataset of 2.9 million synthetic frames spanning deformable, articulated, and rigid objects, and use it to train PointZero. We show that a flexible and expressive transformer, PointZero, outperforms prior methods on the same data. We demonstrate the utility of our pre-training objective by post-training PointZero for two downstream applications: (1) action-conditioned 3D dynamics prediction and (2) imitation learning. When fine-tuned to condition on end-effector pose, PointZero outperforms the baselines on the recent PGND 3D dynamics benchmark. When fine-tuned to predict robot actions and 3D tracks, PointZero outperforms or matches the baselines on 6/7 simulated and real-world robot manipulation tasks. We furthermore evaluate training PointZero from scratch to isolate the benefits of our proposed architecture from those of our proposed pre-training objective and dataset. We release the dataset, checkpoints, and full training recipe.","authors":["Bardienus P. Duisterhof","Kaifeng Zhang","Adam Hung","Bowen Wen","Stan Birchfield","Yunzhu Li","Deva Ramanan","Jeffrey Ichnowski"],"published":"2026-09-16T17:59:30Z","updated":"2026-09-16T17:59:30Z","abstract_url":"https://arxiv.org/abs/2609.19142v1","html_url":"https://arxiv.org/html/2609.19142v1","pdf_url":"https://arxiv.org/pdf/2609.19142v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":66848,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：World models endow perceptual systems with the ability to predict how scenes evolve under interaction. They are most beneficial when trained on diverse volumes of data, to instill a rich prior into downstream applications. Existing methods typically require r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19138v1","title":"In-Context Robot Learning with VLM Agents","abstract":"Enabling robots to adapt to unfamiliar environments as readily as humans remains a moonshot goal of embodied AI. No finite collection of demonstrations can cover every task and situation a robot will encounter, making the ability to learn from context at deployment essential for generalization. Such in-context learning (ICL), however, remains largely beyond the reach of existing robotic policies. The broad agentic capabilities of commercial vision-language models (VLMs), such as GPT-6 Astra, raise a compelling question: can these models learn from demonstrations, examples, and interaction feedback, then translate that information into executable and verifiable robot behavior from a new initial state without gradient updates or persistent changes to task-specific parameters? We introduce GPT-Policy, a general-agent framework for in-context robot learning. GPT-Policy integrates a context compiler that preserves task-relevant visual transitions, a VLM that proposes robot-tool actions, and a constrained controller that verifies and executes each action and reports its outcome. We evaluate its reliability and limitations through task success and efficiency metrics, matched comparisons across models, and controlled context ablations. In real-robot trials, human video demonstrations improve task completion even without robot action labels, while aligned action references yield further gains on contact-sensitive tasks. These findings position GPT-Policy as a step toward robot adaptation through in-context learning, providing an empirical foundation for translating the general-purpose capabilities of VLMs into physical behavior and clarifying the challenges that must be overcome for reliable deployment.","authors":["Dongzhou Cheng","Taoran Yi","Ye Fang","Xingwu Zhang","Fan Feng","Yixuan Li","Gengxiong Zhuang","Rongze Wang","Shuai Yang","Wei Song","Weizhi Xue","Minyan Wu","Jie Gui","Jiaqi Wang","Tong Wu"],"published":"2026-09-16T17:58:35Z","updated":"2026-09-16T17:58:35Z","abstract_url":"https://arxiv.org/abs/2609.19138v1","html_url":"https://arxiv.org/html/2609.19138v1","pdf_url":"https://arxiv.org/pdf/2609.19138v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":96022,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：Enabling robots to adapt to unfamiliar environments as readily as humans remains a moonshot goal of embodied AI. No finite collection of demonstrations can cover every task and situation a robot will encounter, making the ability to learn from context at depl...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19122v1","title":"Adaptive Convolutional Sparse Coding via Information Bottleneck for Robust Visual Signal Representation","abstract":"Visual signals require compact yet sufficient representations for robust downstream prediction. Convolutional sparse coding (CSC) provides an explicit mechanism for suppressing redundant components while preserving signal content, but its sparsity coefficient is typically fixed and manually selected. We propose an adaptive convolutional sparse coding framework for robust visual signal representation. Specifically, we unfold the CSC optimization with the Fast Iterative Shrinkage-Thresholding Algorithm (FISTA) and treat the sparsity coefficient as a differentiable variable jointly learned with the network parameters. From the information bottleneck perspective, this coefficient controls the trade-off between information retention and compression: the sparsity term promotes compact representations, while the reconstruction term together with task loss preserves task-relevant signal content. We further introduce a label-free post-training strategy that adjusts the compression strength for corrupted inputs with the main network parameters fixed. Experiments on CIFAR and ImageNet demonstrate competitive clean-data recognition and greatly improved robustness under different input perturbations.","authors":["Meng'en Qin","Yinchen Liu","Mingxuan Cui","Youlu Xing"],"published":"2026-09-16T17:43:46Z","updated":"2026-09-16T17:43:46Z","abstract_url":"https://arxiv.org/abs/2609.19122v1","html_url":"https://arxiv.org/html/2609.19122v1","pdf_url":"https://arxiv.org/pdf/2609.19122v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":32285,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Visual signals require compact yet sufficient representations for robust downstream prediction. Convolutional sparse coding (CSC) provides an explicit mechanism for suppressing redundant components while preserving signal content, but its sparsity coefficient...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19119v1","title":"Track, Articulate, Act: Generating Articulation from Casual Human Videos","abstract":"Human videos contain rich causal evidence for robot manipulation: they reveal how hand motion induces object motion and produces task-relevant changes in object state. In this work, we study articulated objects such as doors, drawers, cabinets, laptops, ovens, and hinged containers that are ubiquitous in daily life and present unique challenges for embodied interaction. These objects cannot be represented by a single pose; their motion depends on the underlying parts and joints. We introduce a real-to-sim framework that reconstructs a simulation-ready articulated object and hand-object interaction from a casual monocular RGB video, without RGB-D or multi-view input, prior scans, manually specified joints, or robot demonstrations. Our key insight is that dense 3D point tracks provide an embodiment-agnostic articulation cue: points on the fixed link remain approximately stationary, while points on the moving link follow coherent revolute or prismatic motion. Our method segments the links, estimates the joint and its state trajectory, reconstructs an articulated asset, and aligns the recovered 3D hand motion with the object. Central to our approach is a modular recipe that repurposes powerful pretrained models for single-image 3D reconstruction, mesh segmentation, and 3D scene flow, connecting their predictions through explicit geometric reasoning to infer articulation. We use the reconstructed articulated object and the human hand trajectory to replay interactions through contact in MuJoCo. The framework shows how pretrained vision models and explicit motion reasoning can turn casual human videos into articulated object models suitable for downstream embodied interactions. https://track-articulate-act.github.io/","authors":["Jiaming Zhang","Homanga Bharadhwaj"],"published":"2026-09-16T17:43:12Z","updated":"2026-09-16T17:43:12Z","abstract_url":"https://arxiv.org/abs/2609.19119v1","html_url":"https://arxiv.org/html/2609.19119v1","pdf_url":"https://arxiv.org/pdf/2609.19119v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":58183,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Human videos contain rich causal evidence for robot manipulation: they reveal how hand motion induces object motion and produces task-relevant changes in object state. In this work, we study articulated objects such as doors, drawers, cabinets, laptops, ovens...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18898v1","title":"NormLift: From Lifted Features To Semantic Reliability In 3D Gaussian Splatting","abstract":"Training-free weighted aggregation is widely used to lift 2D semantic features onto 3D Gaussians for open-vocabulary scene understanding, yet its theoretical role remains insufficiently understood. Existing analyses typically justify this operation from the rendering side, treating Gaussian features as linearly composable Euclidean variables for reconstructing 2D feature maps. However, this view does not match downstream 3D usage, where each Gaussian is often queried independently in a cosine-based embedding space. We revisit feature lifting from the 3D side and formulate per-Gaussian assignment as a cosine alignment problem on the CLIP unit sphere. Under this objective, the L2-normalized semantic back-projected feature emerges as the closed-form solution, providing a complementary interpretation of the standard lifting rule from the perspective of per-Gaussian semantic assignment. The same formulation further yields a norm decomposition into intra-view and inter-view consistency, suggesting that feature magnitude itself can serve as a semantic reliability signal. Calibrated by effective multi-view support, this reliability score guides a mode-voting refinement that preserves CLIP feature validity by avoiding linear averaging. Experiments on open-vocabulary 3D semantic segmentation show that NormLift is an efficient, training-free framework that achieves strong performance across evaluation protocols.","authors":["Yihan Zang","Da Li","Dominik Engel","Shinkyu Park","Ivan Viola"],"published":"2026-09-16T16:35:35Z","updated":"2026-09-16T16:35:35Z","abstract_url":"https://arxiv.org/abs/2609.18898v1","html_url":"https://arxiv.org/html/2609.18898v1","pdf_url":"https://arxiv.org/pdf/2609.18898v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":78172,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Training-free weighted aggregation is widely used to lift 2D semantic features onto 3D Gaussians for open-vocabulary scene understanding, yet its theoretical role remains insufficiently understood. Existing analyses typically justify this operation from the r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18860v1","title":"Decodable but Misrouted: Sparse Features Uncover a Readout Gap in Vision-Language Models for Harmful Meme Detection","abstract":"When a large vision-language model misclassifies a harmful meme, the failure may reflect missing internal evidence or an inability to route represented evidence to its output. We distinguish these cases in Gemma-3 and Qwen3.5 using sparse autoencoders, role-conditioned probes, causal interventions, and recovery experiments across six harmful content benchmarks, with additional Spanish and Hindi-English code-mixed evaluations. Sparse readouts outperform native prediction on all six primary binary tasks: Qwen averages $0.740$ versus $0.432$ native macro-F1, while residual reconstruction reaches $0.486$, whereas Gemma improves from $0.532$ to $0.714$. These differences reflect supervised accessibility rather than a pre-existing, native decision rule, and the most influential token role depends on the task. Under the evaluated score scales, Qwen silent-feature ablation is $24-63$ times more probe-sensitive, whereas routed-feature patching on literal yes/no tasks is $16-140$ times more output-sensitive. Calibration-only routing recovers $93.3$% of the mean gap, and probe-distilled LoRA improves native predictions, although shared multi-task adaptation causes negative transfer. A case study of Gemma-3-12B on Facebook Hateful Memes finds a distributed rank-32 image-prompt interaction, reaching $0.756$ versus $0.685$ native macro-F1. Robustness controls show that the signal extends beyond English, is not explained solely by accompanying OCR, and depends on paired visual evidence. Thus, routing, rather than representation alone, is a recurring bottleneck in harmful meme classification.","authors":["Girish A. Koushik","Diptesh Kanojia","Helen Treharne"],"published":"2026-09-16T16:00:36Z","updated":"2026-09-16T16:00:36Z","abstract_url":"https://arxiv.org/abs/2609.18860v1","html_url":"https://arxiv.org/html/2609.18860v1","pdf_url":"https://arxiv.org/pdf/2609.18860v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":145458,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：When a large vision-language model misclassifies a harmful meme, the failure may reflect missing internal evidence or an inability to route represented evidence to its output. We distinguish these cases in Gemma-3 and Qwen3.5 using sparse autoencoders, role-c...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18844v1","title":"ReFigBench: Benchmarking Scientific Figure Reconstruction as Editable PowerPoint Artifacts","abstract":"Multimodal coding agents are expected to turn visual inputs into usable artifacts, and they act through a harness, the layer of tools, context management, and execution environment around the model. Existing evaluations often isolate short tool calls, API traces, or screenshot resemblance, and a low score under these proxies cannot say whether the model saw poorly, planned poorly, or was failed by its harness. We study scientific overview figure reconstruction, an agent task in which a source image must become an editable PowerPoint slide that preserves text, topology, layout, and native document structure. We introduce ReFigBench, a benchmark and evaluation framework built on 1,000 real overview figures retrieved from arXiv papers with full provenance. Coding agents from four model families reconstruct every figure under two workflows, direct code generation and a specialized PPTX workflow, and the strongest model runs inside two commercial harnesses, yielding ten configurations. Evaluation combines deterministic artifact checks, repeated automated scoring by judges from two model families, and blinded human comparisons. Perception remains a bottleneck that iterative rendering only partly repays. Whether workflow effort converts into quality depends on the model together with its harness, since the same model gains from the specialized workflow inside one harness and loses inside the other, and the harness shifts scores even under an identical direct prompt. The specialized workflow erases native connectors in every configuration, human judges still prefer its renderings in most matchups, and even the strongest agent falls short of the rubric ceiling. These results expose the tension between fidelity and editability as the central challenge for practical multimodal document agents.","authors":["Liyang Fan","Chi Wei","Yitai Li","Xinping Bi","Guhong Chen","Chenghao Sun","Haoxiang Yang","Qingwen Li","Kai Yan","Hong Li","Bo Li"],"published":"2026-09-16T15:51:51Z","updated":"2026-09-16T15:51:51Z","abstract_url":"https://arxiv.org/abs/2609.18844v1","html_url":"https://arxiv.org/html/2609.18844v1","pdf_url":"https://arxiv.org/pdf/2609.18844v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"html","source_text_chars":92532,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, multimodal 相关；摘要显示其主要贡献为：Multimodal coding agents are expected to turn visual inputs into usable artifacts, and they act through a harness, the layer of tools, context management, and execution environment around the model. Existing evaluations often isolate short tool calls, API tra...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18836v1","title":"Copy What Is Seen, Generate What Is Not: Training-Free Anomaly-Aware Video Restoration","abstract":"A surveillance system that detects an anomaly often has to repair the footage as well, yet the two tasks are studied in isolation: training-free anomaly detectors stop at a score or a label, while training-free video editing answers to a user prompt rather than to a detector. This paper proposes AVR (Anomaly-aware Video Restoration), which closes that gap with frozen pretrained models alone and generates content only where the clip offers no evidence to copy. Motion evidence first gates open-vocabulary proposals into spatio-temporal masks. A background prior computed from the clip then fills every pixel the anomaly ever uncovers, leaving diffusion to synthesize only what no frame showed, and a frozen verifier decides per clip whether to trust a classical, a prior-anchored, or a background-conditioned restorer. Extensive experiments on three surveillance datasets, under both full-reference anomaly injection and real anomalies, show that AVR leads full-frame fidelity under oracle masks, matches three trained video inpainters inside the edited region, and outperforms a detect-then-generate pipeline on the masks it produces itself, while suppressing both the residual anomaly and the flicker of free diffusion.","authors":["Zhida Qu","Shengchao Chen"],"published":"2026-09-16T15:43:21Z","updated":"2026-09-16T15:43:21Z","abstract_url":"https://arxiv.org/abs/2609.18836v1","html_url":"https://arxiv.org/html/2609.18836v1","pdf_url":"https://arxiv.org/pdf/2609.18836v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":47813,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：A surveillance system that detects an anomaly often has to repair the footage as well, yet the two tasks are studied in isolation: training-free anomaly detectors stop at a score or a label, while training-free video editing answers to a user prompt rather th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18823v1","title":"Using OCR Heads to Verbalize Image Semantics","abstract":"How do VLMs map from pixels to semantics? To understand this general question, we focus on a narrow one: studying how VLMs perform optical character recognition (OCR). Across four models, we identify attention heads causally necessary for OCR, and discover that these are in fact general-purpose heads that output interpretable semantic features across all image tokens. For example, pointing these heads at an image token containing the word \"bike\" causes Qwen3-VL-8B to output \"bike,\" but pointing them at a bird wing causes the model to output the token \"feathers.\" We collapse these heads' attention weights into a single verbalization lens transformation that reveals interpretable semantic features in hidden states across all layers. When combined with projection to vocabulary space, we can obtain interpretable labels starting from layer 0, showing that image representations are in fact aligned with language in early layers. We find that we can also use the inverse of this transformation to edit non-word concepts, e.g., replacing a tractor with a revolver in a naturalistic image, providing causal evidence that this subspace is useful for more than just OCR. Our results are an example of how the study of specific mechanisms can shed light on broader interpretability problems.","authors":["Sheridan Feucht","Benno Krojer","Sarah Wang","Henry Abrahamsen","Byron C. Wallace","David Bau"],"published":"2026-09-16T15:30:17Z","updated":"2026-09-16T15:30:17Z","abstract_url":"https://arxiv.org/abs/2609.18823v1","html_url":"https://arxiv.org/html/2609.18823v1","pdf_url":"https://arxiv.org/pdf/2609.18823v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":73866,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：How do VLMs map from pixels to semantics? To understand this general question, we focus on a narrow one: studying how VLMs perform optical character recognition (OCR). Across four models, we identify attention heads causally necessary for OCR, and discover th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18772v1","title":"Zero-Shot Cross-Lingual Recognition of Sign Language Handshapes","abstract":"Sign language processing advances rapidly for high-resource languages such as American Sign Language (ASL), yet most of the world's sign languages lack the phonological annotations new methods require. We present the first zero-shot cross-lingual framework for handshape recognition, transferring from ASL to Catalan Sign Language (LSC). Our approach leverages the decomposition of handshapes into five phonological features -- selected fingers, flexion, spread, thumb position, and thumb contact -- shared across both languages, to decode LSC handshapes from predicted features via a composite phonological distance metric. We evaluate three architectures (MLP, SL-GCN, SHuBERT) trained on two ASL corpora (PopSign, Sem-Lex) against a 37-handshape, single-signer LSC benchmark. Zero-shot transfer proves viable once recording-format disparities are harmonized, reaching 80.0% phonological feature accuracy and 54.5% expected handshape accuracy. Phonological decomposition thus offers a bridge for extending sign language technologies to low-resource languages without any target-language video training labels.","authors":["Marcel Granero-Moya","Carolina del Corral Farrarós","Gloria Haro","Coloma Ballester","Ricardo Marques"],"published":"2026-09-16T14:56:51Z","updated":"2026-09-16T14:56:51Z","abstract_url":"https://arxiv.org/abs/2609.18772v1","html_url":"https://arxiv.org/html/2609.18772v1","pdf_url":"https://arxiv.org/pdf/2609.18772v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":77973,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Sign language processing advances rapidly for high-resource languages such as American Sign Language (ASL), yet most of the world's sign languages lack the phonological annotations new methods require. We present the first zero-shot cross-lingual framework fo...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18753v1","title":"Toward Markerless Video-based Tremor Analysis: Objective Quantification of Pathological Tremor in Mouse Preclinical Models","abstract":"Tremor is a movement disorder characterized by involuntary, rhythmic oscillations of body parts and is a hallmark of several neurological conditions, including Parkinson's disease and essential tremor. Elucidating its underlying mechanisms relies heavily on mouse models, which offer genetic manipulability and translational relevance to human neural circuitry. Accordingly, these models are indispensable for studying tremor pathophysiology. So far, electromyography and accelerometers have been used as methods to quantitatively observe tremors in mice. However, these methods have several drawbacks, such as high costs and complex setups. In particular, the invasive surgical implantation of devices causes significant stress to the animals. Although RGB-based methods offer non-invasive and cost-effective alternatives, they often lack the sensitivity required to detect subtle tremors. Therefore, this paper addresses these challenges by achieving mouse tremor severity estimation using conventional RGB cameras only. To address the challenging task of isolating tremor-related vibrations while the mouse itself is also in motion, our pipeline incorporates segmentation-based pre-processing to extract the mouse region and a Tremor Score Estimation Module that captures subtle tremors with high sensitivity. In the experiments, we assessed tremors in unrestrained mice using a non-invasive method with two standard cameras. The results demonstrated a strong correlation with accelerometer measurements and confirmed that the method accurately captured the intensity-dependent characteristics of tremors. The project page is available at https://isogawalab.github.io/Video-based-Tremor-Analysis-Project/.","authors":["Yota Koshimoto","Akihiro Tsukahara","Yasuhiro Moriwaki","Mariko Isogawa"],"published":"2026-09-16T14:44:11Z","updated":"2026-09-16T14:44:11Z","abstract_url":"https://arxiv.org/abs/2609.18753v1","html_url":"https://arxiv.org/html/2609.18753v1","pdf_url":"https://arxiv.org/pdf/2609.18753v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":30713,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Tremor is a movement disorder characterized by involuntary, rhythmic oscillations of body parts and is a hallmark of several neurological conditions, including Parkinson's disease and essential tremor. Elucidating its underlying mechanisms relies heavily on m...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18737v1","title":"Geometry beneath the Waves: Dense Priors for Sparse-View Underwater 3D Gaussian Splatting","abstract":"Underwater 3D reconstruction supports applications ranging from marine ecosystem monitoring and subsea inspection to underwater archaeology, education, and immersive visualisation. 3D Gaussian Splatting has made real-time photorealistic novel-view rendering practical, while underwater variants incorporate physically based image-formation models to separate medium effects from scene radiance. Their reconstruction quality, however, remains fundamentally limited by the geometry used for initialisation.","authors":["Harvey Caldeira","Haoran Wang","Guoxi Huang","Shaoyu Cai","Rachel Fu","Nantheera Anantrasirichai"],"published":"2026-09-16T14:32:58Z","updated":"2026-09-16T14:32:58Z","abstract_url":"https://arxiv.org/abs/2609.18737v1","html_url":"https://arxiv.org/html/2609.18737v1","pdf_url":"https://arxiv.org/pdf/2609.18737v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":14159,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Underwater 3D reconstruction supports applications ranging from marine ecosystem monitoring and subsea inspection to underwater archaeology, education, and immersive visualisation. 3D Gaussian Splatting has made real-time photorealistic novel-view rendering p...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18690v1","title":"RankGround: Efficient High-Resolution GUI Grounding via Lightweight Reranker-Guided Crop Selection","abstract":"Graphical User Interface (GUI) grounding is a fundamental perception task for multimodal agents, enabling them to interpret natural language instructions and interact with digital interfaces. Existing methods face a fundamental trade-off between accuracy and efficiency: direct full-image inference often fails to capture small or visually similar UI elements, while multi-crop strategies improve localization at the cost of multiple expensive Vision-Language Model (VLM) calls per query. To address this challenge, we propose RankGround, a two-stage framework that achieves accurate GUI grounding with a single VLM call per query. Central to our approach is GroundRanker, a lightweight multimodal reranker that identifies the most promising crop from a dense candidate set. Because no off-the-shelf ranking dataset is available, we construct ranking supervision data from existing grounding datasets. A strict containment criterion and boundary-aware positive augmentation improve alignment and spatial coverage in cluttered layouts. GroundRanker is then trained with a two-stage curriculum: a pointwise objective first learns coarse containment, and a listwise objective refines subtle semantic and spatial distinctions among visually similar crops. Experimental results show that RankGround consistently outperforms strong baselines while reducing computational cost. It achieves 1.4 times faster inference and improves localization accuracy by 5.5% on average over the second-best method across all backbones and screen scales, establishing a new state of the art in both efficiency and precision for GUI grounding.","authors":["Liyang Fan","Xinping Bi","Yitai Li","Shuaimin Li","Hui Li","Min Yang"],"published":"2026-09-16T14:06:38Z","updated":"2026-09-16T14:06:38Z","abstract_url":"https://arxiv.org/abs/2609.18690v1","html_url":"https://arxiv.org/html/2609.18690v1","pdf_url":"https://arxiv.org/pdf/2609.18690v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"html","source_text_chars":59910,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, multimodal 相关；摘要显示其主要贡献为：Graphical User Interface (GUI) grounding is a fundamental perception task for multimodal agents, enabling them to interpret natural language instructions and interact with digital interfaces. Existing methods face a fundamental trade-off between accuracy and...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18688v1","title":"Generalist-Specialist Mixture-of-Experts for Rare Pathology Detection in Multimodal Imaging","abstract":"AI models for multimodal medical imaging must balance modality-specific specialization with cross-modal shared representations, a trade-off that pure Mixture-of-Experts (MoE) architectures currently fail to satisfy. Expert-based routing improves in-domain learning but may sacrifice cross-modal signals, which appear particularly important for rare (low-prevalence) pathologies in our experiments. To resolve this, we introduce Generalist-Specialist-MoE (GS-MoE), a two-branch (MoE) architecture that couples a cross-modal generalist model with distinct modality-specific specialists (experts) via domain-constrained feature fusion. On RadImageNet (1.35M images, 165 pathologies, three modalities), GS-MoE recovers detection of six low-prevalence pathologies on which every baseline scores F1 $=$ 0, with per-class gains up to +0.60 F1. It attains this while even slightly exceeding dense and specialist-only MoE aggregate baselines (MCC 0.770), while using ${\\sim}53\\%$ fewer active parameters at inference than the strongest investigated dense model.","authors":["Johannes Kaiser","Florian Braunmiller","Daniel Rückert","Georgios Kaissis"],"published":"2026-09-16T14:04:24Z","updated":"2026-09-16T14:04:24Z","abstract_url":"https://arxiv.org/abs/2609.18688v1","html_url":"https://arxiv.org/html/2609.18688v1","pdf_url":"https://arxiv.org/pdf/2609.18688v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":34231,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：AI models for multimodal medical imaging must balance modality-specific specialization with cross-modal shared representations, a trade-off that pure Mixture-of-Experts (MoE) architectures currently fail to satisfy. Expert-based routing improves in-domain lea...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18667v1","title":"Video-Based Markerless Motion Capture for Clinical and Rehabilitation Biomechanics: A PRISMA-ScR Scoping Review of Validated Architectures, Clinical Readiness, and Emerging Methods","abstract":"Background.. Video-based markerless motion capture promises movement analysis without the cost, space and skin-marker constraints of optoelectronic systems, with particular potential for clinical and rehabilitation settings. Whether validated pipelines yet deliver clinically acceptable biomechanics, and how they relate to the underlying computer-vision research, remains unclear. Methods. We conducted a scoping review following the PRISMA extension for Scoping Reviews, with a registered protocol and searches of PubMed, Scopus and IEEE Xplore (January 2015 to February 2026; the computer-vision scan was updated to July 2026). A dual-tier design paired a primary corpus of validated biomechanical studies with a complementary, curated and deliberately non-exhaustive corpus of emerging computer-vision work, used qualitatively. We charted study characteristics, pipeline architecture, validation methods and joint-angle accuracy. Results. We included 117 studies, most published from 2024 onward and conducted on healthy adults walking in a laboratory. Pipelines formed five architectural families across monocular and multi-camera modalities; most reported raw joint angles without biomechanical refinement. Sagittal lower-limb agreement clustered around 5 to 6{\\textdegree}, generally short of clinical acceptability, while out-of-plane kinematics, kinetics, and pathological or older populations were rarely validated. Emerging computer-vision building blocks (foundation-model mesh recovery, differentiable inverse kinematics, video-based kinetics) were almost absent from validated studies. Conclusions. Video-based markerless capture is not yet interchangeable with marker-based systems for clinical joint kinematics, and it remains barely validated where rehabilitation needs it most: older and pathological populations, out-of-plane kinematics, and kinetics. Mapping this evidence gap onto emerging computer-vision advances, we propose hypothesis-generating design guidelines, not a validated method, to steer the next generation of pipelines toward accessible, clinically meaningful movement analysis.","authors":["Florian Delaplace","Elodie Piche","Frédéric Chorin","Raphael Zory"],"published":"2026-09-16T13:44:08Z","updated":"2026-09-16T13:44:08Z","abstract_url":"https://arxiv.org/abs/2609.18667v1","html_url":"https://arxiv.org/html/2609.18667v1","pdf_url":"https://arxiv.org/pdf/2609.18667v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":2296,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Background.. Video-based markerless motion capture promises movement analysis without the cost, space and skin-marker constraints of optoelectronic systems, with particular potential for clinical and rehabilitation settings. Whether validated pipelines yet de...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18634v1","title":"GenStream: Semantic Streaming Framework for Generative Reconstruction of Human-centric Media","abstract":"Video streaming dominates global internet traffic, yet conventional pipelines remain inefficient for structured, human-centric content such as sports, performance, or interactive media. Standard codecs re-encode entire frames, foreground and background alike, treating all pixels uniformly and ignoring the semantic structure of the scene. This leads to significant bandwidth waste, particularly in scenarios where backgrounds are static and motion is constrained to a few salient actors. We introduce GenStream, a semantic streaming framework that replaces dense video frames with compact, structured metadata. Instead of transmitting pixels, GenStream encodes each scene as a combination of skeletal keypoints, camera viewpoint parameters, and a static 3D background model. These elements are transmitted to the client, where a generative model reconstructs photorealistic human figures and composites them into the 3D scene from the original viewpoint. This paradigm enables extreme compression, achieving over 99.9% bandwidth reduction compared to HEVC for the continuous data stream. We partially validate GenStream on Olympic figure skating footage and demonstrate potential for high perceptual fidelity under minimal data. While acknowledging the significant computational costs shifted to the client and challenges in generalization, GenStream opens new directions in volumetric avatar synthesis, canonical 3D actor fusion across views, and personalized viewing experiences, laying the groundwork for scalable, intelligent streaming in the post-codec era.","authors":["Emanuele Artioli","Daniele Lorenzi","Shivi Vats","Farzad Tashtarian","Christian Timmerer"],"published":"2026-09-16T13:20:36Z","updated":"2026-09-16T13:20:36Z","abstract_url":"https://arxiv.org/abs/2609.18634v1","html_url":"https://arxiv.org/html/2609.18634v1","pdf_url":"https://arxiv.org/pdf/2609.18634v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":62213,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Video streaming dominates global internet traffic, yet conventional pipelines remain inefficient for structured, human-centric content such as sports, performance, or interactive media. Standard codecs re-encode entire frames, foreground and background alike,...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18632v1","title":"VibeAvatar: Aligning Phonetic Kinematics and Human Aesthetics for High-Fidelity Talking Avatar Synthesis","abstract":"Multi-modal talking avatar synthesis aims to generate realistic talking videos from a reference portrait and speech. Despite rapid progress in diffusion-based methods, existing approaches still struggle to jointly achieve accurate lip articulation, human-preferred motion aesthetics, and efficient inference. We observe that phonetic accuracy and motion aesthetics arise from fundamentally different sources and should be addressed at complementary stages rather than learned implicitly by a single generator. Based on this insight, we propose VibeAvatar, which disentangles these two objectives through a Phonetic Kinematics Adapter (PKA) that converts recognition-oriented speech features into phonetic-kinematic conditions at the conditioning stage, and an Aesthetic Motion Policy (AMP) that optimizes a flow-consistent stochastic sampling policy via Group Relative Policy Optimization (GRPO) at the post-training stage. With a lightweight flow-based motion generator operating in a compact 1D warp-based latent motion space, VibeAvatar achieves state-of-the-art results in articulation, aesthetics, and efficiency on both objective metrics and user studies, while generating a 10-second 512px video in under 10 seconds with only $\\sim$3GB VRAM.","authors":["Qilin Wang","Mingyu Li","Hao Tang"],"published":"2026-09-16T13:20:07Z","updated":"2026-09-16T13:20:07Z","abstract_url":"https://arxiv.org/abs/2609.18632v1","html_url":"https://arxiv.org/html/2609.18632v1","pdf_url":"https://arxiv.org/pdf/2609.18632v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":59659,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：Multi-modal talking avatar synthesis aims to generate realistic talking videos from a reference portrait and speech. Despite rapid progress in diffusion-based methods, existing approaches still struggle to jointly achieve accurate lip articulation, human-pref...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18602v1","title":"PULSE: Unlocking Practical Image Compression on Single-Thread CPU","abstract":"Despite recent progress in learned image compression, existing methods remain computationally expensive on resource-constrained hardware, particularly CPUs. We introduce PULSE, a practical codec that enables (1) low-latency decoding on diverse hardware platforms with an ultra-low-complexity 5.2 kMAC/pixel neural receiver, and (2) efficient bit-exact entropy coding with an integer linear CDF predictor and a meta prior. To recover compression performance under this tight budget, we introduce an agentic evolution process guided by heuristic probes that iteratively improves the architecture through human-LLM collaboration. PULSE decodes a 1080p image in 126 ms on a single CPU thread while achieving compression performance comparable to HM. After perceptual optimization, PULSE competes with larger perceptual codecs like MS-ILLM. Codes are at https://github.com/microsoft/GenCodec/tree/main/PULSE","authors":["Zhaoyang Jia","Tianyu Zhang","Zihan Zheng","Wenxuan Xie","Jiahao Li","Bin Li","Houqiang Li","Yan Lu"],"published":"2026-09-16T12:55:36Z","updated":"2026-09-16T12:55:36Z","abstract_url":"https://arxiv.org/abs/2609.18602v1","html_url":"https://arxiv.org/html/2609.18602v1","pdf_url":"https://arxiv.org/pdf/2609.18602v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":66632,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Despite recent progress in learned image compression, existing methods remain computationally expensive on resource-constrained hardware, particularly CPUs. We introduce PULSE, a practical codec that enables (1) low-latency decoding on diverse hardware platfo...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18582v1","title":"On-the-Fly Homographies Calibration for Multi-Camera Tracking","abstract":"Precise multi-camera tracking traditionally relies on rigorous 3D site calibration, yet this requirement is often operationally impossible in large-scale deployments. Privacy regulations frequently prohibit recording video for offline calibration; limited bandwidth precludes synchronizing high-resolution streams from hundreds of cameras; and covering immense physical sites with calibration targets is logistically infeasible. We present a multi-camera homography calibration system designed to overcome these barriers through \"on-the-fly\" geometric refinement. Starting from coarse manual homographies, we introduce a centroid-based projection optimization (PO) that continuously aligns the ground-plane geometry using live detection streams. Because PO operates asynchronously on already-transmitted, lightweight metadata, it adds zero computational latency to the real-time tracker. This allows the system to adapt automatically to camera movements or environmental changes without human intervention. This optimized geometry feeds a multi-camera bird's-eye-view (BEV) tracker that fuses detections and unifies trajectories across zones. Crucially, by operating strictly on live anonymous metadata, our solution ensures a privacy-safe, zero-overhead, and resilient tracking pipeline that maintains global consistency in dynamic environments where static, recorded-video calibration is impossible.","authors":["David Voihanski","Mor Sinai","Ben Zion Bobrovsky"],"published":"2026-09-16T12:41:55Z","updated":"2026-09-16T12:41:55Z","abstract_url":"https://arxiv.org/abs/2609.18582v1","html_url":"https://arxiv.org/html/2609.18582v1","pdf_url":"https://arxiv.org/pdf/2609.18582v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":39846,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Precise multi-camera tracking traditionally relies on rigorous 3D site calibration, yet this requirement is often operationally impossible in large-scale deployments. Privacy regulations frequently prohibit recording video for offline calibration; limited ban...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18578v1","title":"Learning Where to Focus: Self-Supervised Multi-Scale ViTs for Histopathology","abstract":"Pathologists diagnose diseases by first locating suspicious tissue and then examining it at higher magnification, whereas self-supervised vision transformers (ViTs) allocate the same spatial resolution to every image region despite diagnostic evidence being sparse and spanning multiple biological scales. Recent pathology foundation models have substantially improved representation quality by scaling training data and model capacity, but largely retain uniform tokenization. We instead investigate whether pathology representations can be improved by learning where to allocate spatial resolution during self-supervised learning. To this end, we propose CRAFT (Coarse-to-fine Region-Adaptive Feature Tokenization), a DINO-based framework that learns image-dependent mixed-scale representations by using self-supervised attention to selectively refine informative regions while preserving coarse context, together with a symmetric cross-scale regularization objective that encourages complementary coarse and fine representations. Across CAMELYON16, TCGA-Lung subtype classification, and TCGA-LUAD survival prediction, CRAFT consistently outperforms comparable-scale self-supervised methods while requiring lower inference computation. Despite using only a compact 22M parameter backbone trained on comparatively small pathology datasets, CRAFT remains competitive with, and often surpasses, substantially larger pathology foundation models.","authors":["Anabel Stammer","Valay Bundele","Mehran Hosseinzadeh","Hendrik P. A. Lensch"],"published":"2026-09-16T12:38:41Z","updated":"2026-09-16T12:38:41Z","abstract_url":"https://arxiv.org/abs/2609.18578v1","html_url":"https://arxiv.org/html/2609.18578v1","pdf_url":"https://arxiv.org/pdf/2609.18578v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18562v1","title":"Sim-to-Real Traffic Scene Understanding by Decoupling Semantics from Caption Generation with V-JEPA","abstract":"Track 2 of the AI City Challenge 2026 requires both visual question answering (VQA) and traffic event description generation under a challenging synthetic-to real domain shift. Existing vision-language approaches often entangle semantic understanding with language generation, making them susceptible to hallucination and inconsistent reasoning across event phases. In this work, we propose a decoupled semantic understanding framework that first resolves predefined traffic questions into structured semantic facts and subsequently uses these facts to guide caption generation. A frozen V-JEPA encoder extracts predictive scene representations, while a lightweight Llama-based predictor produces answers for VQA queries. To improve reliability, we introduce a training-free structured refinement mechanism that exploits statistical priors, inter-question relationships, and temporal event consistency to correct prediction errors. The refined semantic facts are then provided to Qwen3-VL-8B to generate pedestrian and vehicle descriptions for each traffic event. Experimental results on the official 2026 AI City Challenge Track 2 benchmark show that the proposed method achieves 87.09% VQA accuracy and an overall S2 score of 60.0853, ranking first among all participating teams. These results demonstrate that predictive world representations combined with structured semantic refinement enable more accurate and reliable traffic understanding, leading to higher-quality lan guage generation.","authors":["Nguyen Hoai Thuong Bui","Thanh Nguyen Vo","Trinh Tra Giang Nguyen","Ha Duc Bui"],"published":"2026-09-16T12:21:06Z","updated":"2026-09-16T12:21:06Z","abstract_url":"https://arxiv.org/abs/2609.18562v1","html_url":"https://arxiv.org/html/2609.18562v1","pdf_url":"https://arxiv.org/pdf/2609.18562v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18554v1","title":"CARA: Collision-Aware Resolution Adaptation for Multiresolution Hash Encoding Based Image Fitting","abstract":"Multiresolution hash encodings have recently enabled fast and high-fidelity implicit neural representations by storing multi-scale features in fixed-size hash tables along a geometric resolution schedule. However, the standard design is data-agnostic: different resolution levels receive identical hash-table capacity despite large differences in image frequency content. As a result, some levels experience severe hash collisions while others underutilize parameters, leading to inefficient capacity allocation. To address this issue, we propose Collision-Aware Resolution Adaptation (CARA), a method that assigns per-level resolutions by balancing the effective information load across hash levels. This adaptive allocation reduces capacity bottlenecks and improves parameter efficiency. In addition, we introduce an invertible pixel-shuffle transform that reduces hash load factors by redistributing spatial information, thereby mitigating collision-induced information loss without enlarging the hash tables. To support evaluation on extremely high-resolution data, we also curate, to the best of our knowledge, the first uncompressed whole-slide image dataset for academic research. Experiments on Kodak images, gigapixel natural images, and raw whole-slide images demonstrate that CARA consistently improves the fidelity-parameter trade-off. Our method matches state-of-the-art performance while using only $27.76%$ of the parameters, and achieves up to $6.11$ dB PSNR improvement at comparable parameter counts. Code is provided in the supplementary.","authors":["Linfeng Ye","Zhixiang Chi","Shayan Mohajer Hamidi","En-hui Yang","Konstantinos N. Plataniotis"],"published":"2026-09-16T12:17:34Z","updated":"2026-09-16T12:17:34Z","abstract_url":"https://arxiv.org/abs/2609.18554v1","html_url":"https://arxiv.org/html/2609.18554v1","pdf_url":"https://arxiv.org/pdf/2609.18554v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18546v1","title":"STUNet-Fusion: Spatiotemporal Needle-Tip Localization in Ultrasound Video via Multi-Channel Motion Fusion","abstract":"Needle-tip localization in ultrasound remains challenging because the needle may appear weak, discontinuous, or partially invisible, while imaging artifacts and anatomical structures can produce similar responses. To address this problem, we propose STUNet-Fusion, a spatiotemporal framework for needle-tip localization in ultrasound videos. The proposed method formulates the input as a tri-channel spatio-temporal fusion tensor, comprising grayscale appearance, grid-based motion feature, and raw frame difference. A shared ResNet-34 encoder extracts spatial features, ConvLSTM integrates temporal dependencies, and a U-Net decoder reconstructs a dense probability heatmap. The final coordinates are extracted via a soft-argmax operation to achieve sub-pixel localization accuracy. Experimental results demonstrate that this spatiotemporal fusion strategy significantly improves localization robustness compared to conventional baselines.","authors":["Chia-Chi Hsu","Chia-Hsuan Hsu","Che-Chou Shen"],"published":"2026-09-16T12:11:18Z","updated":"2026-09-16T12:11:18Z","abstract_url":"https://arxiv.org/abs/2609.18546v1","html_url":"https://arxiv.org/html/2609.18546v1","pdf_url":"https://arxiv.org/pdf/2609.18546v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18542v1","title":"Accuracy- and Real-Time-Aware 4D Radar Preprocessing for Autonomous Driving Perception Systems","abstract":"4D radar has emerged as a promising next-generation sensor for improving the robustness of autonomous driving perception systems because of its stable sensing capability under adverse weather conditions. However, deploying 4D radar in embedded environments with limited hardware resources requires radar-representation preprocessing that jointly considers perception accuracy, real-time performance, and computational complexity. This paper proposes a preprocessing framework for 4D-radar-based 3D object detection. First, Percentile-based 3D Shape Preservation (P3DP) extracts point clouds from radar tensors while preserving object-shape information and suppressing noise and false alarms. Second, Multi-frame-based Noise Point Discrimination using Kernel Density Estimation (MF-KDE) improves the density and reliability of sparse radar point clouds. Finally, Embedded \\& NetScore (ENS) evaluates suitability for embedded deployment by jointly considering accuracy, real-time performance, adverse-weather robustness, and model complexity.","authors":["Woo-Jin Jung","Dong-Hee Paek","Jeong-Su Park","Seung-Hyun Kong"],"published":"2026-09-16T12:06:22Z","updated":"2026-09-16T12:06:22Z","abstract_url":"https://arxiv.org/abs/2609.18542v1","html_url":"https://arxiv.org/html/2609.18542v1","pdf_url":"https://arxiv.org/pdf/2609.18542v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18540v1","title":"SVMemAgent: A Streaming Video Memory Agent for Query-Agnostic Online Frame Selection","abstract":"Most keyframe selection studies focus on offline settings, assuming access to the full video and query in advance. In contrast, real-world streaming scenarios require online frame selection under unknown video duration, without access to either the query or future frames during selection. To address this, we introduce Streaming Video Memory (SVMem), a compact and representative memory of previously observed content, updated continuously as the video stream unfolds. Building on this setting, we propose the Streaming Video Memory Agent (SVMemAgent), which dynamically maintains a memory by deciding at each timestep whether to replace an existing memory frame with the incoming frame or discard it. SVMemAgent is trained using Group Relative Policy Optimization (GRPO) with task-driven rewards derived from diverse question-answer pairs, implicitly exposing the policy to a distribution of queries during training so that SVMem retains generally informative frames at inference, when queries are unavailable. Experiments on both online and offline video benchmarks show that SVMemAgent consistently outperforms online frame selection baselines and achieves competitive performance with offline methods that assume access to the full video and query. Through task-driven rewards, SVMemAgent learns an emergent keyframe selection policy that prefers frames containing textual information, which may benefit downstream VideoQA tasks.","authors":["Dohwan Ko","Ji Soo Lee","Pierce Chuang","Debojeet Chatterjee","Ashish Shenoy","Yichao Lu","Seungwhan Moon","Xin Luna Dong","Vikas Bhardwaj","Hyunwoo J. Kim"],"published":"2026-09-16T12:04:53Z","updated":"2026-09-16T12:04:53Z","abstract_url":"https://arxiv.org/abs/2609.18540v1","html_url":"https://arxiv.org/html/2609.18540v1","pdf_url":"https://arxiv.org/pdf/2609.18540v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18511v1","title":"Learning from Distributed Eyes: Leveraging Collaborative Perception for Automated Model Adaptation","abstract":"In autonomous driving, perception models often struggle to generalize to new environments due to domain shifts. While unsupervised model adaptation offers a feasible solution without labor-intensive manual labeling, existing methods that rely solely on the ego-vehicle's data often lead to inferior pseudo-labeling performance. To address this critical issue, we propose LDE, Learning from Distributed ``Eyes\", a novel framework that transforms collaborative perception (CP) into a source of high-quality supervision for model adaptation. This pseudo-labeling approach is hyperparameter-insensitive and relatively reliable, assuming CP often outperforms single-agent's perception. However, naively implementing this approach encounters (1) the communication bottleneck of sharing rich features under time and bandwidth constraints, (2) the view discrepancy between the CP view and the learner's Field of View (FoV), and (3) the unreliability even in CP-generated labels. To address these issues, we design an adaptation-oriented feature sharing mechanism that selectively transmits the most critical information for adaptation, an FoV filtering method that meticulously eliminates mismatched labels, and a curriculum learning strategy to progressively exploit pseudo labels. Extensive experiments on 3D object detection tasks demonstrate that LDE consistently outperforms both the pre-trained models and state-of-the-art unsupervised adaptation methods.","authors":["Yanan Ma","Yihang Tao","Zhengru Fang","Zihan Fang","Yiqin Deng","Xianhao Chen","Yuguang Fang"],"published":"2026-09-16T11:44:26Z","updated":"2026-09-16T11:44:26Z","abstract_url":"https://arxiv.org/abs/2609.18511v1","html_url":"https://arxiv.org/html/2609.18511v1","pdf_url":"https://arxiv.org/pdf/2609.18511v1.pdf","matched_keywords":["3d","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18510v1","title":"DiT-Garment: Garment Dynamics with Diffusion Transformers","abstract":"We present DiT-Garment to model dynamic 3D clothing over human body models in arbitrary motion. Unlike existing methods, DiT-Garment can animate garments with unseen designs and physical materials, while allowing for direct inference of deformations for any target pose. To achieve this, we leverage a 2D diffusion transformer architecture to learn 3D deformations in a 2D UV-space. As the result is non-deterministic, our generative model learns the distribution of possible outcomes. The template garment is represented as a 3D triangle mesh spatially aligned with a 3D human body model in a standardized pose. To work with different garment designs without the need of a common template or complex graph convolution operations, the diffusion transformer is conditioned on a 3D position map of the template, represented in UV-space, which allows to implicitly learn a deformation of the 3D space around the body in standard pose. Further conditioning on body motion and physical parameters allows to physically ground the model. We quantitatively and qualitatively evaluate DiT-Garment on both synthetic and real data. While only trained on synthetic simulations of automatically generated cloth designs, our method generalizes to captured and artist-made garment designs. Code and data are available for research purposes at https://dumoulina.github.io/dit-garment/.","authors":["Antoine Dumoulin","Laurence Boissieux","Joao Regateiro","Pierre Hellier","Stefanie Wuhrer"],"published":"2026-09-16T11:44:03Z","updated":"2026-09-16T11:44:03Z","abstract_url":"https://arxiv.org/abs/2609.18510v1","html_url":"https://arxiv.org/html/2609.18510v1","pdf_url":"https://arxiv.org/pdf/2609.18510v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18490v1","title":"Learning A Unified Template for Gait Recognition","abstract":"\"What I cannot create, I do not understand.\"Human wisdom reveals that creation is one of the highest forms of learning. For example, Diffusion Models have demonstrated remarkable semantic structure and memory in image generation, understanding, and restoration, which intuitively benefits representation learning. However, current gait networks rarely embrace this perspective, relying primarily on learning by contrasting gait samples under varying complex conditions, leading to semantic inconsistency and uniformity issues. To address these issues, we propose Origins with generative capabilities whose underlying philosophy is that different entities are generated from a unified template, inherently regularizing gait representations within a consistent and diverse semantic space to capture accurate gait differences. Admittedly, learning this unified template is exceedingly challenging, as it requires the comprehensiveness of the template to encompass gait representations with various conditions. Inspired by Diffusion Models, Origins diffuses the unified template into timestep templates for gait generative learning, and meanwhile transfers the unified template for gait representation learning. Especially, gait generative and representation learning serve as a unified framework for end-to-end joint training. Extensive experiments on CASIA-B, CCPG,SUSTech1K, Gait3D, GREW and CCGR-MINI demonstrate that Origins performs unified generative and representation learning, achieving superior performance.","authors":["Panjian Huang","Saihui Hou","Junzhou Huang","Yongzhen Huang"],"published":"2026-09-16T11:27:36Z","updated":"2026-09-16T11:27:36Z","abstract_url":"https://arxiv.org/abs/2609.18490v1","html_url":"https://arxiv.org/html/2609.18490v1","pdf_url":"https://arxiv.org/pdf/2609.18490v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18488v1","title":"Beyond Random Couplings: Contrastive Noise Alignment in Generative Flows","abstract":"Diffusion and flow-matching models are typically trained by corrupting data through independently sampled Gaussian noise. While simple and scalable, this forward process induces arbitrary data-noise couplings, forcing the network to learn high-curvature transports between unrelated endpoints. Existing optimal-transport methods reduce this burden by reassigning fixed noise samples to data, but the source noise distribution itself remains passive. To address this, we introduce Contrastive Noise Alignment (CNA), a training-time method that creates dynamic, contrastive couplings by optimizing the noise representations directly. By modeling the noise batch as an interacting particle system, CNA employs a cross-modal InfoNCE objective to align noise particles with their paired data targets. To prevent spatial collapse, this alignment is regularized using an angular entropy term and a radial norm penalty. We show theoretically that this equilibrium asymptotically preserves Gaussian structures, maintaining tractability during inference. Empirically, CNA improves the alignment between noise and data, reduces flow curvature, and provides better generation quality with fewer required sampling steps. For few-step, pixel-space generation (2-4 NFEs), CNA reduces FID by over 50\\% compared to standard rectified flow, and by at least 24\\% against Optimal Transport baselines.","authors":["Lennart Wittke","Vinicius Azevedo"],"published":"2026-09-16T11:21:31Z","updated":"2026-09-16T11:21:31Z","abstract_url":"https://arxiv.org/abs/2609.18488v1","html_url":"https://arxiv.org/html/2609.18488v1","pdf_url":"https://arxiv.org/pdf/2609.18488v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18487v1","title":"ActionPiece: Rethinking Action Tokenization for Autoregressive Vision-Language-Action Models","abstract":"Action tokenizers play a central role in autoregressive vision-language-action (VLA) models, determining both the targets for policy training and the executable commands recovered from predicted tokens. Their fidelity is commonly evaluated using pointwise reconstruction metrics such as mean squared error (MSE), yet small individual errors do not fully characterize how faithfully action adjustments across demonstrations are preserved. After compression, similar actions may still cluster around a representative motion, while the adjustments needed for different contexts are diminished, distorted, or even reversed. We introduce physical rank consistency (PRC) to measure how well tokenization preserves local physical distance rankings after reconstruction. Evaluating decoded actions provides a common reference across token vocabularies and decoder architectures, complementing pointwise accuracy with a measure of relational fidelity. We further present ActionPiece, which preserves physical action relationships through joint supervision of representation learning and quantization. Physical rank preservation supervises near-far ordering in encoder and quantized feature distances, while quantization regularization applies the same ordering to codeword assignment distributions. Both objectives augment reconstruction, producing discrete action tokens for standard autoregressive policy learning and execution through a frozen decoder. Under the same Qwen3-VL-4B policy training setup, ActionPiece achieves 94.8% on LIBERO and 68.8% on unseen LIBERO-Plus, with additional evaluations reaching 71.9% on SimplerEnv and 51.5% across VLA-Arena L0-L2. Component ablations show that the two objectives jointly improve PRC and policy success, demonstrating the value of physical relationship supervision for action tokenization.","authors":["Shijie Lian","Bin Yu","Zhaolong Shen","Xiaopeng Lin","Yichao Du","Zhirui Zhang","Laurence T. Yang","Kai Chen"],"published":"2026-09-16T11:19:54Z","updated":"2026-09-16T11:19:54Z","abstract_url":"https://arxiv.org/abs/2609.18487v1","html_url":"https://arxiv.org/html/2609.18487v1","pdf_url":"https://arxiv.org/pdf/2609.18487v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18473v1","title":"CADSplat: Sparse-View 3D Gaussian Splatting Aided by CAD Models for Robust, Photorealistic Digital-Twin Reconstruction","abstract":"We present CADSplat, a framework that reconstructs photorealistic, geometrically accurate digital twins from sparse ($<15$ views), wide-baseline posed images of an object by regularizing 3D Gaussian Splatting (3DGS) with an explicit CAD shape prior. Using such a prior requires finding a CAD model whose shape resembles the object depicted in the images and determining the pose of each camera relative to the object. We obtain both by matching segmented object silhouettes against silhouettes rendered from a CAD library and keeping the camera-to-object poses of the best-matching model. We then anchor 3D Gaussian primitives to the surface of the retrieved model and jointly optimize the 3DGS parameters, the camera-to-object registration, and a non-rigid deformation field to account for shape differences between the physical object and the CAD model. Across two real-world datasets, CADSplat outperforms unconstrained, few-shot, and mesh-texturing baselines and degrades gracefully to as few as 3 views. Our experiments show that most of the gain in rendering quality comes from how the splats are constrained---a fixed set of splats tied to a surface and moved by a single smooth deformation field---rather than from the CAD shape itself. The CAD model adds shape knowledge where views are scarcest, in the sparsest captures and on strongly self-occluded objects, and it places every camera in the object's own frame. This enables applications beyond novel-view synthesis, such as markerless augmented reality registration, per-image object pose estimation, physical simulations, and the transfer of part labels from the design to the reconstruction.","authors":["Kristof Overdulve","Lode Jorissen","Nick Michiels"],"published":"2026-09-16T11:07:21Z","updated":"2026-09-16T11:07:21Z","abstract_url":"https://arxiv.org/abs/2609.18473v1","html_url":"https://arxiv.org/html/2609.18473v1","pdf_url":"https://arxiv.org/pdf/2609.18473v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18465v1","title":"GeoCond: A Conditioning-Aware Reliability Adapter for Feed-Forward 3D Reconstruction","abstract":"Feed-forward 3D foundation models such as VGGT predict cameras, depth, and point maps in a single pass, but can fail silently under low overlap, low parallax, and extreme relative rotation. Stratified analyses over these factors show that these failures are governed by geometric conditioning and are poorly captured by native aleatoric confidence. We introduce GeoCond, a lightweight reliability adapter for frozen feed-forward 3D backbones. GeoCond reads the backbone's predicted geometry and outputs pose-level uncertainty and a refinement gate. During training, it can be supervised by frame-permutation orbit variance, ground-truth pose error when labels are available, or cycle residuals from unlabelled independent pose graphs. At inference, the default head requires only one backbone pass and a small MLP. On VGGT, GeoCond improves out-of-distribution (OOD) AUSE (area under the sparsification-error curve; lower is better) from $0.32$ to $0.20$ over native confidence, transfers zero-shot to outdoor extreme-view scenes, and avoids the collapse caused by applying bundle adjustment uniformly. Across multiple backbones, cycle-distilled variants provide a ground-truth-free adaptation route, including cases where permutation variance vanishes on equivariant models. The same reliability signal supports gated refinement, pose-graph weighting, calibration, curation, and capture decisions. Reliable feed-forward 3D reconstruction requires not only predicting geometry, but also knowing when that geometry should be trusted.","authors":["David Ahmedt-Aristizabal","Mohammad Ali Armin","Russell Tsuchida","Lars Petersson"],"published":"2026-09-16T11:00:01Z","updated":"2026-09-16T11:00:01Z","abstract_url":"https://arxiv.org/abs/2609.18465v1","html_url":"https://arxiv.org/html/2609.18465v1","pdf_url":"https://arxiv.org/pdf/2609.18465v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18462v1","title":"CSWAM: Better Causal Semantic Representations for Out-of-Distribution Generalization in World Action Models","abstract":"FastWAM-style world action models enable efficient action-only inference, but generalize poorly under visual distribution shifts. Their reconstruction-oriented representations emphasize appearance-specific details, limiting generalization to unseen scenes and objects. Without observation history, the model also lacks temporal evidence for robustly identifying task-relevant state changes and motion in unfamiliar visual conditions. To address these limitations, we present the Causal Semantic World Action Model (CSWAM), which augments FastWAM with a causal semantic expert built on V-JEPA 2.1. V-JEPA provides temporally grounded representations of semantic state changes and motion with less dependence on appearance-specific details. The expert learns their future evolution from a sparse history of current and past observations and shares the history-derived context with both the video and action streams through causal attention. At inference, CSWAM conditions action denoising on the current video state and observed semantic history, retaining efficient action-only inference. We conduct simulation and real-robot experiments to evaluate generalization under distribution shifts. With embodied pretraining, CSWAM raises Randomized success on RoboTwin 2.0 Clean-to-Randomized transfer from 10.16% to 45.18%, a gain of 35.02 percentage points over FastWAM. Across two real-robot tasks and three OOD difficulty levels, CSWAM improves average success over FastWAM by 42.5 percentage points, from 27.5% to 70.0%.","authors":["Tianbin Liu","Jian Zhu","Taiyi Su","Jianjun Zhang","Chong Ma","Zitai Huang","Yi Xu"],"published":"2026-09-16T10:56:39Z","updated":"2026-09-16T10:56:39Z","abstract_url":"https://arxiv.org/abs/2609.18462v1","html_url":"https://arxiv.org/html/2609.18462v1","pdf_url":"https://arxiv.org/pdf/2609.18462v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18444v1","title":"DR.WILSS: Diffusion-Based Replay for Weakly Supervised Continual Semantic Segmentation","abstract":"Weakly supervised class-incremental semantic segmentation (WILSS) aims to train a segmentation model over multiple steps, each introducing new concepts to be learned with only image-level supervision. We introduce DR.WILSS, an innovative approach to address catastrophic forgetting in continual learning using diffusion-based generative replay. Our framework leverages language clues to guide the diffusion process, employing self-inpainting and regularization techniques to efficiently produce replay data, aiding the learning process. By generating high-quality replay data, the information from previously learned classes can be preserved during continual updates, a critical challenge in incremental learning scenarios. To further align the statistics of replay data with those of training samples, we apply LoRAs to the generative model. Experimental results demonstrate state-of-the-art performance across multiple benchmarks and generative architectures, while avoiding storage of training data and the use of additional resource-demanding tools during training. The proposed technique enables an optimal tradeoff between training complexity and inference-time accuracy, making DR.WILSS a promising solution for real-world applications.","authors":["Leon Arthur Marx","Francesco Barbato","Matteo Caligiuri","Pietro Zanuttigh"],"published":"2026-09-16T10:33:51Z","updated":"2026-09-16T10:33:51Z","abstract_url":"https://arxiv.org/abs/2609.18444v1","html_url":"https://arxiv.org/html/2609.18444v1","pdf_url":"https://arxiv.org/pdf/2609.18444v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18432v1","title":"Occluded Gait Recognition with Mixture of Experts: An Action Detection Perspective","abstract":"Extensive occlusions in real-world scenarios pose challenges to gait recognition due to missing and noisy information, as well as body misalignment in position and scale. We argue that rich dynamic contextual information within a gait sequence inherently possesses occlusion-solving traits: 1) Adjacent frames with gait continuity allow holistic body regions to infer occluded body regions; 2) Gait cycles allow information integration between holistic actions and occluded actions. Therefore, we introduce an action detection perspective where a gait sequence is regarded as a composition of actions. To detect accurate actions under complex occlusion scenarios, we propose an Action Detection Based Mixture of Experts (GaitMoE), consisting of Mixture of Temporal Experts (MTE) and Mixture of Action Experts (MAE). MTE adaptively constructs action anchors by temporal experts and MAE adaptively constructs action proposals from action anchors by action experts. Especially, action detection as a proxy task with gait recognition is an end-to-end joint training only with ID labels. In addition, due to the lack of a unified occluded benchmark, we construct a pioneering Occluded Gait database (OccGait), containing rich occlusion scenarios and annotations of occlusion types. Extensive experiments on OccGait, OccCASIA-B,Gait3D and GREW demonstrate the superior performance of GaitMoE.OccGait is available at https://github.com/BNU-IVC/OccGait.","authors":["Panjian Huang","Yunjie Peng","Saihui Hou","Chunshui Cao","Xu Liu","Zhiqiang He","Yongzhen Huang"],"published":"2026-09-16T10:24:31Z","updated":"2026-09-16T10:24:31Z","abstract_url":"https://arxiv.org/abs/2609.18432v1","html_url":"https://arxiv.org/html/2609.18432v1","pdf_url":"https://arxiv.org/pdf/2609.18432v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18430v1","title":"StrucPhysVideo: Learning Physical Dynamics from Structured Captions and Robot Actions","abstract":"Modeling physical dynamics, including how objects move, interact, and change state, is central to video world models for embodied AI. We present StrucPhysVideo, a family of video world models that bridges physics-focused data curation with language- and action-conditioned prediction of scene evolution. Our data pipeline combines motion-aware video segmentation, quality and content filtering, and physical relevance verification with structured annotations of objects, materials, and temporally localized interactions. By disentangling camera motion from object behavior and explicitly describing contact, deformation, and state transitions, the pipeline provides supervision grounded in observable physical events. Building on these data, we introduce StrucPhysVideo-TI2V, a sparse Mixture-of-Experts (MoE) text-image-to-video model trained with a curriculum that progressively emphasizes physical dynamics while retaining general-domain video data. StrucPhysVideo-TI2V achieves state-of-the-art performance on Physics-IQ Verified, scoring 45.5% and outperforming Cosmos3-Super-Image2Video by 2.8 percentage points. Caption ablations across backbones further demonstrate the effectiveness of physics-focused supervision. We further extend StrucPhysVideo-TI2V to StrucPhysVideo-IA2V, an interactive image-action-to-video world model that predicts visual outcomes from robot end-effector commands. Action conditioning, causal autoregressive generation, and few-step distillation enable incremental robot rollouts with only four denoising steps. Together, StrucPhysVideo advances physical dynamics modeling from image- and language-conditioned video prediction toward action-driven interaction.","authors":["Awomo-WM Team",":","Enhui Ma","Kaiwen Guo","Tingrui Zhang","Wei Song","Yingshui Tan","Jianhua Xu","Tong Zhang","Kaicheng Yu"],"published":"2026-09-16T10:23:00Z","updated":"2026-09-16T10:23:00Z","abstract_url":"https://arxiv.org/abs/2609.18430v1","html_url":"https://arxiv.org/html/2609.18430v1","pdf_url":"https://arxiv.org/pdf/2609.18430v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18413v1","title":"Vocabulary-Guided Gait Recognition","abstract":"What is a gait? Appearance-based gait networks consider a gait as the human shape and motion information from images. Model-based gait networks treat a gait as the human inherent structure from points. However, the considerations remain vague for humans to comprehend truly. In this work, we introduce a novel paradigm Vocabulary-Guided Gait Recognition, dubbed Gait-World, which attempts to explore gait concepts through human vocabularies with Vision-Language Models (VLMs). Although VLMs have achieved the remarkable progress in various vision tasks, the cognitive capability regarding gait modalities remains limited. The success element in Gait-World is the proper vocabulary prompt where this paradigm carefully selects gait cycle actions as Vocabulary Base, bridging the gait and vocabulary feature spaces and further promoting human understanding for the gait. How to extract gait features? Although previous gait networks have made significant progress, learning solely from gait modalities on limited gait databases makes it difficult to learn universal gait features for practicality. Therefore, we propose the first Gait-World model, dubbed α-Gait, which guides the gait network learning with vocabulary knowledge from VLMs. However, due to the heterogeneity of the modalities, directly integrating vocabulary and gait features is highly challenging as they reside in different embedding spaces. To address the issues, α-Gait designs Vocabulary Relation Mapper and Gait Fine grained Detector to map and establish vocabulary relations in the gait space for detecting corresponding gait features. Extensive experiments on CASIA-B, CCPG, SUSTech1K, Gait3D and GREW reveal the potential value and research directions of vocabulary information from VLMs in the gait field.","authors":["Panjian Huang","Saihui Hou","Chunshui Cao","Xu Liu","Yongzhen Huang"],"published":"2026-09-16T10:07:20Z","updated":"2026-09-16T10:07:20Z","abstract_url":"https://arxiv.org/abs/2609.18413v1","html_url":"https://arxiv.org/html/2609.18413v1","pdf_url":"https://arxiv.org/pdf/2609.18413v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18406v1","title":"Prosthesis-Aware 3D Human Pose Estimation: A Dataset and Benchmark for RSP Users","abstract":"Recovering 3D human body motion from video is important for applications such as rehabilitation assessment and sports performance evaluation. For prosthesis users, this requires capturing both natural body joints and the geometry of the prosthetic device, a challenge that existing methods are not designed to address. Model-based estimators rely on body models trained on non-amputee individuals and cannot represent prosthesis geometry, while model-free methods lack body kinematic priors and are unreliable under occlusion. This challenge is particularly prominent for users of running-specific prostheses (RSPs), where the RSP has a complex curved geometry and moves dynamically during exercise. To fill this gap, we collect RSP3D, the first 3D dataset of RSP users, covering essential daily-life and exercise actions from participants with varied amputation conditions, using a multi-camera marker-based motion capture setup. We formally define the task of prosthesis-aware 3D pose estimation, evaluate representative methods in a zero-shot setting, and confirm their individual limitations. We further propose a hybrid baseline combining model-based body joint estimation with model-free RSP shape recovery, establishing a starting point for future research.","authors":["Yilin Wen","Kechuan Dong","Fumiya Suginaka","Ken Endo","Yusuke Sugano"],"published":"2026-09-16T09:59:54Z","updated":"2026-09-16T09:59:54Z","abstract_url":"https://arxiv.org/abs/2609.18406v1","html_url":"https://arxiv.org/html/2609.18406v1","pdf_url":"https://arxiv.org/pdf/2609.18406v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18393v1","title":"MSR: Multiple Subject Reference for Video Generation","abstract":"Conditioning a video generator on multiple images requires preserving appearance while associating each reference with its intended role. We present MSR (Multiple Subject Reference), a slot-aware conditioning scheme for LTX-based video generation. Each reference image is independently encoded as a static clip and represented by a separate latent-token group. A compact Fourier-feature multilayer perceptron adds a numeric slot embedding, while slot-dependent temporal offsets modify the group's rotary coordinates. The reference groups are prepended to noisy target tokens and serve as clean context during target-only flow-matching training. We implement this scheme through low-rank adaptation and release the resulting weights and inference workflows. Qualitative examples demonstrate compositions containing distinct characters and referenced environments in realistic and stylized scenes. Development observations suggest reduced reference confusion relative to an earlier continuous-reference baseline, while similar clothing, complex garments, and viewpoint changes remain challenging. We describe the conditioning mechanism, the retained training configuration, and the observed strengths and limitations of the released system. A supplementary audio-reference experiment adds voice conditioning while keeping the visual parameters frozen.","authors":["Guannan Li","Jiaji Chen","Jingyuan Liao","Yu Geng","Baolan Qiu"],"published":"2026-09-16T09:51:50Z","updated":"2026-09-16T09:51:50Z","abstract_url":"https://arxiv.org/abs/2609.18393v1","html_url":"https://arxiv.org/html/2609.18393v1","pdf_url":"https://arxiv.org/pdf/2609.18393v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18363v1","title":"Online Multi-Camera 3D Tracking via ID Prediction over Recurrent Sparse Queries","abstract":"Online multi camera 3D tracking must maintain scene global identities across synchronized views, yet query-based trackers carry these identities only implicitly in the instance bank, where they fragment upon query interruption. We present an online architecture that recovers association accuracy by predicting IDs explicitly over recurrent sparse queries. An outside-in Sparse4D detector fuses calibrated views into world frame 3D detections while propagating a sparse query bank, and a causal MOTIP ID decoder associates detections against a finite trajectory memory. We adapt MOTIP's relative-ID prediction and recycled slot runtime to globally fused 3D observations, and introduce metric spatial gating and proximity based newborn recovery. On the official 2026 AI City Challenge Track 1 test set, our method raises HOTA from 29.63 with native instance bank identities to 38.01, primarily through an AssA increase from 20.83 to 31.10, and ranks third on the public leaderboard. Full-sequence validation over all 9,000 frames of each scene shows that decoupled ID training improves HOTA over native identities, whereas continuing detector training alongside the detached ID objective produces scene-dependent gains and losses.","authors":["Pragyan Shrestha","Haruto Nakayama","Atom Scott"],"published":"2026-09-16T09:21:25Z","updated":"2026-09-16T09:21:25Z","abstract_url":"https://arxiv.org/abs/2609.18363v1","html_url":"https://arxiv.org/html/2609.18363v1","pdf_url":"https://arxiv.org/pdf/2609.18363v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18345v1","title":"Visual Input and Its Framing Affect Attribute-based Descriptions Produced by Large Vision-Language Models","abstract":"Large vision-language models (LVLMs) are commonly used with only a single text prompt as the input, or plus an image. In this paper, we demonstrate that when the image exists, even if the text prompt is not about the specific instance (but only the concept it belongs to) in that image, the response would still be affected. For example, when the text prompt only asks for the attribute descriptions of a dog breed, an image depicting a specific dog from that breed would shift the response. Further, how the specific instance is framed in that image would determine towards which the response shifts. Detailed analyses also reveal that in the response, physical terms increase from 18% for text-only to 45% (40%) for subject-focused (subject-in-situation) framings. Overall, the unexpected effects of visual cues on LVLMs highlight the need to understand the presence of an image and its framing when evaluating the robustness of LVLMs.","authors":["Xiaomeng Wang","Martha Larson","Zhengyu Zhao"],"published":"2026-09-16T09:08:57Z","updated":"2026-09-16T09:08:57Z","abstract_url":"https://arxiv.org/abs/2609.18345v1","html_url":"https://arxiv.org/html/2609.18345v1","pdf_url":"https://arxiv.org/pdf/2609.18345v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18336v1","title":"Pose2Muscle: Structured Spatio-Temporal Decoding for Discrete Muscle Activity Estimation from Human Pose","abstract":"Muscle activity is fundamental to human movement, and understanding its patterns is critical for injury prevention and rehabilitation. Conventional muscle activity monitoring relies on specialized sensors such as surface electromyography, which limits its practicality for long-term real-world use. Existing studies suggest that muscle-related information can be inferred from human pose. However, the substantial gap between externally observable pose and internal muscle activation, limits the accuracy and generalization of current approaches. In this study, we propose Pose2Muscle, a pose-driven framework for discrete muscle activity estimation without requiring sEMG signals at inference time. Instead of directly regressing continuous sEMG signals, Pose2Muscle reformulates muscle estimation as a structured prediction problem over discrete muscle activity states, yielding a more stable and interpretable target space. The framework combines multi-scale spatio-temporal attention to capture motion patterns at complementary spatial and temporal scales with a directed acyclic graph-based decoder that maintains multiple candidate muscle-state hypotheses and performs structured trajectory inference over time. To support this task, we construct PoseEMG-43, a synchronized pose-sEMG dataset containing 2,992 movement instances from 43 daily-life actions performed by 14 participants. Experiments show that Pose2Muscle consistently outperforms representative retrieval- and pose-based baselines. It achieves an Adjacent-level Accuracy of 86.36% and a Pearson correlation coefficient of 0.8821 under the Random Split, and 63.97% and 0.6795, respectively, under the Subject-Level Split. These results demonstrate the feasibility of inferring structured muscle-state patterns from human pose and suggest the potential of Pose2Muscle for muscle-aware movement analysis when direct physiological sensing is impractical","authors":["Yuepeng Chen","Jiehong Shi","Kaili Zheng","Boyi Zhang","Chenyi Guo","Ji Wu","Xiangling Fu"],"published":"2026-09-16T08:58:45Z","updated":"2026-09-16T08:58:45Z","abstract_url":"https://arxiv.org/abs/2609.18336v1","html_url":"https://arxiv.org/html/2609.18336v1","pdf_url":"https://arxiv.org/pdf/2609.18336v1.pdf","matched_keywords":["retrieval","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18323v1","title":"Can MiniMax-H3 Reason About the Physical World? An Evaluation of Omni-Modal Generative Model","abstract":"Recent Omni-Modal Generative Models (Omni-Models) have advanced content generation toward unified modeling of text, images, video, and audio. MiniMax-H3 exemplifies this transition by combining multimodal context understanding with joint audio-visual generation in a shared latent framework. Its unified architecture raises a fundamental question: Can multimodal alignment improve the model's world reasoning, and what new evaluation paradigms do omni-modal inputs enable? To investigate this question, this work introduces a comprehensive evaluation framework organized around four complementary dimensions of physical world reasoning. Unlike existing evaluation frameworks for video generation and world models, which are often constrained by limited input modalities and evaluation settings where prompts closely match the target video content, our evaluation is specifically designed to exploit the multimodal inputs of Omni-Model. We construct a diverse set of novel tasks that require models to integrate complementary information across modalities. Specifically, we consider four scenarios, including implicit prompts paired with multiple frames, audio-image, prefix-videos, and audio-video inputs. Every single modality provides only partial evidence about the underlying event, requiring the model to jointly reason over the complementary semantic cues to infer latent event states and future dynamics. Across 517 evaluation instances, MiniMax-H3 achieves an overall success rate of 41.97%. Video-based Decision Reasoning yields the highest success rate at 56.00%, while Audio-based Disambiguation Reasoning is the weakest, reaching only 27.40%. These results indicate that effective multimodal integration remains key to fully exploiting the benefits of diverse input modalities. The project is available at https://github.com/gulucaptain/MiniMax-H3-Reason.","authors":["Haoyu Zhao","Zihao Zhao","Tianyu Deng","Ziqin Xu","Zihao Zhang","Xudong Wang","Jinxiang Guo","Chen Gao","Ziyi Ye","Yeying Jin","Jiaxi Gu","Zuxuan Wu","Shuicheng Yan"],"published":"2026-09-16T08:43:11Z","updated":"2026-09-16T08:43:11Z","abstract_url":"https://arxiv.org/abs/2609.18323v1","html_url":"https://arxiv.org/html/2609.18323v1","pdf_url":"https://arxiv.org/pdf/2609.18323v1.pdf","matched_keywords":["video","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18260v1","title":"MS-RFD: Multi-Signal Release Frame Detection in Hammer Throw from Reconstructed 3D Trajectories","abstract":"Recent advances in artificial intelligence and computer vision are reshaping sports performance analysis by enabling automated detection, tracking, and performance analysis. In hammer throw, performance is strongly determined by the kinematic conditions at release, particularly release speed, release angle, and release height. However, identifying the release instant from video typically requires manual frame-by-frame inspection, which is subjective and cumbersome in real-world training scenarios. In this paper, we present a fully automatic multi-signal release frame detection (MS-RFD) method for hammer throw using reconstructed 3D hammer trajectories. The proposed method integrates four complementary kinematic signals: speed dynamics, angular velocity transition, radial distance relative to the rotation center, and post-release trajectory linearity. These signals are fused to score and verify candidate release frames. MS-RFD is evaluated through the throwing-distance estimation error obtained from the release parameters estimated at the detected frame. An ablation study analyzes the contribution of each signal and compares alternative candidate selection strategies. The results show that speed dynamics and radial expansion provide the strongest signals for release frame detection, while angular velocity and post-release linearity provide smaller refinements.","authors":["Ahmed Endris Hasen","Nikolaos Passalis","Tomi Vanttinen","Jenni Raitoharju"],"published":"2026-09-16T07:38:59Z","updated":"2026-09-16T07:38:59Z","abstract_url":"https://arxiv.org/abs/2609.18260v1","html_url":"https://arxiv.org/html/2609.18260v1","pdf_url":"https://arxiv.org/pdf/2609.18260v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18259v1","title":"${M}^2$Tok: Multi-head Multi-codebook Discrete Action Tokenization for Vision-Language-Action Models","abstract":"Recent advancements have successfully adapted autoregressive language models to process multimodal signals, such as images and actions. Since raw action signals are continuous, effective tokenization is essential to map high-dimensional inputs into compact discrete tokens for autoregressive processing. However, existing discrete action tokenizers often suffer from high reconstruction loss, failing to preserve the fine-grained dynamics required for precise control. This ``discretization bottleneck'' significantly limits the performance ceiling of downstream Vision-Language-Action (VLA) models. To address this, we propose $\\mathcal{M}^2$Tok, a Multi-head Multi-codebook Action Tokenizer designed to minimize reconstruction error and enhance policy performance. Our approach introduces two key structural innovations: (1) we decompose the latent action features into multiple heads, enabling the model to implicitly align specific heads with distinct action dimensions; (2) we assign independent codebooks to each head for quantization. By leveraging the combinatorial nature of multiple codebooks, we significantly expand the representational expressivity of the tokenizer, leading to substantially lower reconstruction loss compared to previous methods. We evaluate the $\\mathcal{M}^2$Tok-based VLA on the RoboTwin, Simpler-Env, and 3 zero-shot real-world tasks. Experimental results demonstrate our method not only achieves superior reconstruction fidelity but also significantly boosts the success rate of VLA models. Comprehensive ablation studies further confirm the effectiveness of the multi-head and multi-codebook mechanisms. Code is available at \\href{https://github.com/cpaaax/M2Tok}{https://github.com/cpaaax/M2Tok}.","authors":["Chunpu Xu","Zhixuan Liang","Yuhao Zhang","Chi-Min Chan","Jessie Wang","Yang Xiao","Mengkang Hu","Xiaokang Yang","Yao Mu"],"published":"2026-09-16T07:38:41Z","updated":"2026-09-16T07:38:41Z","abstract_url":"https://arxiv.org/abs/2609.18259v1","html_url":"https://arxiv.org/html/2609.18259v1","pdf_url":"https://arxiv.org/pdf/2609.18259v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18239v1","title":"Unified Response Geometry for Structured Pruning","abstract":"Structured pruning is commonly formulated as ranking individual channels, although channel responses can be complementary or cancel through downstream mixing. Motivated by these response interactions, we formulate pruning as the selection of a subset with large joint response capacity, followed by a separate functional realization step. Our unified response geometry maps each candidate set to \\(M(D,R)=D^{1/2}RD^{1/2}\\) and uses its determinant together with Schur-greedy residuals to select non-redundant coordinates. The same construction yields two information-conditioned instances: an unlabeled instance based on activation covariance, and a task-conditioned instance that combines activation and gradient variance for response scale with gradient correlation for complementarity. To convert the selected subset into an executable network, we fold predictable removed responses into successor weights through ridge compensation and recalibrate batch-normalization statistics, without fine-tuning the network. On ImageNet ResNet-50, the unlabeled instance reaches \\(65.4\\%\\) and \\(53.9\\%\\) Top-1 accuracy at 30\\% and 40\\% deletion, versus \\(59.8\\%\\) and \\(43.1\\%\\) for strength-only selection; the task-conditioned instance reaches \\(67.7\\%\\) and \\(56.3\\%\\) under the same protocol. A six-family screen shows architecture-dependent behavior, with positive relative contrasts in several convolutional and expansion-layer settings and clear boundary cases in windowed attention. These results support response geometry as a conditional principle for structured pruning, with its benefit determined jointly by the observed response and the architecture in which that response is realized.","authors":["Kaixiang Shu"],"published":"2026-09-16T07:15:09Z","updated":"2026-09-16T07:15:09Z","abstract_url":"https://arxiv.org/abs/2609.18239v1","html_url":"https://arxiv.org/html/2609.18239v1","pdf_url":"https://arxiv.org/pdf/2609.18239v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18206v1","title":"CapMap-MS-TTA: 3rd Place Solution for the MUMU Track of the 8th LSVOS Challenge at ECCV 2026","abstract":"The MUMU track of the 8th Large-scale Video Object Segmentation (LSVOS) Challenge requires a single unified multimodal model to jointly solve image tagging (Task A), open-vocabulary object detection (Task B), and English captioning (Task C) under strict resource constraints (<=0.5B parameters and <=8 GB peak GPU memory). We present CapMap-MS-TTA, a training-free submission built on Microsoft Florence-2-base (~231M parameters), combining caption keyword mapping with multi-scale flip test-time augmentation. Task C uses the native <DETAILED_CAPTION> pathway with length/token sanitization. Task A maps the same detailed caption into the official quality/scene/event vocabularies via an expanded keyword lexicon with whole-word matching and a lightweight expand-hints stage. Task B runs Florence-2 open detection (<OD>) with multi-scale and horizontal-flip test-time augmentation (TTA), followed by label-aware non-maximum suppression (NMS). Without fine-tuning, the system improves our reproduced Florence-2 baseline from 15.16 to a best public score of 16.4815, and ranks 3rd on the final MUMU leaderboard.","authors":["Chengfeng Qiu","Kaifeng Wei"],"published":"2026-09-16T06:38:23Z","updated":"2026-09-16T06:38:23Z","abstract_url":"https://arxiv.org/abs/2609.18206v1","html_url":"https://arxiv.org/html/2609.18206v1","pdf_url":"https://arxiv.org/pdf/2609.18206v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18139v1","title":"Multi-View Mixture-of-Experts with Vision-Language Reranking for Cross-View Object Geo-Localization","abstract":"Cross-view object geo-localization (CVOGL) locates a target in satellite imagery using drone or street-view queries. Existing methods train separate detectors for each viewpoint, leading to parameter redundancy and impeding cross-view knowledge sharing. Moreover, top-ranked satellite candidates are often visually similar, so visual appearance and categorical labels alone are insufficient to resolve such ambiguity. To address these, we propose MVLGeo, an efficient framework designed to unify multiple viewpoints and reduce model redundancy. First, we introduce environmental contextual text from the query view as cues to distinguish visually similar candidates via Vision-Language Reranking (VL-Rerank). Second, we design a multi-view Mixture-of-Experts architecture (MV-MoE) with a shared encoder and view-specific experts to reduce redundancy and promote knowledge sharing, while cross-view contrastive learning aligns their representations for consistency. Third, we introduce an adaptive elliptical prior (ESAM-Prior) as auxiliary positional encoding for anisotropic geometric perception. Extensive experiments on the CVOGL benchmarks confirm that MVLGeo, as a unified model for multiple query viewpoints, achieves state-of-the-art performance, demonstrating robustness to input degradation and generalization across viewpoints. Code and models will be available on GitHub to facilitate future work.","authors":["Xuyu Fan","Qi Ming","Zhu Han","Liuqian Wang","Siyuan Cao","Xiaohan Zhang","Xudong Zhao","Mingjing Zhao","Yuhan Zhang"],"published":"2026-09-16T05:21:54Z","updated":"2026-09-16T05:21:54Z","abstract_url":"https://arxiv.org/abs/2609.18139v1","html_url":"https://arxiv.org/html/2609.18139v1","pdf_url":"https://arxiv.org/pdf/2609.18139v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18129v1","title":"MCLC-NET: Multimodal Continual Learning for Leaf Counting","abstract":"Leaf counting is an important task in plant phenotyping for monitoring plant growth and estimating crop yield. Most existing methods rely on RGB images, but their performance is often affected by occlusion, lighting variations, and other real-world challenges. Additional modalities, such as depth and thermal images, can provide useful complementary information. However, multimodal leaf counting remains underexplored. Also, many existing methods assume that all training data are available simultaneously, which is impractical in real agricultural settings, where data is collected over time from multiple sources. To address these challenges, we propose MCLC-NET, a multimodal continual learning framework for leaf counting. It learns tasks sequentially using a memory-based strategy with a memory buffer to retain important samples from previous tasks. We also introduce MMLC, a real-world multimodal leaf-counting dataset designed for a domain incremental scenario (DIS) in CL. It contains RGB, depth, and thermal images collected across different crop types under varying environmental conditions, arranged in three orderings: crop-wise, time-wise, and mixed. Experimental results, averaged over three random seeds, demonstrate that MCLC-NET consistently outperforms existing methods across all three task orderings, achieving the lowest AMSE of 0.675$\\pm$0.027, 0.542$\\pm$0.069, and 0.745$\\pm$0.057, respectively.","authors":["Ruchi Bhatt","Pratibha Kumari","Shreya Bansal","Vedant Agnihotri","Dwarikanath Mahapatra","Mukesh Saini"],"published":"2026-09-16T05:07:52Z","updated":"2026-09-16T05:07:52Z","abstract_url":"https://arxiv.org/abs/2609.18129v1","html_url":"https://arxiv.org/html/2609.18129v1","pdf_url":"https://arxiv.org/pdf/2609.18129v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18125v1","title":"PRISM: Predictive Representation of Interaction Style and Motion for Social Robot Navigation","abstract":"Humans often observe others before interacting and adjust their behavior accordingly. Robot navigation in crowds, however, often represents pedestrians mainly by observed geometric states, leaving individual differences in interaction tendencies implicit. We propose PRISM (Predictive Representation of Interaction Style and Motion), a framework that infers interaction traits from passive observations of human-human interactions. PRISM encodes human trajectories into a continuous ordinal latent space with a transformer encoder trained by Rank-N-Contrast loss, and pairs each inferred trait with a temporal-stability score supplied to the navigation policy. In randomized crowd simulations, PRISM reduces collision rates over the geometry-only baseline and yields small improvements in navigation-time and path-length metrics. These results suggest the utility of passive latent-trait inference for social navigation in dynamic crowds.","authors":["Bo-Han Chen","Hiromu Taketsugu","Norimichi Ukita"],"published":"2026-09-16T05:01:27Z","updated":"2026-09-16T05:01:27Z","abstract_url":"https://arxiv.org/abs/2609.18125v1","html_url":"https://arxiv.org/html/2609.18125v1","pdf_url":"https://arxiv.org/pdf/2609.18125v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18124v1","title":"Aligned Consensus Teaching for Label-Efficient Oriented Object Detection in Weakly-Aligned Visible-Infrared Imagery","abstract":"Visible-infrared object detection (VIOD) detects objects with oriented bounding boxes from paired visible and infrared images. Existing methods depend on costly dual-modality annotations. Semi-supervised learning can reduce this burden, but extending it from single-modal detection to VIOD is challenging. In the practical image-pair-level setting considered here, only a few pairs are labeled in both modalities, while the rest are completely unlabeled. This limited supervision creates three challenges: (i) too few labeled boxes for robust cross-modal alignment; (ii) pseudo-label errors caused by branch-wise misses accumulate during self-training; and (iii) tail-class annotations become critically scarce as the labeling budget decreases. We propose Aligned Consensus Teacher (ACT) for label-efficient VIOD in this setting. Its Cycle-Consistent Region Alignment (CRA) combines cycle consistency and sparse anchors with reliability-weighted regional matching. Cross-Modal Consensus Mean-Teacher (CMC-MT) forms consensus pseudo labels under pair-preserving views to recover branch-wise misses and supervise unlabeled pairs. Text-Guided Cross-Modal Instance Augmentation (TG-CMIA) uses a vision-language scene prior to compose tail-class instance pairs while preserving RGB--IR offsets. To the best of our knowledge, ACT is the first framework to study semi-supervised VIOD under this image-pair-level setting. Experiments on DroneVehicle and VEDAI show consistent gains across annotation ratios. With 10\\% labeled pairs on DroneVehicle, ACT reaches 94.3\\% of the mAP obtained by the same detector under full supervision. Code and models will be available on GitHub to facilitate future work.","authors":["Qi Ming","Xiaxin Yuan","Jiahuan Zhou","Jiangmeng Li","Xudong Zhao","Zhanchao Huang","Juan Fang","Shaoguang Huang","Aleksandra Pizurica"],"published":"2026-09-16T04:59:37Z","updated":"2026-09-16T04:59:37Z","abstract_url":"https://arxiv.org/abs/2609.18124v1","html_url":"https://arxiv.org/html/2609.18124v1","pdf_url":"https://arxiv.org/pdf/2609.18124v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18111v1","title":"A Comprehensive Review of Generative Physical Artificial Intelligence","abstract":"The integration of large-scale foundation models with physical embodiments has led to significant advancements in robotics known as Generative Physical Artificial Intelligence (GPAI). These agentic AI systems autonomously perceive, reason, and act in complex real-world situations. This survey comprehensively analyzes GPAI systems, focusing on their architectural foundations, current applications, and key limitations. We introduce a taxonomy of five distinct approaches: Robot Foundation Models (RFMs) for cross-platform skill transfer; Vision-Language Action (VLA) models for end-to-end multi-modal perception and control; Large Behavior Models (LBMs) for human-like movement generation; Diffusion Policy Models (DPMs) for diffusion model-based temporally coherent action generation; and World Foundation Models (WFMs) for physics-compliant simulation and data generation. We examine how these approaches complement each other: WFMs generate training data for VLAs and DPMs, RFMs enable cross-platform deployment of learned policies, while LBMs provide motion priors for natural behavior. Through examples across autonomous vehicles, industrial automation, healthcare robotics, and humanoid systems, we identify significant performance improvements and summarize promising research directions in data-efficient learning, sim-to-real transfer, edge-compatible architectures, and safety frameworks. These insights advance embodied AI for IoT-connected environments where intelligent agents interact with networked sensors, actuators, and edge devices.","authors":["Satyam Gaba","Krutiksinh Rana","Siva Sai","Vinay Chamola","Dusit Niyato"],"published":"2026-09-16T04:29:50Z","updated":"2026-09-16T04:29:50Z","abstract_url":"https://arxiv.org/abs/2609.18111v1","html_url":"https://arxiv.org/html/2609.18111v1","pdf_url":"https://arxiv.org/pdf/2609.18111v1.pdf","matched_keywords":["agent","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18088v1","title":"Mask 2D-3D: Adaptive Dual-Masked Autoencoder Network for Image-to-Point Cloud Registration","abstract":"Detection-free methods for image-to-point cloud registration are prone to erroneous correspondences caused by domain and modality discrepancies, limited sensitivity of feature extractors, and the presence of non-overlapping regions. The Masked Autoencoder (MAE) has shown strong performance in visual representation for images and point clouds. It may be helpful to apply this approach to image-to-point cloud registration, a task that requires unified feature extraction and accurate cross-modal correspondences. Standard MAE's random masking may overlook key regions due to limited camera views, reducing registration effectiveness. To address this, we propose the Intermodal Dual-MAE Framework (ID-MAE) with a Similarity-based RL Masking Strategy (SRLM), which adaptively masks informative positions by leveraging cross-modal similarity and reinforcement learning, thus narrowing the modality gap. Our method enhances cross-modal representation learning by enforcing representation consistency during feature extraction, thereby enabling more reliable 2D-3D correspondence estimation. Experiments on RGB-D Scenes v2 and 7-Scenes benchmarks show that our method achieves state-of-the-art performance in image-to-point cloud registration.","authors":["Zhixin Cheng","Jiacheng Deng","Xiaotian Yin","Baoqun Yin","Richang Hong","Tianzhu Zhang"],"published":"2026-09-16T03:47:07Z","updated":"2026-09-16T03:47:07Z","abstract_url":"https://arxiv.org/abs/2609.18088v1","html_url":"https://arxiv.org/html/2609.18088v1","pdf_url":"https://arxiv.org/pdf/2609.18088v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18077v1","title":"vidax: A Unified JAX Framework for Video Generative Models on Accelerator Meshes","abstract":"Open-source video generative models ship almost exclusively as PyTorch/CUDA reference implementations. This leaves Cloud TPU pods without a production-ready inference path, despite offering large, cost-effective accelerator memory pools ideal for long-sequence spatiotemporal attention. We present vidax, an open-source JAX/Flax inference engine and zero-copy PyTorch-to-JAX weight translator for modern video generation architectures. vidax covers a diverse set of spatiotemporal models --- including Diffusion Transformers, omnimodal Mixture-of-Transformers, 3D VAEs, text encoders, and native samplers --- with zero PyTorch dependency in the execution path. The framework unifies 1D tensor parallelism with DeepSpeed-Ulysses sequence parallelism on a single JAX sharding mesh, integrates TPU flash-attention kernels, and implements per-layer weight offloading to support reference resolutions that exceed single-device memory. We benchmark compile times, latency, and peak memory utilization on TPU v4-8 hardware, and document real-world numerical bugs surfaced during checkpoint translation. vidax is released open-source as a baseline for JAX and TPU video generation research.","authors":["Congyue Deng"],"published":"2026-09-16T03:26:45Z","updated":"2026-09-16T03:26:45Z","abstract_url":"https://arxiv.org/abs/2609.18077v1","html_url":"https://arxiv.org/html/2609.18077v1","pdf_url":"https://arxiv.org/pdf/2609.18077v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18069v1","title":"GeoCueFormer: Geometry-Guided Wavelet Representation and Prediction-Cued Dual-Stage Decoder for Underwater Semantic Segmentation","abstract":"Underwater semantic segmentation is essential for marine ecosystem monitoring, yet remains challenging due to severe visual degradation. Light absorption and scattering often lead to color shifts, low contrast, and blurred boundaries, making shallow detail features unreliable. Existing underwater segmentation methods improve RGB feature aggregation or boundary prediction, but still lack an explicit mechanism to distinguish structure-related details from degradation-induced responses. To address this limitation, we propose GeoCueFormer, a lightweight framework that combines geometry-constrained frequency enhancement with prediction-cued refinement. GeoCueFormer performs stage-specific wavelet enhancement on hierarchical encoder features to complement shallow boundary details while preserving deep structural semantics. A depth-derived spatial gate constrains shallow frequency enhancement toward geometry-consistent regions, and a prediction-cued dual-stage decoder further refines ambiguous high-resolution features. GeoCueFormer obtains 82.23% and 73.04% mIoU on SUIM and DUT, respectively. Under comparable model complexity and standard benchmark settings on SUIM and DUT, it achieves SOTA performance while maintaining a favorable accuracy-complexity trade-off. These results show that distinguishing structural details from degradation-induced interference is more effective for underwater segmentation.","authors":["Xian Wu","Xinjin Li","Yiliu Xu","Yining Liu","Yong Jiang"],"published":"2026-09-16T03:14:32Z","updated":"2026-09-16T03:14:32Z","abstract_url":"https://arxiv.org/abs/2609.18069v1","html_url":"https://arxiv.org/html/2609.18069v1","pdf_url":"https://arxiv.org/pdf/2609.18069v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18058v1","title":"Finder: Agentic Closed-Loop Object Finding for Embodied Grounding","abstract":"Finding the object referred to by language in a partially observed 3D scene is a core capability for embodied agents. Existing approaches either couple object search with online exploration, which can be costly when relevant observations have already been captured, or query pre-built open-vocabulary maps and scene graphs in a static, one-shot fashion. We present Finder, an agentic closed-loop object-finding primitive for embodied grounding. Instead of treating grounding as passive retrieval from a fixed scene representation, Finder maintains a typed loop state that links query-conditioned planning, scoped evidence gathering, candidate verification, and accept/continue/abort control. When evidence is incomplete or ambiguous, the loop can redirect subsequent perception and comparison rather than simply returning the top retrieved object. On open-vocabulary embodied Object Retrieval in Habitat/HM3D and real-world RGB-D scenes, Finder improves the averaged 1m success rate by 15.75 points over strong baselines. The same primitive also transfers to sequential object grounding and embodied object-centric question answering, improving spatial and temporal localization without changing the inner grounding protocol. Project page: https://finder-vln.github.io.","authors":["Shixiong Xu","Zhiyuan Chen","Song Ding","Rui Luo","Xiaowei Liang","Dongxu Miao","Zhiying Du"],"published":"2026-09-16T03:02:45Z","updated":"2026-09-16T03:02:45Z","abstract_url":"https://arxiv.org/abs/2609.18058v1","html_url":"https://arxiv.org/html/2609.18058v1","pdf_url":"https://arxiv.org/pdf/2609.18058v1.pdf","matched_keywords":["retrieval","3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18056v1","title":"Position Anchor Tuning: Towards Efficient Adaptation of Pre-Trained Point Cloud Transformers","abstract":"Parameter-efficient fine-tuning (PEFT) has recently emerged as a pivotal research direction for adapting pre-trained point cloud transformers to diverse downstream tasks. Although existing methods achieve excellent fine-tuning performance with high parameter efficiency, they ignore inference efficiency. To tackle this problem, a novel PEFT method termed position anchor tuning (PAT) is proposed in this paper. As multi-head attention (MHA) and feed-forward network (FFN) are computation-heavy blocks in pre-trained transformers, PAT decreases their computational cost through token aggregation-expansion pairs. Each pair comprises a token aggregation module (TAM) and a token expansion module (TEM). For MHA and FFN blocks, TAMs extract representative tokens from their input tokens based on position anchors in 3D space. These extracted tokens, rather than the original input tokens, are processed by the blocks, thereby reducing the number of tokens involved in computation. Then, TEMs propagate the learned representations back to the original input tokens. Since TAMs are solely responsible for capturing task-specific representations, base-sharing low-rank adaptation (BSLoRA) is further introduced to enable them to learn such representations effectively with only a small number of trainable parameters. Extensive experiments on widely used benchmarks demonstrate that PAT performs comparably to state-of-the-art methods while incurring significantly lower computational overhead and fewer trainable parameters.","authors":["Zheng Liu","Xin Gao","Jinchao Zhu","Gao Huang"],"published":"2026-09-16T02:59:29Z","updated":"2026-09-16T02:59:29Z","abstract_url":"https://arxiv.org/abs/2609.18056v1","html_url":"https://arxiv.org/html/2609.18056v1","pdf_url":"https://arxiv.org/pdf/2609.18056v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18034v1","title":"IRIS: Implicit Rendering Matters for Pose-Free Novel View Synthesis","abstract":"Novel view synthesis from unposed multi-view images remains challenging, as the model must jointly learn scene representations and camera parameters without pose supervision. Existing approaches largely fall into two extremes: implicit latent-space rendering is flexible and easy to optimize, but often yields weakly grounded camera estimation; explicit 3D representations provide stronger geometric grounding, but introduce heavier parameterization and more fragile optimization. In this paper, we present IRIS, a fully self-supervised framework that provides a practical middle ground between these two paradigms. Instead of decoding free latent tokens or reconstructing fully explicit 3D primitives, IRIS represents the scene as a latent neural field and renders novel views by querying this field under self-predicted cameras. Specifically, projected features from reference views are aggregated at sampled 3D points to form point-wise latent features, which are then composed along target rays for rendering. This design preserves the flexibility and optimization stability of implicit modeling, while introducing stronger geometric structure than unconstrained latent rendering. Extensive experiments show that IRIS achieves strong novel view synthesis quality with competitive pose accuracy under fully self-supervised learning. Our project page: https://leo-frank.github.io/IRIS","authors":["Wenyu Li","Sidun Liu","Peng Qiao","Yong Dou","Tongrui Hu"],"published":"2026-09-16T02:35:22Z","updated":"2026-09-16T02:35:22Z","abstract_url":"https://arxiv.org/abs/2609.18034v1","html_url":"https://arxiv.org/html/2609.18034v1","pdf_url":"https://arxiv.org/pdf/2609.18034v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18007v1","title":"Newer Is Not Fairer: Gender Stereotyping in Text-to-Image AI Across Model Generations","abstract":"Text-to-image generative models are widely used in professional and creative settings, yet how they represent gender across occupations -- and whether newer models are fairer -- remains poorly understood across multiple generations. We evaluate gender representation across 20 occupations, 5 prompt templates, and 4 Stable Diffusion model generations (SD 1.5, SD 2.1, SDXL, SD 3 Medium), generating 8,000 images with n = 100 per occupation-model cell (5 prompts x 20 images), and classifying all with DeepFace. Across the 8,000 open-source images, 76.4% show male subjects (95% CI [75.1%, 78.7%], p < 2.2 x 10^-16, Benjamini-Hochberg adjusted). More strikingly, 57.6% of images for historically female-coded occupations show male subjects (raw p = 3.43 x 10^-22, BH-adjusted p = 1.71 x 10^-21). All nine significant tests reported in this paper survive BH correction across 10 tests. When compared against U.S. Bureau of Labor Statistics workforce data, models underrepresent women by 20-46pp on average, with particularly large deviations for near gender-balanced occupations: scientist (48% female in BLS, 82-99% male in model outputs) and cleaner (46% female in BLS, 80-92% male in outputs). Model generations do not improve steadily: bias worsens from SD 1.5 to SDXL before partially recovering in SD 3 Medium. A preliminary comparison with GPT-image-1 on five occupations suggests lower bias than open-source models, though the practical effect is small (Cramer's V = 0.080) and the comparison is exploratory. No model achieves gender parity.","authors":["Shesh Narayan Gupta","Nik Bear Brown"],"published":"2026-09-16T01:54:12Z","updated":"2026-09-16T01:54:12Z","abstract_url":"https://arxiv.org/abs/2609.18007v1","html_url":"https://arxiv.org/html/2609.18007v1","pdf_url":"https://arxiv.org/pdf/2609.18007v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.17953v1","title":"EDCT-Bench: Uncovering Faithfulness Gaps in VLMs via Explanation-Driven Counterfactual Testing","abstract":"Vision-Language Models (VLMs) can produce Natural Language Explanations (NLEs) that sound plausible yet remain inconsistent with the visual evidence they cite. We present Explanation-Driven Counterfactual Testing (EDCT), an intervention-based protocol that extracts visual concepts cited in a model's explanation, applies verified minimal edits to them, and tests whether the resulting answer and explanation remain consistent with the edited image. Using this protocol, we create EDCT-Bench, a comprehensive benchmark spanning three complementary domains: knowledge-intensive visual question answering (OK-VQA), safety-critical driving (DriveLM), and 3D spatial reasoning (3DSRBench). Across the evaluated VLMs, EDCT reveals substantial faithfulness gaps, with models frequently producing responses inconsistent with verified visual changes. Finally, our fine-tuning study suggests that EDCT-generated counterfactuals provide high-impact training signals.","authors":["Sihao Ding","Santosh Vasa","Aditi Ramadwar","Thomas Monninger"],"published":"2026-09-16T00:25:31Z","updated":"2026-09-16T00:25:31Z","abstract_url":"https://arxiv.org/abs/2609.17953v1","html_url":"https://arxiv.org/html/2609.17953v1","pdf_url":"https://arxiv.org/pdf/2609.17953v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-09-17T05:40:01+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":61,"new_or_recent_papers":[{"id":"2609.19143v1","title":"PANORAMA: Panoptic Grounded Captioning via Mask Proposal Selection","abstract":"Intelligent systems that act in the world require image understanding that is both comprehensive and spatially grounded. Current vision-language models (VLMs) can generate fluent and detailed image captions, but reliably associating them with image pixels remains challenging. Existing methods that combine dense captioning with pixel-level grounding often produce either incomplete descriptions or inaccurate segmentation masks. We study this problem through panoptic grounded captioning, a task that requires a VLM to describe both foreground objects and background regions while grounding each referring phrase with pixel-level masks. We make three contributions. First, we introduce PanoCaps, a human-annotated benchmark constructed from panoptic segmentation datasets. It provides dense captions with near-complete pixel coverage and image-text alignments at the entity level, supporting both training and evaluation. We further propose a phrase-mask matching protocol and a generalized Panoptic Quality (gPQ) metric that jointly evaluates textual and mask agreement. Second, we formulate phrase grounding as selection from a phrase-conditioned pool of mask proposals and introduce PANORAMA, a VLM that conditions a pretrained segmenter on contextualized phrase representations to obtain candidate masks and learns to select those corresponding to each phrase. Training this interface jointly with caption generation enables PANORAMA to produce high-quality masks while allowing each phrase to refer to a single region or multiple instances. Third, PANORAMA achieves the best overall grounding on PanoCaps and matches or exceeds specialized models across several pixel-level grounding tasks. Experiments show that our method produces precise entity-level segmentations while maintaining detailed, mask-consistent captions. Code, data and models are available at https://www.di.ens.fr/willow/research/panorama/.","authors":["Sara Pieri","Evangelos Kazakos","Shizhe Chen","Josef Sivic","Cordelia Schmid"],"published":"2026-09-16T17:59:30Z","updated":"2026-09-16T17:59:30Z","abstract_url":"https://arxiv.org/abs/2609.19143v1","html_url":"https://arxiv.org/html/2609.19143v1","pdf_url":"https://arxiv.org/pdf/2609.19143v1.pdf","matched_keywords":["representation","instance"],"source_used":"html","source_text_chars":122178,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, instance 相关；摘要显示其主要贡献为：Intelligent systems that act in the world require image understanding that is both comprehensive and spatially grounded. Current vision-language models (VLMs) can generate fluent and detailed image captions, but reliably associating them with image pixels rem...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19142v1","title":"PointZero: 3D Point Track Completion for Learning Transferable 3D Dynamics","abstract":"World models endow perceptual systems with the ability to predict how scenes evolve under interaction. They are most beneficial when trained on diverse volumes of data, to instill a rich prior into downstream applications. Existing methods typically require robot action labels to learn action-conditioned 3D dynamics, which excludes web video data from the training pool. We study 3D point track completion as a pre-training objective for learning transferable 3D dynamics without robot data. Given a single RGB-D observation and sparse partial 3D trajectories (tracks), we predict future 3D tracks of all observed points. We show this objective produces a rich 3D dynamics prior, without requiring robot action labels. We contribute a diverse dataset of 2.9 million synthetic frames spanning deformable, articulated, and rigid objects, and use it to train PointZero. We show that a flexible and expressive transformer, PointZero, outperforms prior methods on the same data. We demonstrate the utility of our pre-training objective by post-training PointZero for two downstream applications: (1) action-conditioned 3D dynamics prediction and (2) imitation learning. When fine-tuned to condition on end-effector pose, PointZero outperforms the baselines on the recent PGND 3D dynamics benchmark. When fine-tuned to predict robot actions and 3D tracks, PointZero outperforms or matches the baselines on 6/7 simulated and real-world robot manipulation tasks. We furthermore evaluate training PointZero from scratch to isolate the benefits of our proposed architecture from those of our proposed pre-training objective and dataset. We release the dataset, checkpoints, and full training recipe.","authors":["Bardienus P. Duisterhof","Kaifeng Zhang","Adam Hung","Bowen Wen","Stan Birchfield","Yunzhu Li","Deva Ramanan","Jeffrey Ichnowski"],"published":"2026-09-16T17:59:30Z","updated":"2026-09-16T17:59:30Z","abstract_url":"https://arxiv.org/abs/2609.19142v1","html_url":"https://arxiv.org/html/2609.19142v1","pdf_url":"https://arxiv.org/pdf/2609.19142v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":66848,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：World models endow perceptual systems with the ability to predict how scenes evolve under interaction. They are most beneficial when trained on diverse volumes of data, to instill a rich prior into downstream applications. Existing methods typically require r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19138v1","title":"In-Context Robot Learning with VLM Agents","abstract":"Enabling robots to adapt to unfamiliar environments as readily as humans remains a moonshot goal of embodied AI. No finite collection of demonstrations can cover every task and situation a robot will encounter, making the ability to learn from context at deployment essential for generalization. Such in-context learning (ICL), however, remains largely beyond the reach of existing robotic policies. The broad agentic capabilities of commercial vision-language models (VLMs), such as GPT-6 Astra, raise a compelling question: can these models learn from demonstrations, examples, and interaction feedback, then translate that information into executable and verifiable robot behavior from a new initial state without gradient updates or persistent changes to task-specific parameters? We introduce GPT-Policy, a general-agent framework for in-context robot learning. GPT-Policy integrates a context compiler that preserves task-relevant visual transitions, a VLM that proposes robot-tool actions, and a constrained controller that verifies and executes each action and reports its outcome. We evaluate its reliability and limitations through task success and efficiency metrics, matched comparisons across models, and controlled context ablations. In real-robot trials, human video demonstrations improve task completion even without robot action labels, while aligned action references yield further gains on contact-sensitive tasks. These findings position GPT-Policy as a step toward robot adaptation through in-context learning, providing an empirical foundation for translating the general-purpose capabilities of VLMs into physical behavior and clarifying the challenges that must be overcome for reliable deployment.","authors":["Dongzhou Cheng","Taoran Yi","Ye Fang","Xingwu Zhang","Fan Feng","Yixuan Li","Gengxiong Zhuang","Rongze Wang","Shuai Yang","Wei Song","Weizhi Xue","Minyan Wu","Jie Gui","Jiaqi Wang","Tong Wu"],"published":"2026-09-16T17:58:35Z","updated":"2026-09-16T17:58:35Z","abstract_url":"https://arxiv.org/abs/2609.19138v1","html_url":"https://arxiv.org/html/2609.19138v1","pdf_url":"https://arxiv.org/pdf/2609.19138v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":96022,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：Enabling robots to adapt to unfamiliar environments as readily as humans remains a moonshot goal of embodied AI. No finite collection of demonstrations can cover every task and situation a robot will encounter, making the ability to learn from context at depl...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19122v1","title":"Adaptive Convolutional Sparse Coding via Information Bottleneck for Robust Visual Signal Representation","abstract":"Visual signals require compact yet sufficient representations for robust downstream prediction. Convolutional sparse coding (CSC) provides an explicit mechanism for suppressing redundant components while preserving signal content, but its sparsity coefficient is typically fixed and manually selected. We propose an adaptive convolutional sparse coding framework for robust visual signal representation. Specifically, we unfold the CSC optimization with the Fast Iterative Shrinkage-Thresholding Algorithm (FISTA) and treat the sparsity coefficient as a differentiable variable jointly learned with the network parameters. From the information bottleneck perspective, this coefficient controls the trade-off between information retention and compression: the sparsity term promotes compact representations, while the reconstruction term together with task loss preserves task-relevant signal content. We further introduce a label-free post-training strategy that adjusts the compression strength for corrupted inputs with the main network parameters fixed. Experiments on CIFAR and ImageNet demonstrate competitive clean-data recognition and greatly improved robustness under different input perturbations.","authors":["Meng'en Qin","Yinchen Liu","Mingxuan Cui","Youlu Xing"],"published":"2026-09-16T17:43:46Z","updated":"2026-09-16T17:43:46Z","abstract_url":"https://arxiv.org/abs/2609.19122v1","html_url":"https://arxiv.org/html/2609.19122v1","pdf_url":"https://arxiv.org/pdf/2609.19122v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":32285,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Visual signals require compact yet sufficient representations for robust downstream prediction. Convolutional sparse coding (CSC) provides an explicit mechanism for suppressing redundant components while preserving signal content, but its sparsity coefficient...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.19119v1","title":"Track, Articulate, Act: Generating Articulation from Casual Human Videos","abstract":"Human videos contain rich causal evidence for robot manipulation: they reveal how hand motion induces object motion and produces task-relevant changes in object state. In this work, we study articulated objects such as doors, drawers, cabinets, laptops, ovens, and hinged containers that are ubiquitous in daily life and present unique challenges for embodied interaction. These objects cannot be represented by a single pose; their motion depends on the underlying parts and joints. We introduce a real-to-sim framework that reconstructs a simulation-ready articulated object and hand-object interaction from a casual monocular RGB video, without RGB-D or multi-view input, prior scans, manually specified joints, or robot demonstrations. Our key insight is that dense 3D point tracks provide an embodiment-agnostic articulation cue: points on the fixed link remain approximately stationary, while points on the moving link follow coherent revolute or prismatic motion. Our method segments the links, estimates the joint and its state trajectory, reconstructs an articulated asset, and aligns the recovered 3D hand motion with the object. Central to our approach is a modular recipe that repurposes powerful pretrained models for single-image 3D reconstruction, mesh segmentation, and 3D scene flow, connecting their predictions through explicit geometric reasoning to infer articulation. We use the reconstructed articulated object and the human hand trajectory to replay interactions through contact in MuJoCo. The framework shows how pretrained vision models and explicit motion reasoning can turn casual human videos into articulated object models suitable for downstream embodied interactions. https://track-articulate-act.github.io/","authors":["Jiaming Zhang","Homanga Bharadhwaj"],"published":"2026-09-16T17:43:12Z","updated":"2026-09-16T17:43:12Z","abstract_url":"https://arxiv.org/abs/2609.19119v1","html_url":"https://arxiv.org/html/2609.19119v1","pdf_url":"https://arxiv.org/pdf/2609.19119v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":58183,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Human videos contain rich causal evidence for robot manipulation: they reveal how hand motion induces object motion and produces task-relevant changes in object state. In this work, we study articulated objects such as doors, drawers, cabinets, laptops, ovens...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:01+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18898v1","title":"NormLift: From Lifted Features To Semantic Reliability In 3D Gaussian Splatting","abstract":"Training-free weighted aggregation is widely used to lift 2D semantic features onto 3D Gaussians for open-vocabulary scene understanding, yet its theoretical role remains insufficiently understood. Existing analyses typically justify this operation from the rendering side, treating Gaussian features as linearly composable Euclidean variables for reconstructing 2D feature maps. However, this view does not match downstream 3D usage, where each Gaussian is often queried independently in a cosine-based embedding space. We revisit feature lifting from the 3D side and formulate per-Gaussian assignment as a cosine alignment problem on the CLIP unit sphere. Under this objective, the L2-normalized semantic back-projected feature emerges as the closed-form solution, providing a complementary interpretation of the standard lifting rule from the perspective of per-Gaussian semantic assignment. The same formulation further yields a norm decomposition into intra-view and inter-view consistency, suggesting that feature magnitude itself can serve as a semantic reliability signal. Calibrated by effective multi-view support, this reliability score guides a mode-voting refinement that preserves CLIP feature validity by avoiding linear averaging. Experiments on open-vocabulary 3D semantic segmentation show that NormLift is an efficient, training-free framework that achieves strong performance across evaluation protocols.","authors":["Yihan Zang","Da Li","Dominik Engel","Shinkyu Park","Ivan Viola"],"published":"2026-09-16T16:35:35Z","updated":"2026-09-16T16:35:35Z","abstract_url":"https://arxiv.org/abs/2609.18898v1","html_url":"https://arxiv.org/html/2609.18898v1","pdf_url":"https://arxiv.org/pdf/2609.18898v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":78172,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Training-free weighted aggregation is widely used to lift 2D semantic features onto 3D Gaussians for open-vocabulary scene understanding, yet its theoretical role remains insufficiently understood. Existing analyses typically justify this operation from the r...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18860v1","title":"Decodable but Misrouted: Sparse Features Uncover a Readout Gap in Vision-Language Models for Harmful Meme Detection","abstract":"When a large vision-language model misclassifies a harmful meme, the failure may reflect missing internal evidence or an inability to route represented evidence to its output. We distinguish these cases in Gemma-3 and Qwen3.5 using sparse autoencoders, role-conditioned probes, causal interventions, and recovery experiments across six harmful content benchmarks, with additional Spanish and Hindi-English code-mixed evaluations. Sparse readouts outperform native prediction on all six primary binary tasks: Qwen averages $0.740$ versus $0.432$ native macro-F1, while residual reconstruction reaches $0.486$, whereas Gemma improves from $0.532$ to $0.714$. These differences reflect supervised accessibility rather than a pre-existing, native decision rule, and the most influential token role depends on the task. Under the evaluated score scales, Qwen silent-feature ablation is $24-63$ times more probe-sensitive, whereas routed-feature patching on literal yes/no tasks is $16-140$ times more output-sensitive. Calibration-only routing recovers $93.3$% of the mean gap, and probe-distilled LoRA improves native predictions, although shared multi-task adaptation causes negative transfer. A case study of Gemma-3-12B on Facebook Hateful Memes finds a distributed rank-32 image-prompt interaction, reaching $0.756$ versus $0.685$ native macro-F1. Robustness controls show that the signal extends beyond English, is not explained solely by accompanying OCR, and depends on paired visual evidence. Thus, routing, rather than representation alone, is a recurring bottleneck in harmful meme classification.","authors":["Girish A. Koushik","Diptesh Kanojia","Helen Treharne"],"published":"2026-09-16T16:00:36Z","updated":"2026-09-16T16:00:36Z","abstract_url":"https://arxiv.org/abs/2609.18860v1","html_url":"https://arxiv.org/html/2609.18860v1","pdf_url":"https://arxiv.org/pdf/2609.18860v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":145458,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：When a large vision-language model misclassifies a harmful meme, the failure may reflect missing internal evidence or an inability to route represented evidence to its output. We distinguish these cases in Gemma-3 and Qwen3.5 using sparse autoencoders, role-c...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18844v1","title":"ReFigBench: Benchmarking Scientific Figure Reconstruction as Editable PowerPoint Artifacts","abstract":"Multimodal coding agents are expected to turn visual inputs into usable artifacts, and they act through a harness, the layer of tools, context management, and execution environment around the model. Existing evaluations often isolate short tool calls, API traces, or screenshot resemblance, and a low score under these proxies cannot say whether the model saw poorly, planned poorly, or was failed by its harness. We study scientific overview figure reconstruction, an agent task in which a source image must become an editable PowerPoint slide that preserves text, topology, layout, and native document structure. We introduce ReFigBench, a benchmark and evaluation framework built on 1,000 real overview figures retrieved from arXiv papers with full provenance. Coding agents from four model families reconstruct every figure under two workflows, direct code generation and a specialized PPTX workflow, and the strongest model runs inside two commercial harnesses, yielding ten configurations. Evaluation combines deterministic artifact checks, repeated automated scoring by judges from two model families, and blinded human comparisons. Perception remains a bottleneck that iterative rendering only partly repays. Whether workflow effort converts into quality depends on the model together with its harness, since the same model gains from the specialized workflow inside one harness and loses inside the other, and the harness shifts scores even under an identical direct prompt. The specialized workflow erases native connectors in every configuration, human judges still prefer its renderings in most matchups, and even the strongest agent falls short of the rubric ceiling. These results expose the tension between fidelity and editability as the central challenge for practical multimodal document agents.","authors":["Liyang Fan","Chi Wei","Yitai Li","Xinping Bi","Guhong Chen","Chenghao Sun","Haoxiang Yang","Qingwen Li","Kai Yan","Hong Li","Bo Li"],"published":"2026-09-16T15:51:51Z","updated":"2026-09-16T15:51:51Z","abstract_url":"https://arxiv.org/abs/2609.18844v1","html_url":"https://arxiv.org/html/2609.18844v1","pdf_url":"https://arxiv.org/pdf/2609.18844v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"html","source_text_chars":92532,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, multimodal 相关；摘要显示其主要贡献为：Multimodal coding agents are expected to turn visual inputs into usable artifacts, and they act through a harness, the layer of tools, context management, and execution environment around the model. Existing evaluations often isolate short tool calls, API tra...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18836v1","title":"Copy What Is Seen, Generate What Is Not: Training-Free Anomaly-Aware Video Restoration","abstract":"A surveillance system that detects an anomaly often has to repair the footage as well, yet the two tasks are studied in isolation: training-free anomaly detectors stop at a score or a label, while training-free video editing answers to a user prompt rather than to a detector. This paper proposes AVR (Anomaly-aware Video Restoration), which closes that gap with frozen pretrained models alone and generates content only where the clip offers no evidence to copy. Motion evidence first gates open-vocabulary proposals into spatio-temporal masks. A background prior computed from the clip then fills every pixel the anomaly ever uncovers, leaving diffusion to synthesize only what no frame showed, and a frozen verifier decides per clip whether to trust a classical, a prior-anchored, or a background-conditioned restorer. Extensive experiments on three surveillance datasets, under both full-reference anomaly injection and real anomalies, show that AVR leads full-frame fidelity under oracle masks, matches three trained video inpainters inside the edited region, and outperforms a detect-then-generate pipeline on the masks it produces itself, while suppressing both the residual anomaly and the flicker of free diffusion.","authors":["Zhida Qu","Shengchao Chen"],"published":"2026-09-16T15:43:21Z","updated":"2026-09-16T15:43:21Z","abstract_url":"https://arxiv.org/abs/2609.18836v1","html_url":"https://arxiv.org/html/2609.18836v1","pdf_url":"https://arxiv.org/pdf/2609.18836v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":47813,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：A surveillance system that detects an anomaly often has to repair the footage as well, yet the two tasks are studied in isolation: training-free anomaly detectors stop at a score or a label, while training-free video editing answers to a user prompt rather th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18823v1","title":"Using OCR Heads to Verbalize Image Semantics","abstract":"How do VLMs map from pixels to semantics? To understand this general question, we focus on a narrow one: studying how VLMs perform optical character recognition (OCR). Across four models, we identify attention heads causally necessary for OCR, and discover that these are in fact general-purpose heads that output interpretable semantic features across all image tokens. For example, pointing these heads at an image token containing the word \"bike\" causes Qwen3-VL-8B to output \"bike,\" but pointing them at a bird wing causes the model to output the token \"feathers.\" We collapse these heads' attention weights into a single verbalization lens transformation that reveals interpretable semantic features in hidden states across all layers. When combined with projection to vocabulary space, we can obtain interpretable labels starting from layer 0, showing that image representations are in fact aligned with language in early layers. We find that we can also use the inverse of this transformation to edit non-word concepts, e.g., replacing a tractor with a revolver in a naturalistic image, providing causal evidence that this subspace is useful for more than just OCR. Our results are an example of how the study of specific mechanisms can shed light on broader interpretability problems.","authors":["Sheridan Feucht","Benno Krojer","Sarah Wang","Henry Abrahamsen","Byron C. Wallace","David Bau"],"published":"2026-09-16T15:30:17Z","updated":"2026-09-16T15:30:17Z","abstract_url":"https://arxiv.org/abs/2609.18823v1","html_url":"https://arxiv.org/html/2609.18823v1","pdf_url":"https://arxiv.org/pdf/2609.18823v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":73866,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：How do VLMs map from pixels to semantics? To understand this general question, we focus on a narrow one: studying how VLMs perform optical character recognition (OCR). Across four models, we identify attention heads causally necessary for OCR, and discover th...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18772v1","title":"Zero-Shot Cross-Lingual Recognition of Sign Language Handshapes","abstract":"Sign language processing advances rapidly for high-resource languages such as American Sign Language (ASL), yet most of the world's sign languages lack the phonological annotations new methods require. We present the first zero-shot cross-lingual framework for handshape recognition, transferring from ASL to Catalan Sign Language (LSC). Our approach leverages the decomposition of handshapes into five phonological features -- selected fingers, flexion, spread, thumb position, and thumb contact -- shared across both languages, to decode LSC handshapes from predicted features via a composite phonological distance metric. We evaluate three architectures (MLP, SL-GCN, SHuBERT) trained on two ASL corpora (PopSign, Sem-Lex) against a 37-handshape, single-signer LSC benchmark. Zero-shot transfer proves viable once recording-format disparities are harmonized, reaching 80.0% phonological feature accuracy and 54.5% expected handshape accuracy. Phonological decomposition thus offers a bridge for extending sign language technologies to low-resource languages without any target-language video training labels.","authors":["Marcel Granero-Moya","Carolina del Corral Farrarós","Gloria Haro","Coloma Ballester","Ricardo Marques"],"published":"2026-09-16T14:56:51Z","updated":"2026-09-16T14:56:51Z","abstract_url":"https://arxiv.org/abs/2609.18772v1","html_url":"https://arxiv.org/html/2609.18772v1","pdf_url":"https://arxiv.org/pdf/2609.18772v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":77973,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Sign language processing advances rapidly for high-resource languages such as American Sign Language (ASL), yet most of the world's sign languages lack the phonological annotations new methods require. We present the first zero-shot cross-lingual framework fo...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18753v1","title":"Toward Markerless Video-based Tremor Analysis: Objective Quantification of Pathological Tremor in Mouse Preclinical Models","abstract":"Tremor is a movement disorder characterized by involuntary, rhythmic oscillations of body parts and is a hallmark of several neurological conditions, including Parkinson's disease and essential tremor. Elucidating its underlying mechanisms relies heavily on mouse models, which offer genetic manipulability and translational relevance to human neural circuitry. Accordingly, these models are indispensable for studying tremor pathophysiology. So far, electromyography and accelerometers have been used as methods to quantitatively observe tremors in mice. However, these methods have several drawbacks, such as high costs and complex setups. In particular, the invasive surgical implantation of devices causes significant stress to the animals. Although RGB-based methods offer non-invasive and cost-effective alternatives, they often lack the sensitivity required to detect subtle tremors. Therefore, this paper addresses these challenges by achieving mouse tremor severity estimation using conventional RGB cameras only. To address the challenging task of isolating tremor-related vibrations while the mouse itself is also in motion, our pipeline incorporates segmentation-based pre-processing to extract the mouse region and a Tremor Score Estimation Module that captures subtle tremors with high sensitivity. In the experiments, we assessed tremors in unrestrained mice using a non-invasive method with two standard cameras. The results demonstrated a strong correlation with accelerometer measurements and confirmed that the method accurately captured the intensity-dependent characteristics of tremors. The project page is available at https://isogawalab.github.io/Video-based-Tremor-Analysis-Project/.","authors":["Yota Koshimoto","Akihiro Tsukahara","Yasuhiro Moriwaki","Mariko Isogawa"],"published":"2026-09-16T14:44:11Z","updated":"2026-09-16T14:44:11Z","abstract_url":"https://arxiv.org/abs/2609.18753v1","html_url":"https://arxiv.org/html/2609.18753v1","pdf_url":"https://arxiv.org/pdf/2609.18753v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":30713,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Tremor is a movement disorder characterized by involuntary, rhythmic oscillations of body parts and is a hallmark of several neurological conditions, including Parkinson's disease and essential tremor. Elucidating its underlying mechanisms relies heavily on m...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18737v1","title":"Geometry beneath the Waves: Dense Priors for Sparse-View Underwater 3D Gaussian Splatting","abstract":"Underwater 3D reconstruction supports applications ranging from marine ecosystem monitoring and subsea inspection to underwater archaeology, education, and immersive visualisation. 3D Gaussian Splatting has made real-time photorealistic novel-view rendering practical, while underwater variants incorporate physically based image-formation models to separate medium effects from scene radiance. Their reconstruction quality, however, remains fundamentally limited by the geometry used for initialisation.","authors":["Harvey Caldeira","Haoran Wang","Guoxi Huang","Shaoyu Cai","Rachel Fu","Nantheera Anantrasirichai"],"published":"2026-09-16T14:32:58Z","updated":"2026-09-16T14:32:58Z","abstract_url":"https://arxiv.org/abs/2609.18737v1","html_url":"https://arxiv.org/html/2609.18737v1","pdf_url":"https://arxiv.org/pdf/2609.18737v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":14159,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Underwater 3D reconstruction supports applications ranging from marine ecosystem monitoring and subsea inspection to underwater archaeology, education, and immersive visualisation. 3D Gaussian Splatting has made real-time photorealistic novel-view rendering p...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18690v1","title":"RankGround: Efficient High-Resolution GUI Grounding via Lightweight Reranker-Guided Crop Selection","abstract":"Graphical User Interface (GUI) grounding is a fundamental perception task for multimodal agents, enabling them to interpret natural language instructions and interact with digital interfaces. Existing methods face a fundamental trade-off between accuracy and efficiency: direct full-image inference often fails to capture small or visually similar UI elements, while multi-crop strategies improve localization at the cost of multiple expensive Vision-Language Model (VLM) calls per query. To address this challenge, we propose RankGround, a two-stage framework that achieves accurate GUI grounding with a single VLM call per query. Central to our approach is GroundRanker, a lightweight multimodal reranker that identifies the most promising crop from a dense candidate set. Because no off-the-shelf ranking dataset is available, we construct ranking supervision data from existing grounding datasets. A strict containment criterion and boundary-aware positive augmentation improve alignment and spatial coverage in cluttered layouts. GroundRanker is then trained with a two-stage curriculum: a pointwise objective first learns coarse containment, and a listwise objective refines subtle semantic and spatial distinctions among visually similar crops. Experimental results show that RankGround consistently outperforms strong baselines while reducing computational cost. It achieves 1.4 times faster inference and improves localization accuracy by 5.5% on average over the second-best method across all backbones and screen scales, establishing a new state of the art in both efficiency and precision for GUI grounding.","authors":["Liyang Fan","Xinping Bi","Yitai Li","Shuaimin Li","Hui Li","Min Yang"],"published":"2026-09-16T14:06:38Z","updated":"2026-09-16T14:06:38Z","abstract_url":"https://arxiv.org/abs/2609.18690v1","html_url":"https://arxiv.org/html/2609.18690v1","pdf_url":"https://arxiv.org/pdf/2609.18690v1.pdf","matched_keywords":["agent","multimodal"],"source_used":"html","source_text_chars":59910,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent, multimodal 相关；摘要显示其主要贡献为：Graphical User Interface (GUI) grounding is a fundamental perception task for multimodal agents, enabling them to interpret natural language instructions and interact with digital interfaces. Existing methods face a fundamental trade-off between accuracy and...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:02+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18688v1","title":"Generalist-Specialist Mixture-of-Experts for Rare Pathology Detection in Multimodal Imaging","abstract":"AI models for multimodal medical imaging must balance modality-specific specialization with cross-modal shared representations, a trade-off that pure Mixture-of-Experts (MoE) architectures currently fail to satisfy. Expert-based routing improves in-domain learning but may sacrifice cross-modal signals, which appear particularly important for rare (low-prevalence) pathologies in our experiments. To resolve this, we introduce Generalist-Specialist-MoE (GS-MoE), a two-branch (MoE) architecture that couples a cross-modal generalist model with distinct modality-specific specialists (experts) via domain-constrained feature fusion. On RadImageNet (1.35M images, 165 pathologies, three modalities), GS-MoE recovers detection of six low-prevalence pathologies on which every baseline scores F1 $=$ 0, with per-class gains up to +0.60 F1. It attains this while even slightly exceeding dense and specialist-only MoE aggregate baselines (MCC 0.770), while using ${\\sim}53\\%$ fewer active parameters at inference than the strongest investigated dense model.","authors":["Johannes Kaiser","Florian Braunmiller","Daniel Rückert","Georgios Kaissis"],"published":"2026-09-16T14:04:24Z","updated":"2026-09-16T14:04:24Z","abstract_url":"https://arxiv.org/abs/2609.18688v1","html_url":"https://arxiv.org/html/2609.18688v1","pdf_url":"https://arxiv.org/pdf/2609.18688v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":34231,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：AI models for multimodal medical imaging must balance modality-specific specialization with cross-modal shared representations, a trade-off that pure Mixture-of-Experts (MoE) architectures currently fail to satisfy. Expert-based routing improves in-domain lea...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18667v1","title":"Video-Based Markerless Motion Capture for Clinical and Rehabilitation Biomechanics: A PRISMA-ScR Scoping Review of Validated Architectures, Clinical Readiness, and Emerging Methods","abstract":"Background.. Video-based markerless motion capture promises movement analysis without the cost, space and skin-marker constraints of optoelectronic systems, with particular potential for clinical and rehabilitation settings. Whether validated pipelines yet deliver clinically acceptable biomechanics, and how they relate to the underlying computer-vision research, remains unclear. Methods. We conducted a scoping review following the PRISMA extension for Scoping Reviews, with a registered protocol and searches of PubMed, Scopus and IEEE Xplore (January 2015 to February 2026; the computer-vision scan was updated to July 2026). A dual-tier design paired a primary corpus of validated biomechanical studies with a complementary, curated and deliberately non-exhaustive corpus of emerging computer-vision work, used qualitatively. We charted study characteristics, pipeline architecture, validation methods and joint-angle accuracy. Results. We included 117 studies, most published from 2024 onward and conducted on healthy adults walking in a laboratory. Pipelines formed five architectural families across monocular and multi-camera modalities; most reported raw joint angles without biomechanical refinement. Sagittal lower-limb agreement clustered around 5 to 6{\\textdegree}, generally short of clinical acceptability, while out-of-plane kinematics, kinetics, and pathological or older populations were rarely validated. Emerging computer-vision building blocks (foundation-model mesh recovery, differentiable inverse kinematics, video-based kinetics) were almost absent from validated studies. Conclusions. Video-based markerless capture is not yet interchangeable with marker-based systems for clinical joint kinematics, and it remains barely validated where rehabilitation needs it most: older and pathological populations, out-of-plane kinematics, and kinetics. Mapping this evidence gap onto emerging computer-vision advances, we propose hypothesis-generating design guidelines, not a validated method, to steer the next generation of pipelines toward accessible, clinically meaningful movement analysis.","authors":["Florian Delaplace","Elodie Piche","Frédéric Chorin","Raphael Zory"],"published":"2026-09-16T13:44:08Z","updated":"2026-09-16T13:44:08Z","abstract_url":"https://arxiv.org/abs/2609.18667v1","html_url":"https://arxiv.org/html/2609.18667v1","pdf_url":"https://arxiv.org/pdf/2609.18667v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":2296,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Background.. Video-based markerless motion capture promises movement analysis without the cost, space and skin-marker constraints of optoelectronic systems, with particular potential for clinical and rehabilitation settings. Whether validated pipelines yet de...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18634v1","title":"GenStream: Semantic Streaming Framework for Generative Reconstruction of Human-centric Media","abstract":"Video streaming dominates global internet traffic, yet conventional pipelines remain inefficient for structured, human-centric content such as sports, performance, or interactive media. Standard codecs re-encode entire frames, foreground and background alike, treating all pixels uniformly and ignoring the semantic structure of the scene. This leads to significant bandwidth waste, particularly in scenarios where backgrounds are static and motion is constrained to a few salient actors. We introduce GenStream, a semantic streaming framework that replaces dense video frames with compact, structured metadata. Instead of transmitting pixels, GenStream encodes each scene as a combination of skeletal keypoints, camera viewpoint parameters, and a static 3D background model. These elements are transmitted to the client, where a generative model reconstructs photorealistic human figures and composites them into the 3D scene from the original viewpoint. This paradigm enables extreme compression, achieving over 99.9% bandwidth reduction compared to HEVC for the continuous data stream. We partially validate GenStream on Olympic figure skating footage and demonstrate potential for high perceptual fidelity under minimal data. While acknowledging the significant computational costs shifted to the client and challenges in generalization, GenStream opens new directions in volumetric avatar synthesis, canonical 3D actor fusion across views, and personalized viewing experiences, laying the groundwork for scalable, intelligent streaming in the post-codec era.","authors":["Emanuele Artioli","Daniele Lorenzi","Shivi Vats","Farzad Tashtarian","Christian Timmerer"],"published":"2026-09-16T13:20:36Z","updated":"2026-09-16T13:20:36Z","abstract_url":"https://arxiv.org/abs/2609.18634v1","html_url":"https://arxiv.org/html/2609.18634v1","pdf_url":"https://arxiv.org/pdf/2609.18634v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":62213,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Video streaming dominates global internet traffic, yet conventional pipelines remain inefficient for structured, human-centric content such as sports, performance, or interactive media. Standard codecs re-encode entire frames, foreground and background alike,...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18632v1","title":"VibeAvatar: Aligning Phonetic Kinematics and Human Aesthetics for High-Fidelity Talking Avatar Synthesis","abstract":"Multi-modal talking avatar synthesis aims to generate realistic talking videos from a reference portrait and speech. Despite rapid progress in diffusion-based methods, existing approaches still struggle to jointly achieve accurate lip articulation, human-preferred motion aesthetics, and efficient inference. We observe that phonetic accuracy and motion aesthetics arise from fundamentally different sources and should be addressed at complementary stages rather than learned implicitly by a single generator. Based on this insight, we propose VibeAvatar, which disentangles these two objectives through a Phonetic Kinematics Adapter (PKA) that converts recognition-oriented speech features into phonetic-kinematic conditions at the conditioning stage, and an Aesthetic Motion Policy (AMP) that optimizes a flow-consistent stochastic sampling policy via Group Relative Policy Optimization (GRPO) at the post-training stage. With a lightweight flow-based motion generator operating in a compact 1D warp-based latent motion space, VibeAvatar achieves state-of-the-art results in articulation, aesthetics, and efficiency on both objective metrics and user studies, while generating a 10-second 512px video in under 10 seconds with only $\\sim$3GB VRAM.","authors":["Qilin Wang","Mingyu Li","Hao Tang"],"published":"2026-09-16T13:20:07Z","updated":"2026-09-16T13:20:07Z","abstract_url":"https://arxiv.org/abs/2609.18632v1","html_url":"https://arxiv.org/html/2609.18632v1","pdf_url":"https://arxiv.org/pdf/2609.18632v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":59659,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：Multi-modal talking avatar synthesis aims to generate realistic talking videos from a reference portrait and speech. Despite rapid progress in diffusion-based methods, existing approaches still struggle to jointly achieve accurate lip articulation, human-pref...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18602v1","title":"PULSE: Unlocking Practical Image Compression on Single-Thread CPU","abstract":"Despite recent progress in learned image compression, existing methods remain computationally expensive on resource-constrained hardware, particularly CPUs. We introduce PULSE, a practical codec that enables (1) low-latency decoding on diverse hardware platforms with an ultra-low-complexity 5.2 kMAC/pixel neural receiver, and (2) efficient bit-exact entropy coding with an integer linear CDF predictor and a meta prior. To recover compression performance under this tight budget, we introduce an agentic evolution process guided by heuristic probes that iteratively improves the architecture through human-LLM collaboration. PULSE decodes a 1080p image in 126 ms on a single CPU thread while achieving compression performance comparable to HM. After perceptual optimization, PULSE competes with larger perceptual codecs like MS-ILLM. Codes are at https://github.com/microsoft/GenCodec/tree/main/PULSE","authors":["Zhaoyang Jia","Tianyu Zhang","Zihan Zheng","Wenxuan Xie","Jiahao Li","Bin Li","Houqiang Li","Yan Lu"],"published":"2026-09-16T12:55:36Z","updated":"2026-09-16T12:55:36Z","abstract_url":"https://arxiv.org/abs/2609.18602v1","html_url":"https://arxiv.org/html/2609.18602v1","pdf_url":"https://arxiv.org/pdf/2609.18602v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":66632,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：Despite recent progress in learned image compression, existing methods remain computationally expensive on resource-constrained hardware, particularly CPUs. We introduce PULSE, a practical codec that enables (1) low-latency decoding on diverse hardware platfo...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18582v1","title":"On-the-Fly Homographies Calibration for Multi-Camera Tracking","abstract":"Precise multi-camera tracking traditionally relies on rigorous 3D site calibration, yet this requirement is often operationally impossible in large-scale deployments. Privacy regulations frequently prohibit recording video for offline calibration; limited bandwidth precludes synchronizing high-resolution streams from hundreds of cameras; and covering immense physical sites with calibration targets is logistically infeasible. We present a multi-camera homography calibration system designed to overcome these barriers through \"on-the-fly\" geometric refinement. Starting from coarse manual homographies, we introduce a centroid-based projection optimization (PO) that continuously aligns the ground-plane geometry using live detection streams. Because PO operates asynchronously on already-transmitted, lightweight metadata, it adds zero computational latency to the real-time tracker. This allows the system to adapt automatically to camera movements or environmental changes without human intervention. This optimized geometry feeds a multi-camera bird's-eye-view (BEV) tracker that fuses detections and unifies trajectories across zones. Crucially, by operating strictly on live anonymous metadata, our solution ensures a privacy-safe, zero-overhead, and resilient tracking pipeline that maintains global consistency in dynamic environments where static, recorded-video calibration is impossible.","authors":["David Voihanski","Mor Sinai","Ben Zion Bobrovsky"],"published":"2026-09-16T12:41:55Z","updated":"2026-09-16T12:41:55Z","abstract_url":"https://arxiv.org/abs/2609.18582v1","html_url":"https://arxiv.org/html/2609.18582v1","pdf_url":"https://arxiv.org/pdf/2609.18582v1.pdf","matched_keywords":["video","3d"],"source_used":"html","source_text_chars":39846,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：Precise multi-camera tracking traditionally relies on rigorous 3D site calibration, yet this requirement is often operationally impossible in large-scale deployments. Privacy regulations frequently prohibit recording video for offline calibration; limited ban...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-09-17T05:40:03+00:00","status":"fallback"},"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18578v1","title":"Learning Where to Focus: Self-Supervised Multi-Scale ViTs for Histopathology","abstract":"Pathologists diagnose diseases by first locating suspicious tissue and then examining it at higher magnification, whereas self-supervised vision transformers (ViTs) allocate the same spatial resolution to every image region despite diagnostic evidence being sparse and spanning multiple biological scales. Recent pathology foundation models have substantially improved representation quality by scaling training data and model capacity, but largely retain uniform tokenization. We instead investigate whether pathology representations can be improved by learning where to allocate spatial resolution during self-supervised learning. To this end, we propose CRAFT (Coarse-to-fine Region-Adaptive Feature Tokenization), a DINO-based framework that learns image-dependent mixed-scale representations by using self-supervised attention to selectively refine informative regions while preserving coarse context, together with a symmetric cross-scale regularization objective that encourages complementary coarse and fine representations. Across CAMELYON16, TCGA-Lung subtype classification, and TCGA-LUAD survival prediction, CRAFT consistently outperforms comparable-scale self-supervised methods while requiring lower inference computation. Despite using only a compact 22M parameter backbone trained on comparatively small pathology datasets, CRAFT remains competitive with, and often surpasses, substantially larger pathology foundation models.","authors":["Anabel Stammer","Valay Bundele","Mehran Hosseinzadeh","Hendrik P. A. Lensch"],"published":"2026-09-16T12:38:41Z","updated":"2026-09-16T12:38:41Z","abstract_url":"https://arxiv.org/abs/2609.18578v1","html_url":"https://arxiv.org/html/2609.18578v1","pdf_url":"https://arxiv.org/pdf/2609.18578v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18562v1","title":"Sim-to-Real Traffic Scene Understanding by Decoupling Semantics from Caption Generation with V-JEPA","abstract":"Track 2 of the AI City Challenge 2026 requires both visual question answering (VQA) and traffic event description generation under a challenging synthetic-to real domain shift. Existing vision-language approaches often entangle semantic understanding with language generation, making them susceptible to hallucination and inconsistent reasoning across event phases. In this work, we propose a decoupled semantic understanding framework that first resolves predefined traffic questions into structured semantic facts and subsequently uses these facts to guide caption generation. A frozen V-JEPA encoder extracts predictive scene representations, while a lightweight Llama-based predictor produces answers for VQA queries. To improve reliability, we introduce a training-free structured refinement mechanism that exploits statistical priors, inter-question relationships, and temporal event consistency to correct prediction errors. The refined semantic facts are then provided to Qwen3-VL-8B to generate pedestrian and vehicle descriptions for each traffic event. Experimental results on the official 2026 AI City Challenge Track 2 benchmark show that the proposed method achieves 87.09% VQA accuracy and an overall S2 score of 60.0853, ranking first among all participating teams. These results demonstrate that predictive world representations combined with structured semantic refinement enable more accurate and reliable traffic understanding, leading to higher-quality lan guage generation.","authors":["Nguyen Hoai Thuong Bui","Thanh Nguyen Vo","Trinh Tra Giang Nguyen","Ha Duc Bui"],"published":"2026-09-16T12:21:06Z","updated":"2026-09-16T12:21:06Z","abstract_url":"https://arxiv.org/abs/2609.18562v1","html_url":"https://arxiv.org/html/2609.18562v1","pdf_url":"https://arxiv.org/pdf/2609.18562v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18554v1","title":"CARA: Collision-Aware Resolution Adaptation for Multiresolution Hash Encoding Based Image Fitting","abstract":"Multiresolution hash encodings have recently enabled fast and high-fidelity implicit neural representations by storing multi-scale features in fixed-size hash tables along a geometric resolution schedule. However, the standard design is data-agnostic: different resolution levels receive identical hash-table capacity despite large differences in image frequency content. As a result, some levels experience severe hash collisions while others underutilize parameters, leading to inefficient capacity allocation. To address this issue, we propose Collision-Aware Resolution Adaptation (CARA), a method that assigns per-level resolutions by balancing the effective information load across hash levels. This adaptive allocation reduces capacity bottlenecks and improves parameter efficiency. In addition, we introduce an invertible pixel-shuffle transform that reduces hash load factors by redistributing spatial information, thereby mitigating collision-induced information loss without enlarging the hash tables. To support evaluation on extremely high-resolution data, we also curate, to the best of our knowledge, the first uncompressed whole-slide image dataset for academic research. Experiments on Kodak images, gigapixel natural images, and raw whole-slide images demonstrate that CARA consistently improves the fidelity-parameter trade-off. Our method matches state-of-the-art performance while using only $27.76%$ of the parameters, and achieves up to $6.11$ dB PSNR improvement at comparable parameter counts. Code is provided in the supplementary.","authors":["Linfeng Ye","Zhixiang Chi","Shayan Mohajer Hamidi","En-hui Yang","Konstantinos N. Plataniotis"],"published":"2026-09-16T12:17:34Z","updated":"2026-09-16T12:17:34Z","abstract_url":"https://arxiv.org/abs/2609.18554v1","html_url":"https://arxiv.org/html/2609.18554v1","pdf_url":"https://arxiv.org/pdf/2609.18554v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18546v1","title":"STUNet-Fusion: Spatiotemporal Needle-Tip Localization in Ultrasound Video via Multi-Channel Motion Fusion","abstract":"Needle-tip localization in ultrasound remains challenging because the needle may appear weak, discontinuous, or partially invisible, while imaging artifacts and anatomical structures can produce similar responses. To address this problem, we propose STUNet-Fusion, a spatiotemporal framework for needle-tip localization in ultrasound videos. The proposed method formulates the input as a tri-channel spatio-temporal fusion tensor, comprising grayscale appearance, grid-based motion feature, and raw frame difference. A shared ResNet-34 encoder extracts spatial features, ConvLSTM integrates temporal dependencies, and a U-Net decoder reconstructs a dense probability heatmap. The final coordinates are extracted via a soft-argmax operation to achieve sub-pixel localization accuracy. Experimental results demonstrate that this spatiotemporal fusion strategy significantly improves localization robustness compared to conventional baselines.","authors":["Chia-Chi Hsu","Chia-Hsuan Hsu","Che-Chou Shen"],"published":"2026-09-16T12:11:18Z","updated":"2026-09-16T12:11:18Z","abstract_url":"https://arxiv.org/abs/2609.18546v1","html_url":"https://arxiv.org/html/2609.18546v1","pdf_url":"https://arxiv.org/pdf/2609.18546v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18542v1","title":"Accuracy- and Real-Time-Aware 4D Radar Preprocessing for Autonomous Driving Perception Systems","abstract":"4D radar has emerged as a promising next-generation sensor for improving the robustness of autonomous driving perception systems because of its stable sensing capability under adverse weather conditions. However, deploying 4D radar in embedded environments with limited hardware resources requires radar-representation preprocessing that jointly considers perception accuracy, real-time performance, and computational complexity. This paper proposes a preprocessing framework for 4D-radar-based 3D object detection. First, Percentile-based 3D Shape Preservation (P3DP) extracts point clouds from radar tensors while preserving object-shape information and suppressing noise and false alarms. Second, Multi-frame-based Noise Point Discrimination using Kernel Density Estimation (MF-KDE) improves the density and reliability of sparse radar point clouds. Finally, Embedded \\& NetScore (ENS) evaluates suitability for embedded deployment by jointly considering accuracy, real-time performance, adverse-weather robustness, and model complexity.","authors":["Woo-Jin Jung","Dong-Hee Paek","Jeong-Su Park","Seung-Hyun Kong"],"published":"2026-09-16T12:06:22Z","updated":"2026-09-16T12:06:22Z","abstract_url":"https://arxiv.org/abs/2609.18542v1","html_url":"https://arxiv.org/html/2609.18542v1","pdf_url":"https://arxiv.org/pdf/2609.18542v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18540v1","title":"SVMemAgent: A Streaming Video Memory Agent for Query-Agnostic Online Frame Selection","abstract":"Most keyframe selection studies focus on offline settings, assuming access to the full video and query in advance. In contrast, real-world streaming scenarios require online frame selection under unknown video duration, without access to either the query or future frames during selection. To address this, we introduce Streaming Video Memory (SVMem), a compact and representative memory of previously observed content, updated continuously as the video stream unfolds. Building on this setting, we propose the Streaming Video Memory Agent (SVMemAgent), which dynamically maintains a memory by deciding at each timestep whether to replace an existing memory frame with the incoming frame or discard it. SVMemAgent is trained using Group Relative Policy Optimization (GRPO) with task-driven rewards derived from diverse question-answer pairs, implicitly exposing the policy to a distribution of queries during training so that SVMem retains generally informative frames at inference, when queries are unavailable. Experiments on both online and offline video benchmarks show that SVMemAgent consistently outperforms online frame selection baselines and achieves competitive performance with offline methods that assume access to the full video and query. Through task-driven rewards, SVMemAgent learns an emergent keyframe selection policy that prefers frames containing textual information, which may benefit downstream VideoQA tasks.","authors":["Dohwan Ko","Ji Soo Lee","Pierce Chuang","Debojeet Chatterjee","Ashish Shenoy","Yichao Lu","Seungwhan Moon","Xin Luna Dong","Vikas Bhardwaj","Hyunwoo J. Kim"],"published":"2026-09-16T12:04:53Z","updated":"2026-09-16T12:04:53Z","abstract_url":"https://arxiv.org/abs/2609.18540v1","html_url":"https://arxiv.org/html/2609.18540v1","pdf_url":"https://arxiv.org/pdf/2609.18540v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18511v1","title":"Learning from Distributed Eyes: Leveraging Collaborative Perception for Automated Model Adaptation","abstract":"In autonomous driving, perception models often struggle to generalize to new environments due to domain shifts. While unsupervised model adaptation offers a feasible solution without labor-intensive manual labeling, existing methods that rely solely on the ego-vehicle's data often lead to inferior pseudo-labeling performance. To address this critical issue, we propose LDE, Learning from Distributed ``Eyes\", a novel framework that transforms collaborative perception (CP) into a source of high-quality supervision for model adaptation. This pseudo-labeling approach is hyperparameter-insensitive and relatively reliable, assuming CP often outperforms single-agent's perception. However, naively implementing this approach encounters (1) the communication bottleneck of sharing rich features under time and bandwidth constraints, (2) the view discrepancy between the CP view and the learner's Field of View (FoV), and (3) the unreliability even in CP-generated labels. To address these issues, we design an adaptation-oriented feature sharing mechanism that selectively transmits the most critical information for adaptation, an FoV filtering method that meticulously eliminates mismatched labels, and a curriculum learning strategy to progressively exploit pseudo labels. Extensive experiments on 3D object detection tasks demonstrate that LDE consistently outperforms both the pre-trained models and state-of-the-art unsupervised adaptation methods.","authors":["Yanan Ma","Yihang Tao","Zhengru Fang","Zihan Fang","Yiqin Deng","Xianhao Chen","Yuguang Fang"],"published":"2026-09-16T11:44:26Z","updated":"2026-09-16T11:44:26Z","abstract_url":"https://arxiv.org/abs/2609.18511v1","html_url":"https://arxiv.org/html/2609.18511v1","pdf_url":"https://arxiv.org/pdf/2609.18511v1.pdf","matched_keywords":["3d","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18510v1","title":"DiT-Garment: Garment Dynamics with Diffusion Transformers","abstract":"We present DiT-Garment to model dynamic 3D clothing over human body models in arbitrary motion. Unlike existing methods, DiT-Garment can animate garments with unseen designs and physical materials, while allowing for direct inference of deformations for any target pose. To achieve this, we leverage a 2D diffusion transformer architecture to learn 3D deformations in a 2D UV-space. As the result is non-deterministic, our generative model learns the distribution of possible outcomes. The template garment is represented as a 3D triangle mesh spatially aligned with a 3D human body model in a standardized pose. To work with different garment designs without the need of a common template or complex graph convolution operations, the diffusion transformer is conditioned on a 3D position map of the template, represented in UV-space, which allows to implicitly learn a deformation of the 3D space around the body in standard pose. Further conditioning on body motion and physical parameters allows to physically ground the model. We quantitatively and qualitatively evaluate DiT-Garment on both synthetic and real data. While only trained on synthetic simulations of automatically generated cloth designs, our method generalizes to captured and artist-made garment designs. Code and data are available for research purposes at https://dumoulina.github.io/dit-garment/.","authors":["Antoine Dumoulin","Laurence Boissieux","Joao Regateiro","Pierre Hellier","Stefanie Wuhrer"],"published":"2026-09-16T11:44:03Z","updated":"2026-09-16T11:44:03Z","abstract_url":"https://arxiv.org/abs/2609.18510v1","html_url":"https://arxiv.org/html/2609.18510v1","pdf_url":"https://arxiv.org/pdf/2609.18510v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18490v1","title":"Learning A Unified Template for Gait Recognition","abstract":"\"What I cannot create, I do not understand.\"Human wisdom reveals that creation is one of the highest forms of learning. For example, Diffusion Models have demonstrated remarkable semantic structure and memory in image generation, understanding, and restoration, which intuitively benefits representation learning. However, current gait networks rarely embrace this perspective, relying primarily on learning by contrasting gait samples under varying complex conditions, leading to semantic inconsistency and uniformity issues. To address these issues, we propose Origins with generative capabilities whose underlying philosophy is that different entities are generated from a unified template, inherently regularizing gait representations within a consistent and diverse semantic space to capture accurate gait differences. Admittedly, learning this unified template is exceedingly challenging, as it requires the comprehensiveness of the template to encompass gait representations with various conditions. Inspired by Diffusion Models, Origins diffuses the unified template into timestep templates for gait generative learning, and meanwhile transfers the unified template for gait representation learning. Especially, gait generative and representation learning serve as a unified framework for end-to-end joint training. Extensive experiments on CASIA-B, CCPG,SUSTech1K, Gait3D, GREW and CCGR-MINI demonstrate that Origins performs unified generative and representation learning, achieving superior performance.","authors":["Panjian Huang","Saihui Hou","Junzhou Huang","Yongzhen Huang"],"published":"2026-09-16T11:27:36Z","updated":"2026-09-16T11:27:36Z","abstract_url":"https://arxiv.org/abs/2609.18490v1","html_url":"https://arxiv.org/html/2609.18490v1","pdf_url":"https://arxiv.org/pdf/2609.18490v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18488v1","title":"Beyond Random Couplings: Contrastive Noise Alignment in Generative Flows","abstract":"Diffusion and flow-matching models are typically trained by corrupting data through independently sampled Gaussian noise. While simple and scalable, this forward process induces arbitrary data-noise couplings, forcing the network to learn high-curvature transports between unrelated endpoints. Existing optimal-transport methods reduce this burden by reassigning fixed noise samples to data, but the source noise distribution itself remains passive. To address this, we introduce Contrastive Noise Alignment (CNA), a training-time method that creates dynamic, contrastive couplings by optimizing the noise representations directly. By modeling the noise batch as an interacting particle system, CNA employs a cross-modal InfoNCE objective to align noise particles with their paired data targets. To prevent spatial collapse, this alignment is regularized using an angular entropy term and a radial norm penalty. We show theoretically that this equilibrium asymptotically preserves Gaussian structures, maintaining tractability during inference. Empirically, CNA improves the alignment between noise and data, reduces flow curvature, and provides better generation quality with fewer required sampling steps. For few-step, pixel-space generation (2-4 NFEs), CNA reduces FID by over 50\\% compared to standard rectified flow, and by at least 24\\% against Optimal Transport baselines.","authors":["Lennart Wittke","Vinicius Azevedo"],"published":"2026-09-16T11:21:31Z","updated":"2026-09-16T11:21:31Z","abstract_url":"https://arxiv.org/abs/2609.18488v1","html_url":"https://arxiv.org/html/2609.18488v1","pdf_url":"https://arxiv.org/pdf/2609.18488v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18487v1","title":"ActionPiece: Rethinking Action Tokenization for Autoregressive Vision-Language-Action Models","abstract":"Action tokenizers play a central role in autoregressive vision-language-action (VLA) models, determining both the targets for policy training and the executable commands recovered from predicted tokens. Their fidelity is commonly evaluated using pointwise reconstruction metrics such as mean squared error (MSE), yet small individual errors do not fully characterize how faithfully action adjustments across demonstrations are preserved. After compression, similar actions may still cluster around a representative motion, while the adjustments needed for different contexts are diminished, distorted, or even reversed. We introduce physical rank consistency (PRC) to measure how well tokenization preserves local physical distance rankings after reconstruction. Evaluating decoded actions provides a common reference across token vocabularies and decoder architectures, complementing pointwise accuracy with a measure of relational fidelity. We further present ActionPiece, which preserves physical action relationships through joint supervision of representation learning and quantization. Physical rank preservation supervises near-far ordering in encoder and quantized feature distances, while quantization regularization applies the same ordering to codeword assignment distributions. Both objectives augment reconstruction, producing discrete action tokens for standard autoregressive policy learning and execution through a frozen decoder. Under the same Qwen3-VL-4B policy training setup, ActionPiece achieves 94.8% on LIBERO and 68.8% on unseen LIBERO-Plus, with additional evaluations reaching 71.9% on SimplerEnv and 51.5% across VLA-Arena L0-L2. Component ablations show that the two objectives jointly improve PRC and policy success, demonstrating the value of physical relationship supervision for action tokenization.","authors":["Shijie Lian","Bin Yu","Zhaolong Shen","Xiaopeng Lin","Yichao Du","Zhirui Zhang","Laurence T. Yang","Kai Chen"],"published":"2026-09-16T11:19:54Z","updated":"2026-09-16T11:19:54Z","abstract_url":"https://arxiv.org/abs/2609.18487v1","html_url":"https://arxiv.org/html/2609.18487v1","pdf_url":"https://arxiv.org/pdf/2609.18487v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18473v1","title":"CADSplat: Sparse-View 3D Gaussian Splatting Aided by CAD Models for Robust, Photorealistic Digital-Twin Reconstruction","abstract":"We present CADSplat, a framework that reconstructs photorealistic, geometrically accurate digital twins from sparse ($<15$ views), wide-baseline posed images of an object by regularizing 3D Gaussian Splatting (3DGS) with an explicit CAD shape prior. Using such a prior requires finding a CAD model whose shape resembles the object depicted in the images and determining the pose of each camera relative to the object. We obtain both by matching segmented object silhouettes against silhouettes rendered from a CAD library and keeping the camera-to-object poses of the best-matching model. We then anchor 3D Gaussian primitives to the surface of the retrieved model and jointly optimize the 3DGS parameters, the camera-to-object registration, and a non-rigid deformation field to account for shape differences between the physical object and the CAD model. Across two real-world datasets, CADSplat outperforms unconstrained, few-shot, and mesh-texturing baselines and degrades gracefully to as few as 3 views. Our experiments show that most of the gain in rendering quality comes from how the splats are constrained---a fixed set of splats tied to a surface and moved by a single smooth deformation field---rather than from the CAD shape itself. The CAD model adds shape knowledge where views are scarcest, in the sparsest captures and on strongly self-occluded objects, and it places every camera in the object's own frame. This enables applications beyond novel-view synthesis, such as markerless augmented reality registration, per-image object pose estimation, physical simulations, and the transfer of part labels from the design to the reconstruction.","authors":["Kristof Overdulve","Lode Jorissen","Nick Michiels"],"published":"2026-09-16T11:07:21Z","updated":"2026-09-16T11:07:21Z","abstract_url":"https://arxiv.org/abs/2609.18473v1","html_url":"https://arxiv.org/html/2609.18473v1","pdf_url":"https://arxiv.org/pdf/2609.18473v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18465v1","title":"GeoCond: A Conditioning-Aware Reliability Adapter for Feed-Forward 3D Reconstruction","abstract":"Feed-forward 3D foundation models such as VGGT predict cameras, depth, and point maps in a single pass, but can fail silently under low overlap, low parallax, and extreme relative rotation. Stratified analyses over these factors show that these failures are governed by geometric conditioning and are poorly captured by native aleatoric confidence. We introduce GeoCond, a lightweight reliability adapter for frozen feed-forward 3D backbones. GeoCond reads the backbone's predicted geometry and outputs pose-level uncertainty and a refinement gate. During training, it can be supervised by frame-permutation orbit variance, ground-truth pose error when labels are available, or cycle residuals from unlabelled independent pose graphs. At inference, the default head requires only one backbone pass and a small MLP. On VGGT, GeoCond improves out-of-distribution (OOD) AUSE (area under the sparsification-error curve; lower is better) from $0.32$ to $0.20$ over native confidence, transfers zero-shot to outdoor extreme-view scenes, and avoids the collapse caused by applying bundle adjustment uniformly. Across multiple backbones, cycle-distilled variants provide a ground-truth-free adaptation route, including cases where permutation variance vanishes on equivariant models. The same reliability signal supports gated refinement, pose-graph weighting, calibration, curation, and capture decisions. Reliable feed-forward 3D reconstruction requires not only predicting geometry, but also knowing when that geometry should be trusted.","authors":["David Ahmedt-Aristizabal","Mohammad Ali Armin","Russell Tsuchida","Lars Petersson"],"published":"2026-09-16T11:00:01Z","updated":"2026-09-16T11:00:01Z","abstract_url":"https://arxiv.org/abs/2609.18465v1","html_url":"https://arxiv.org/html/2609.18465v1","pdf_url":"https://arxiv.org/pdf/2609.18465v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18462v1","title":"CSWAM: Better Causal Semantic Representations for Out-of-Distribution Generalization in World Action Models","abstract":"FastWAM-style world action models enable efficient action-only inference, but generalize poorly under visual distribution shifts. Their reconstruction-oriented representations emphasize appearance-specific details, limiting generalization to unseen scenes and objects. Without observation history, the model also lacks temporal evidence for robustly identifying task-relevant state changes and motion in unfamiliar visual conditions. To address these limitations, we present the Causal Semantic World Action Model (CSWAM), which augments FastWAM with a causal semantic expert built on V-JEPA 2.1. V-JEPA provides temporally grounded representations of semantic state changes and motion with less dependence on appearance-specific details. The expert learns their future evolution from a sparse history of current and past observations and shares the history-derived context with both the video and action streams through causal attention. At inference, CSWAM conditions action denoising on the current video state and observed semantic history, retaining efficient action-only inference. We conduct simulation and real-robot experiments to evaluate generalization under distribution shifts. With embodied pretraining, CSWAM raises Randomized success on RoboTwin 2.0 Clean-to-Randomized transfer from 10.16% to 45.18%, a gain of 35.02 percentage points over FastWAM. Across two real-robot tasks and three OOD difficulty levels, CSWAM improves average success over FastWAM by 42.5 percentage points, from 27.5% to 70.0%.","authors":["Tianbin Liu","Jian Zhu","Taiyi Su","Jianjun Zhang","Chong Ma","Zitai Huang","Yi Xu"],"published":"2026-09-16T10:56:39Z","updated":"2026-09-16T10:56:39Z","abstract_url":"https://arxiv.org/abs/2609.18462v1","html_url":"https://arxiv.org/html/2609.18462v1","pdf_url":"https://arxiv.org/pdf/2609.18462v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18444v1","title":"DR.WILSS: Diffusion-Based Replay for Weakly Supervised Continual Semantic Segmentation","abstract":"Weakly supervised class-incremental semantic segmentation (WILSS) aims to train a segmentation model over multiple steps, each introducing new concepts to be learned with only image-level supervision. We introduce DR.WILSS, an innovative approach to address catastrophic forgetting in continual learning using diffusion-based generative replay. Our framework leverages language clues to guide the diffusion process, employing self-inpainting and regularization techniques to efficiently produce replay data, aiding the learning process. By generating high-quality replay data, the information from previously learned classes can be preserved during continual updates, a critical challenge in incremental learning scenarios. To further align the statistics of replay data with those of training samples, we apply LoRAs to the generative model. Experimental results demonstrate state-of-the-art performance across multiple benchmarks and generative architectures, while avoiding storage of training data and the use of additional resource-demanding tools during training. The proposed technique enables an optimal tradeoff between training complexity and inference-time accuracy, making DR.WILSS a promising solution for real-world applications.","authors":["Leon Arthur Marx","Francesco Barbato","Matteo Caligiuri","Pietro Zanuttigh"],"published":"2026-09-16T10:33:51Z","updated":"2026-09-16T10:33:51Z","abstract_url":"https://arxiv.org/abs/2609.18444v1","html_url":"https://arxiv.org/html/2609.18444v1","pdf_url":"https://arxiv.org/pdf/2609.18444v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18432v1","title":"Occluded Gait Recognition with Mixture of Experts: An Action Detection Perspective","abstract":"Extensive occlusions in real-world scenarios pose challenges to gait recognition due to missing and noisy information, as well as body misalignment in position and scale. We argue that rich dynamic contextual information within a gait sequence inherently possesses occlusion-solving traits: 1) Adjacent frames with gait continuity allow holistic body regions to infer occluded body regions; 2) Gait cycles allow information integration between holistic actions and occluded actions. Therefore, we introduce an action detection perspective where a gait sequence is regarded as a composition of actions. To detect accurate actions under complex occlusion scenarios, we propose an Action Detection Based Mixture of Experts (GaitMoE), consisting of Mixture of Temporal Experts (MTE) and Mixture of Action Experts (MAE). MTE adaptively constructs action anchors by temporal experts and MAE adaptively constructs action proposals from action anchors by action experts. Especially, action detection as a proxy task with gait recognition is an end-to-end joint training only with ID labels. In addition, due to the lack of a unified occluded benchmark, we construct a pioneering Occluded Gait database (OccGait), containing rich occlusion scenarios and annotations of occlusion types. Extensive experiments on OccGait, OccCASIA-B,Gait3D and GREW demonstrate the superior performance of GaitMoE.OccGait is available at https://github.com/BNU-IVC/OccGait.","authors":["Panjian Huang","Yunjie Peng","Saihui Hou","Chunshui Cao","Xu Liu","Zhiqiang He","Yongzhen Huang"],"published":"2026-09-16T10:24:31Z","updated":"2026-09-16T10:24:31Z","abstract_url":"https://arxiv.org/abs/2609.18432v1","html_url":"https://arxiv.org/html/2609.18432v1","pdf_url":"https://arxiv.org/pdf/2609.18432v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18430v1","title":"StrucPhysVideo: Learning Physical Dynamics from Structured Captions and Robot Actions","abstract":"Modeling physical dynamics, including how objects move, interact, and change state, is central to video world models for embodied AI. We present StrucPhysVideo, a family of video world models that bridges physics-focused data curation with language- and action-conditioned prediction of scene evolution. Our data pipeline combines motion-aware video segmentation, quality and content filtering, and physical relevance verification with structured annotations of objects, materials, and temporally localized interactions. By disentangling camera motion from object behavior and explicitly describing contact, deformation, and state transitions, the pipeline provides supervision grounded in observable physical events. Building on these data, we introduce StrucPhysVideo-TI2V, a sparse Mixture-of-Experts (MoE) text-image-to-video model trained with a curriculum that progressively emphasizes physical dynamics while retaining general-domain video data. StrucPhysVideo-TI2V achieves state-of-the-art performance on Physics-IQ Verified, scoring 45.5% and outperforming Cosmos3-Super-Image2Video by 2.8 percentage points. Caption ablations across backbones further demonstrate the effectiveness of physics-focused supervision. We further extend StrucPhysVideo-TI2V to StrucPhysVideo-IA2V, an interactive image-action-to-video world model that predicts visual outcomes from robot end-effector commands. Action conditioning, causal autoregressive generation, and few-step distillation enable incremental robot rollouts with only four denoising steps. Together, StrucPhysVideo advances physical dynamics modeling from image- and language-conditioned video prediction toward action-driven interaction.","authors":["Awomo-WM Team",":","Enhui Ma","Kaiwen Guo","Tingrui Zhang","Wei Song","Yingshui Tan","Jianhua Xu","Tong Zhang","Kaicheng Yu"],"published":"2026-09-16T10:23:00Z","updated":"2026-09-16T10:23:00Z","abstract_url":"https://arxiv.org/abs/2609.18430v1","html_url":"https://arxiv.org/html/2609.18430v1","pdf_url":"https://arxiv.org/pdf/2609.18430v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18413v1","title":"Vocabulary-Guided Gait Recognition","abstract":"What is a gait? Appearance-based gait networks consider a gait as the human shape and motion information from images. Model-based gait networks treat a gait as the human inherent structure from points. However, the considerations remain vague for humans to comprehend truly. In this work, we introduce a novel paradigm Vocabulary-Guided Gait Recognition, dubbed Gait-World, which attempts to explore gait concepts through human vocabularies with Vision-Language Models (VLMs). Although VLMs have achieved the remarkable progress in various vision tasks, the cognitive capability regarding gait modalities remains limited. The success element in Gait-World is the proper vocabulary prompt where this paradigm carefully selects gait cycle actions as Vocabulary Base, bridging the gait and vocabulary feature spaces and further promoting human understanding for the gait. How to extract gait features? Although previous gait networks have made significant progress, learning solely from gait modalities on limited gait databases makes it difficult to learn universal gait features for practicality. Therefore, we propose the first Gait-World model, dubbed α-Gait, which guides the gait network learning with vocabulary knowledge from VLMs. However, due to the heterogeneity of the modalities, directly integrating vocabulary and gait features is highly challenging as they reside in different embedding spaces. To address the issues, α-Gait designs Vocabulary Relation Mapper and Gait Fine grained Detector to map and establish vocabulary relations in the gait space for detecting corresponding gait features. Extensive experiments on CASIA-B, CCPG, SUSTech1K, Gait3D and GREW reveal the potential value and research directions of vocabulary information from VLMs in the gait field.","authors":["Panjian Huang","Saihui Hou","Chunshui Cao","Xu Liu","Yongzhen Huang"],"published":"2026-09-16T10:07:20Z","updated":"2026-09-16T10:07:20Z","abstract_url":"https://arxiv.org/abs/2609.18413v1","html_url":"https://arxiv.org/html/2609.18413v1","pdf_url":"https://arxiv.org/pdf/2609.18413v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18406v1","title":"Prosthesis-Aware 3D Human Pose Estimation: A Dataset and Benchmark for RSP Users","abstract":"Recovering 3D human body motion from video is important for applications such as rehabilitation assessment and sports performance evaluation. For prosthesis users, this requires capturing both natural body joints and the geometry of the prosthetic device, a challenge that existing methods are not designed to address. Model-based estimators rely on body models trained on non-amputee individuals and cannot represent prosthesis geometry, while model-free methods lack body kinematic priors and are unreliable under occlusion. This challenge is particularly prominent for users of running-specific prostheses (RSPs), where the RSP has a complex curved geometry and moves dynamically during exercise. To fill this gap, we collect RSP3D, the first 3D dataset of RSP users, covering essential daily-life and exercise actions from participants with varied amputation conditions, using a multi-camera marker-based motion capture setup. We formally define the task of prosthesis-aware 3D pose estimation, evaluate representative methods in a zero-shot setting, and confirm their individual limitations. We further propose a hybrid baseline combining model-based body joint estimation with model-free RSP shape recovery, establishing a starting point for future research.","authors":["Yilin Wen","Kechuan Dong","Fumiya Suginaka","Ken Endo","Yusuke Sugano"],"published":"2026-09-16T09:59:54Z","updated":"2026-09-16T09:59:54Z","abstract_url":"https://arxiv.org/abs/2609.18406v1","html_url":"https://arxiv.org/html/2609.18406v1","pdf_url":"https://arxiv.org/pdf/2609.18406v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18393v1","title":"MSR: Multiple Subject Reference for Video Generation","abstract":"Conditioning a video generator on multiple images requires preserving appearance while associating each reference with its intended role. We present MSR (Multiple Subject Reference), a slot-aware conditioning scheme for LTX-based video generation. Each reference image is independently encoded as a static clip and represented by a separate latent-token group. A compact Fourier-feature multilayer perceptron adds a numeric slot embedding, while slot-dependent temporal offsets modify the group's rotary coordinates. The reference groups are prepended to noisy target tokens and serve as clean context during target-only flow-matching training. We implement this scheme through low-rank adaptation and release the resulting weights and inference workflows. Qualitative examples demonstrate compositions containing distinct characters and referenced environments in realistic and stylized scenes. Development observations suggest reduced reference confusion relative to an earlier continuous-reference baseline, while similar clothing, complex garments, and viewpoint changes remain challenging. We describe the conditioning mechanism, the retained training configuration, and the observed strengths and limitations of the released system. A supplementary audio-reference experiment adds voice conditioning while keeping the visual parameters frozen.","authors":["Guannan Li","Jiaji Chen","Jingyuan Liao","Yu Geng","Baolan Qiu"],"published":"2026-09-16T09:51:50Z","updated":"2026-09-16T09:51:50Z","abstract_url":"https://arxiv.org/abs/2609.18393v1","html_url":"https://arxiv.org/html/2609.18393v1","pdf_url":"https://arxiv.org/pdf/2609.18393v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18363v1","title":"Online Multi-Camera 3D Tracking via ID Prediction over Recurrent Sparse Queries","abstract":"Online multi camera 3D tracking must maintain scene global identities across synchronized views, yet query-based trackers carry these identities only implicitly in the instance bank, where they fragment upon query interruption. We present an online architecture that recovers association accuracy by predicting IDs explicitly over recurrent sparse queries. An outside-in Sparse4D detector fuses calibrated views into world frame 3D detections while propagating a sparse query bank, and a causal MOTIP ID decoder associates detections against a finite trajectory memory. We adapt MOTIP's relative-ID prediction and recycled slot runtime to globally fused 3D observations, and introduce metric spatial gating and proximity based newborn recovery. On the official 2026 AI City Challenge Track 1 test set, our method raises HOTA from 29.63 with native instance bank identities to 38.01, primarily through an AssA increase from 20.83 to 31.10, and ranks third on the public leaderboard. Full-sequence validation over all 9,000 frames of each scene shows that decoupled ID training improves HOTA over native identities, whereas continuing detector training alongside the detached ID objective produces scene-dependent gains and losses.","authors":["Pragyan Shrestha","Haruto Nakayama","Atom Scott"],"published":"2026-09-16T09:21:25Z","updated":"2026-09-16T09:21:25Z","abstract_url":"https://arxiv.org/abs/2609.18363v1","html_url":"https://arxiv.org/html/2609.18363v1","pdf_url":"https://arxiv.org/pdf/2609.18363v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18345v1","title":"Visual Input and Its Framing Affect Attribute-based Descriptions Produced by Large Vision-Language Models","abstract":"Large vision-language models (LVLMs) are commonly used with only a single text prompt as the input, or plus an image. In this paper, we demonstrate that when the image exists, even if the text prompt is not about the specific instance (but only the concept it belongs to) in that image, the response would still be affected. For example, when the text prompt only asks for the attribute descriptions of a dog breed, an image depicting a specific dog from that breed would shift the response. Further, how the specific instance is framed in that image would determine towards which the response shifts. Detailed analyses also reveal that in the response, physical terms increase from 18% for text-only to 45% (40%) for subject-focused (subject-in-situation) framings. Overall, the unexpected effects of visual cues on LVLMs highlight the need to understand the presence of an image and its framing when evaluating the robustness of LVLMs.","authors":["Xiaomeng Wang","Martha Larson","Zhengyu Zhao"],"published":"2026-09-16T09:08:57Z","updated":"2026-09-16T09:08:57Z","abstract_url":"https://arxiv.org/abs/2609.18345v1","html_url":"https://arxiv.org/html/2609.18345v1","pdf_url":"https://arxiv.org/pdf/2609.18345v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18336v1","title":"Pose2Muscle: Structured Spatio-Temporal Decoding for Discrete Muscle Activity Estimation from Human Pose","abstract":"Muscle activity is fundamental to human movement, and understanding its patterns is critical for injury prevention and rehabilitation. Conventional muscle activity monitoring relies on specialized sensors such as surface electromyography, which limits its practicality for long-term real-world use. Existing studies suggest that muscle-related information can be inferred from human pose. However, the substantial gap between externally observable pose and internal muscle activation, limits the accuracy and generalization of current approaches. In this study, we propose Pose2Muscle, a pose-driven framework for discrete muscle activity estimation without requiring sEMG signals at inference time. Instead of directly regressing continuous sEMG signals, Pose2Muscle reformulates muscle estimation as a structured prediction problem over discrete muscle activity states, yielding a more stable and interpretable target space. The framework combines multi-scale spatio-temporal attention to capture motion patterns at complementary spatial and temporal scales with a directed acyclic graph-based decoder that maintains multiple candidate muscle-state hypotheses and performs structured trajectory inference over time. To support this task, we construct PoseEMG-43, a synchronized pose-sEMG dataset containing 2,992 movement instances from 43 daily-life actions performed by 14 participants. Experiments show that Pose2Muscle consistently outperforms representative retrieval- and pose-based baselines. It achieves an Adjacent-level Accuracy of 86.36% and a Pearson correlation coefficient of 0.8821 under the Random Split, and 63.97% and 0.6795, respectively, under the Subject-Level Split. These results demonstrate the feasibility of inferring structured muscle-state patterns from human pose and suggest the potential of Pose2Muscle for muscle-aware movement analysis when direct physiological sensing is impractical","authors":["Yuepeng Chen","Jiehong Shi","Kaili Zheng","Boyi Zhang","Chenyi Guo","Ji Wu","Xiangling Fu"],"published":"2026-09-16T08:58:45Z","updated":"2026-09-16T08:58:45Z","abstract_url":"https://arxiv.org/abs/2609.18336v1","html_url":"https://arxiv.org/html/2609.18336v1","pdf_url":"https://arxiv.org/pdf/2609.18336v1.pdf","matched_keywords":["retrieval","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18323v1","title":"Can MiniMax-H3 Reason About the Physical World? An Evaluation of Omni-Modal Generative Model","abstract":"Recent Omni-Modal Generative Models (Omni-Models) have advanced content generation toward unified modeling of text, images, video, and audio. MiniMax-H3 exemplifies this transition by combining multimodal context understanding with joint audio-visual generation in a shared latent framework. Its unified architecture raises a fundamental question: Can multimodal alignment improve the model's world reasoning, and what new evaluation paradigms do omni-modal inputs enable? To investigate this question, this work introduces a comprehensive evaluation framework organized around four complementary dimensions of physical world reasoning. Unlike existing evaluation frameworks for video generation and world models, which are often constrained by limited input modalities and evaluation settings where prompts closely match the target video content, our evaluation is specifically designed to exploit the multimodal inputs of Omni-Model. We construct a diverse set of novel tasks that require models to integrate complementary information across modalities. Specifically, we consider four scenarios, including implicit prompts paired with multiple frames, audio-image, prefix-videos, and audio-video inputs. Every single modality provides only partial evidence about the underlying event, requiring the model to jointly reason over the complementary semantic cues to infer latent event states and future dynamics. Across 517 evaluation instances, MiniMax-H3 achieves an overall success rate of 41.97%. Video-based Decision Reasoning yields the highest success rate at 56.00%, while Audio-based Disambiguation Reasoning is the weakest, reaching only 27.40%. These results indicate that effective multimodal integration remains key to fully exploiting the benefits of diverse input modalities. The project is available at https://github.com/gulucaptain/MiniMax-H3-Reason.","authors":["Haoyu Zhao","Zihao Zhao","Tianyu Deng","Ziqin Xu","Zihao Zhang","Xudong Wang","Jinxiang Guo","Chen Gao","Ziyi Ye","Yeying Jin","Jiaxi Gu","Zuxuan Wu","Shuicheng Yan"],"published":"2026-09-16T08:43:11Z","updated":"2026-09-16T08:43:11Z","abstract_url":"https://arxiv.org/abs/2609.18323v1","html_url":"https://arxiv.org/html/2609.18323v1","pdf_url":"https://arxiv.org/pdf/2609.18323v1.pdf","matched_keywords":["video","instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18260v1","title":"MS-RFD: Multi-Signal Release Frame Detection in Hammer Throw from Reconstructed 3D Trajectories","abstract":"Recent advances in artificial intelligence and computer vision are reshaping sports performance analysis by enabling automated detection, tracking, and performance analysis. In hammer throw, performance is strongly determined by the kinematic conditions at release, particularly release speed, release angle, and release height. However, identifying the release instant from video typically requires manual frame-by-frame inspection, which is subjective and cumbersome in real-world training scenarios. In this paper, we present a fully automatic multi-signal release frame detection (MS-RFD) method for hammer throw using reconstructed 3D hammer trajectories. The proposed method integrates four complementary kinematic signals: speed dynamics, angular velocity transition, radial distance relative to the rotation center, and post-release trajectory linearity. These signals are fused to score and verify candidate release frames. MS-RFD is evaluated through the throwing-distance estimation error obtained from the release parameters estimated at the detected frame. An ablation study analyzes the contribution of each signal and compares alternative candidate selection strategies. The results show that speed dynamics and radial expansion provide the strongest signals for release frame detection, while angular velocity and post-release linearity provide smaller refinements.","authors":["Ahmed Endris Hasen","Nikolaos Passalis","Tomi Vanttinen","Jenni Raitoharju"],"published":"2026-09-16T07:38:59Z","updated":"2026-09-16T07:38:59Z","abstract_url":"https://arxiv.org/abs/2609.18260v1","html_url":"https://arxiv.org/html/2609.18260v1","pdf_url":"https://arxiv.org/pdf/2609.18260v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18259v1","title":"${M}^2$Tok: Multi-head Multi-codebook Discrete Action Tokenization for Vision-Language-Action Models","abstract":"Recent advancements have successfully adapted autoregressive language models to process multimodal signals, such as images and actions. Since raw action signals are continuous, effective tokenization is essential to map high-dimensional inputs into compact discrete tokens for autoregressive processing. However, existing discrete action tokenizers often suffer from high reconstruction loss, failing to preserve the fine-grained dynamics required for precise control. This ``discretization bottleneck'' significantly limits the performance ceiling of downstream Vision-Language-Action (VLA) models. To address this, we propose $\\mathcal{M}^2$Tok, a Multi-head Multi-codebook Action Tokenizer designed to minimize reconstruction error and enhance policy performance. Our approach introduces two key structural innovations: (1) we decompose the latent action features into multiple heads, enabling the model to implicitly align specific heads with distinct action dimensions; (2) we assign independent codebooks to each head for quantization. By leveraging the combinatorial nature of multiple codebooks, we significantly expand the representational expressivity of the tokenizer, leading to substantially lower reconstruction loss compared to previous methods. We evaluate the $\\mathcal{M}^2$Tok-based VLA on the RoboTwin, Simpler-Env, and 3 zero-shot real-world tasks. Experimental results demonstrate our method not only achieves superior reconstruction fidelity but also significantly boosts the success rate of VLA models. Comprehensive ablation studies further confirm the effectiveness of the multi-head and multi-codebook mechanisms. Code is available at \\href{https://github.com/cpaaax/M2Tok}{https://github.com/cpaaax/M2Tok}.","authors":["Chunpu Xu","Zhixuan Liang","Yuhao Zhang","Chi-Min Chan","Jessie Wang","Yang Xiao","Mengkang Hu","Xiaokang Yang","Yao Mu"],"published":"2026-09-16T07:38:41Z","updated":"2026-09-16T07:38:41Z","abstract_url":"https://arxiv.org/abs/2609.18259v1","html_url":"https://arxiv.org/html/2609.18259v1","pdf_url":"https://arxiv.org/pdf/2609.18259v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18239v1","title":"Unified Response Geometry for Structured Pruning","abstract":"Structured pruning is commonly formulated as ranking individual channels, although channel responses can be complementary or cancel through downstream mixing. Motivated by these response interactions, we formulate pruning as the selection of a subset with large joint response capacity, followed by a separate functional realization step. Our unified response geometry maps each candidate set to \\(M(D,R)=D^{1/2}RD^{1/2}\\) and uses its determinant together with Schur-greedy residuals to select non-redundant coordinates. The same construction yields two information-conditioned instances: an unlabeled instance based on activation covariance, and a task-conditioned instance that combines activation and gradient variance for response scale with gradient correlation for complementarity. To convert the selected subset into an executable network, we fold predictable removed responses into successor weights through ridge compensation and recalibrate batch-normalization statistics, without fine-tuning the network. On ImageNet ResNet-50, the unlabeled instance reaches \\(65.4\\%\\) and \\(53.9\\%\\) Top-1 accuracy at 30\\% and 40\\% deletion, versus \\(59.8\\%\\) and \\(43.1\\%\\) for strength-only selection; the task-conditioned instance reaches \\(67.7\\%\\) and \\(56.3\\%\\) under the same protocol. A six-family screen shows architecture-dependent behavior, with positive relative contrasts in several convolutional and expansion-layer settings and clear boundary cases in windowed attention. These results support response geometry as a conditional principle for structured pruning, with its benefit determined jointly by the observed response and the architecture in which that response is realized.","authors":["Kaixiang Shu"],"published":"2026-09-16T07:15:09Z","updated":"2026-09-16T07:15:09Z","abstract_url":"https://arxiv.org/abs/2609.18239v1","html_url":"https://arxiv.org/html/2609.18239v1","pdf_url":"https://arxiv.org/pdf/2609.18239v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18206v1","title":"CapMap-MS-TTA: 3rd Place Solution for the MUMU Track of the 8th LSVOS Challenge at ECCV 2026","abstract":"The MUMU track of the 8th Large-scale Video Object Segmentation (LSVOS) Challenge requires a single unified multimodal model to jointly solve image tagging (Task A), open-vocabulary object detection (Task B), and English captioning (Task C) under strict resource constraints (<=0.5B parameters and <=8 GB peak GPU memory). We present CapMap-MS-TTA, a training-free submission built on Microsoft Florence-2-base (~231M parameters), combining caption keyword mapping with multi-scale flip test-time augmentation. Task C uses the native <DETAILED_CAPTION> pathway with length/token sanitization. Task A maps the same detailed caption into the official quality/scene/event vocabularies via an expanded keyword lexicon with whole-word matching and a lightweight expand-hints stage. Task B runs Florence-2 open detection (<OD>) with multi-scale and horizontal-flip test-time augmentation (TTA), followed by label-aware non-maximum suppression (NMS). Without fine-tuning, the system improves our reproduced Florence-2 baseline from 15.16 to a best public score of 16.4815, and ranks 3rd on the final MUMU leaderboard.","authors":["Chengfeng Qiu","Kaifeng Wei"],"published":"2026-09-16T06:38:23Z","updated":"2026-09-16T06:38:23Z","abstract_url":"https://arxiv.org/abs/2609.18206v1","html_url":"https://arxiv.org/html/2609.18206v1","pdf_url":"https://arxiv.org/pdf/2609.18206v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18139v1","title":"Multi-View Mixture-of-Experts with Vision-Language Reranking for Cross-View Object Geo-Localization","abstract":"Cross-view object geo-localization (CVOGL) locates a target in satellite imagery using drone or street-view queries. Existing methods train separate detectors for each viewpoint, leading to parameter redundancy and impeding cross-view knowledge sharing. Moreover, top-ranked satellite candidates are often visually similar, so visual appearance and categorical labels alone are insufficient to resolve such ambiguity. To address these, we propose MVLGeo, an efficient framework designed to unify multiple viewpoints and reduce model redundancy. First, we introduce environmental contextual text from the query view as cues to distinguish visually similar candidates via Vision-Language Reranking (VL-Rerank). Second, we design a multi-view Mixture-of-Experts architecture (MV-MoE) with a shared encoder and view-specific experts to reduce redundancy and promote knowledge sharing, while cross-view contrastive learning aligns their representations for consistency. Third, we introduce an adaptive elliptical prior (ESAM-Prior) as auxiliary positional encoding for anisotropic geometric perception. Extensive experiments on the CVOGL benchmarks confirm that MVLGeo, as a unified model for multiple query viewpoints, achieves state-of-the-art performance, demonstrating robustness to input degradation and generalization across viewpoints. Code and models will be available on GitHub to facilitate future work.","authors":["Xuyu Fan","Qi Ming","Zhu Han","Liuqian Wang","Siyuan Cao","Xiaohan Zhang","Xudong Zhao","Mingjing Zhao","Yuhan Zhang"],"published":"2026-09-16T05:21:54Z","updated":"2026-09-16T05:21:54Z","abstract_url":"https://arxiv.org/abs/2609.18139v1","html_url":"https://arxiv.org/html/2609.18139v1","pdf_url":"https://arxiv.org/pdf/2609.18139v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18129v1","title":"MCLC-NET: Multimodal Continual Learning for Leaf Counting","abstract":"Leaf counting is an important task in plant phenotyping for monitoring plant growth and estimating crop yield. Most existing methods rely on RGB images, but their performance is often affected by occlusion, lighting variations, and other real-world challenges. Additional modalities, such as depth and thermal images, can provide useful complementary information. However, multimodal leaf counting remains underexplored. Also, many existing methods assume that all training data are available simultaneously, which is impractical in real agricultural settings, where data is collected over time from multiple sources. To address these challenges, we propose MCLC-NET, a multimodal continual learning framework for leaf counting. It learns tasks sequentially using a memory-based strategy with a memory buffer to retain important samples from previous tasks. We also introduce MMLC, a real-world multimodal leaf-counting dataset designed for a domain incremental scenario (DIS) in CL. It contains RGB, depth, and thermal images collected across different crop types under varying environmental conditions, arranged in three orderings: crop-wise, time-wise, and mixed. Experimental results, averaged over three random seeds, demonstrate that MCLC-NET consistently outperforms existing methods across all three task orderings, achieving the lowest AMSE of 0.675$\\pm$0.027, 0.542$\\pm$0.069, and 0.745$\\pm$0.057, respectively.","authors":["Ruchi Bhatt","Pratibha Kumari","Shreya Bansal","Vedant Agnihotri","Dwarikanath Mahapatra","Mukesh Saini"],"published":"2026-09-16T05:07:52Z","updated":"2026-09-16T05:07:52Z","abstract_url":"https://arxiv.org/abs/2609.18129v1","html_url":"https://arxiv.org/html/2609.18129v1","pdf_url":"https://arxiv.org/pdf/2609.18129v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18125v1","title":"PRISM: Predictive Representation of Interaction Style and Motion for Social Robot Navigation","abstract":"Humans often observe others before interacting and adjust their behavior accordingly. Robot navigation in crowds, however, often represents pedestrians mainly by observed geometric states, leaving individual differences in interaction tendencies implicit. We propose PRISM (Predictive Representation of Interaction Style and Motion), a framework that infers interaction traits from passive observations of human-human interactions. PRISM encodes human trajectories into a continuous ordinal latent space with a transformer encoder trained by Rank-N-Contrast loss, and pairs each inferred trait with a temporal-stability score supplied to the navigation policy. In randomized crowd simulations, PRISM reduces collision rates over the geometry-only baseline and yields small improvements in navigation-time and path-length metrics. These results suggest the utility of passive latent-trait inference for social navigation in dynamic crowds.","authors":["Bo-Han Chen","Hiromu Taketsugu","Norimichi Ukita"],"published":"2026-09-16T05:01:27Z","updated":"2026-09-16T05:01:27Z","abstract_url":"https://arxiv.org/abs/2609.18125v1","html_url":"https://arxiv.org/html/2609.18125v1","pdf_url":"https://arxiv.org/pdf/2609.18125v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18124v1","title":"Aligned Consensus Teaching for Label-Efficient Oriented Object Detection in Weakly-Aligned Visible-Infrared Imagery","abstract":"Visible-infrared object detection (VIOD) detects objects with oriented bounding boxes from paired visible and infrared images. Existing methods depend on costly dual-modality annotations. Semi-supervised learning can reduce this burden, but extending it from single-modal detection to VIOD is challenging. In the practical image-pair-level setting considered here, only a few pairs are labeled in both modalities, while the rest are completely unlabeled. This limited supervision creates three challenges: (i) too few labeled boxes for robust cross-modal alignment; (ii) pseudo-label errors caused by branch-wise misses accumulate during self-training; and (iii) tail-class annotations become critically scarce as the labeling budget decreases. We propose Aligned Consensus Teacher (ACT) for label-efficient VIOD in this setting. Its Cycle-Consistent Region Alignment (CRA) combines cycle consistency and sparse anchors with reliability-weighted regional matching. Cross-Modal Consensus Mean-Teacher (CMC-MT) forms consensus pseudo labels under pair-preserving views to recover branch-wise misses and supervise unlabeled pairs. Text-Guided Cross-Modal Instance Augmentation (TG-CMIA) uses a vision-language scene prior to compose tail-class instance pairs while preserving RGB--IR offsets. To the best of our knowledge, ACT is the first framework to study semi-supervised VIOD under this image-pair-level setting. Experiments on DroneVehicle and VEDAI show consistent gains across annotation ratios. With 10\\% labeled pairs on DroneVehicle, ACT reaches 94.3\\% of the mAP obtained by the same detector under full supervision. Code and models will be available on GitHub to facilitate future work.","authors":["Qi Ming","Xiaxin Yuan","Jiahuan Zhou","Jiangmeng Li","Xudong Zhao","Zhanchao Huang","Juan Fang","Shaoguang Huang","Aleksandra Pizurica"],"published":"2026-09-16T04:59:37Z","updated":"2026-09-16T04:59:37Z","abstract_url":"https://arxiv.org/abs/2609.18124v1","html_url":"https://arxiv.org/html/2609.18124v1","pdf_url":"https://arxiv.org/pdf/2609.18124v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18111v1","title":"A Comprehensive Review of Generative Physical Artificial Intelligence","abstract":"The integration of large-scale foundation models with physical embodiments has led to significant advancements in robotics known as Generative Physical Artificial Intelligence (GPAI). These agentic AI systems autonomously perceive, reason, and act in complex real-world situations. This survey comprehensively analyzes GPAI systems, focusing on their architectural foundations, current applications, and key limitations. We introduce a taxonomy of five distinct approaches: Robot Foundation Models (RFMs) for cross-platform skill transfer; Vision-Language Action (VLA) models for end-to-end multi-modal perception and control; Large Behavior Models (LBMs) for human-like movement generation; Diffusion Policy Models (DPMs) for diffusion model-based temporally coherent action generation; and World Foundation Models (WFMs) for physics-compliant simulation and data generation. We examine how these approaches complement each other: WFMs generate training data for VLAs and DPMs, RFMs enable cross-platform deployment of learned policies, while LBMs provide motion priors for natural behavior. Through examples across autonomous vehicles, industrial automation, healthcare robotics, and humanoid systems, we identify significant performance improvements and summarize promising research directions in data-efficient learning, sim-to-real transfer, edge-compatible architectures, and safety frameworks. These insights advance embodied AI for IoT-connected environments where intelligent agents interact with networked sensors, actuators, and edge devices.","authors":["Satyam Gaba","Krutiksinh Rana","Siva Sai","Vinay Chamola","Dusit Niyato"],"published":"2026-09-16T04:29:50Z","updated":"2026-09-16T04:29:50Z","abstract_url":"https://arxiv.org/abs/2609.18111v1","html_url":"https://arxiv.org/html/2609.18111v1","pdf_url":"https://arxiv.org/pdf/2609.18111v1.pdf","matched_keywords":["agent","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18088v1","title":"Mask 2D-3D: Adaptive Dual-Masked Autoencoder Network for Image-to-Point Cloud Registration","abstract":"Detection-free methods for image-to-point cloud registration are prone to erroneous correspondences caused by domain and modality discrepancies, limited sensitivity of feature extractors, and the presence of non-overlapping regions. The Masked Autoencoder (MAE) has shown strong performance in visual representation for images and point clouds. It may be helpful to apply this approach to image-to-point cloud registration, a task that requires unified feature extraction and accurate cross-modal correspondences. Standard MAE's random masking may overlook key regions due to limited camera views, reducing registration effectiveness. To address this, we propose the Intermodal Dual-MAE Framework (ID-MAE) with a Similarity-based RL Masking Strategy (SRLM), which adaptively masks informative positions by leveraging cross-modal similarity and reinforcement learning, thus narrowing the modality gap. Our method enhances cross-modal representation learning by enforcing representation consistency during feature extraction, thereby enabling more reliable 2D-3D correspondence estimation. Experiments on RGB-D Scenes v2 and 7-Scenes benchmarks show that our method achieves state-of-the-art performance in image-to-point cloud registration.","authors":["Zhixin Cheng","Jiacheng Deng","Xiaotian Yin","Baoqun Yin","Richang Hong","Tianzhu Zhang"],"published":"2026-09-16T03:47:07Z","updated":"2026-09-16T03:47:07Z","abstract_url":"https://arxiv.org/abs/2609.18088v1","html_url":"https://arxiv.org/html/2609.18088v1","pdf_url":"https://arxiv.org/pdf/2609.18088v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18077v1","title":"vidax: A Unified JAX Framework for Video Generative Models on Accelerator Meshes","abstract":"Open-source video generative models ship almost exclusively as PyTorch/CUDA reference implementations. This leaves Cloud TPU pods without a production-ready inference path, despite offering large, cost-effective accelerator memory pools ideal for long-sequence spatiotemporal attention. We present vidax, an open-source JAX/Flax inference engine and zero-copy PyTorch-to-JAX weight translator for modern video generation architectures. vidax covers a diverse set of spatiotemporal models --- including Diffusion Transformers, omnimodal Mixture-of-Transformers, 3D VAEs, text encoders, and native samplers --- with zero PyTorch dependency in the execution path. The framework unifies 1D tensor parallelism with DeepSpeed-Ulysses sequence parallelism on a single JAX sharding mesh, integrates TPU flash-attention kernels, and implements per-layer weight offloading to support reference resolutions that exceed single-device memory. We benchmark compile times, latency, and peak memory utilization on TPU v4-8 hardware, and document real-world numerical bugs surfaced during checkpoint translation. vidax is released open-source as a baseline for JAX and TPU video generation research.","authors":["Congyue Deng"],"published":"2026-09-16T03:26:45Z","updated":"2026-09-16T03:26:45Z","abstract_url":"https://arxiv.org/abs/2609.18077v1","html_url":"https://arxiv.org/html/2609.18077v1","pdf_url":"https://arxiv.org/pdf/2609.18077v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18069v1","title":"GeoCueFormer: Geometry-Guided Wavelet Representation and Prediction-Cued Dual-Stage Decoder for Underwater Semantic Segmentation","abstract":"Underwater semantic segmentation is essential for marine ecosystem monitoring, yet remains challenging due to severe visual degradation. Light absorption and scattering often lead to color shifts, low contrast, and blurred boundaries, making shallow detail features unreliable. Existing underwater segmentation methods improve RGB feature aggregation or boundary prediction, but still lack an explicit mechanism to distinguish structure-related details from degradation-induced responses. To address this limitation, we propose GeoCueFormer, a lightweight framework that combines geometry-constrained frequency enhancement with prediction-cued refinement. GeoCueFormer performs stage-specific wavelet enhancement on hierarchical encoder features to complement shallow boundary details while preserving deep structural semantics. A depth-derived spatial gate constrains shallow frequency enhancement toward geometry-consistent regions, and a prediction-cued dual-stage decoder further refines ambiguous high-resolution features. GeoCueFormer obtains 82.23% and 73.04% mIoU on SUIM and DUT, respectively. Under comparable model complexity and standard benchmark settings on SUIM and DUT, it achieves SOTA performance while maintaining a favorable accuracy-complexity trade-off. These results show that distinguishing structural details from degradation-induced interference is more effective for underwater segmentation.","authors":["Xian Wu","Xinjin Li","Yiliu Xu","Yining Liu","Yong Jiang"],"published":"2026-09-16T03:14:32Z","updated":"2026-09-16T03:14:32Z","abstract_url":"https://arxiv.org/abs/2609.18069v1","html_url":"https://arxiv.org/html/2609.18069v1","pdf_url":"https://arxiv.org/pdf/2609.18069v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18058v1","title":"Finder: Agentic Closed-Loop Object Finding for Embodied Grounding","abstract":"Finding the object referred to by language in a partially observed 3D scene is a core capability for embodied agents. Existing approaches either couple object search with online exploration, which can be costly when relevant observations have already been captured, or query pre-built open-vocabulary maps and scene graphs in a static, one-shot fashion. We present Finder, an agentic closed-loop object-finding primitive for embodied grounding. Instead of treating grounding as passive retrieval from a fixed scene representation, Finder maintains a typed loop state that links query-conditioned planning, scoped evidence gathering, candidate verification, and accept/continue/abort control. When evidence is incomplete or ambiguous, the loop can redirect subsequent perception and comparison rather than simply returning the top retrieved object. On open-vocabulary embodied Object Retrieval in Habitat/HM3D and real-world RGB-D scenes, Finder improves the averaged 1m success rate by 15.75 points over strong baselines. The same primitive also transfers to sequential object grounding and embodied object-centric question answering, improving spatial and temporal localization without changing the inner grounding protocol. Project page: https://finder-vln.github.io.","authors":["Shixiong Xu","Zhiyuan Chen","Song Ding","Rui Luo","Xiaowei Liang","Dongxu Miao","Zhiying Du"],"published":"2026-09-16T03:02:45Z","updated":"2026-09-16T03:02:45Z","abstract_url":"https://arxiv.org/abs/2609.18058v1","html_url":"https://arxiv.org/html/2609.18058v1","pdf_url":"https://arxiv.org/pdf/2609.18058v1.pdf","matched_keywords":["retrieval","3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18056v1","title":"Position Anchor Tuning: Towards Efficient Adaptation of Pre-Trained Point Cloud Transformers","abstract":"Parameter-efficient fine-tuning (PEFT) has recently emerged as a pivotal research direction for adapting pre-trained point cloud transformers to diverse downstream tasks. Although existing methods achieve excellent fine-tuning performance with high parameter efficiency, they ignore inference efficiency. To tackle this problem, a novel PEFT method termed position anchor tuning (PAT) is proposed in this paper. As multi-head attention (MHA) and feed-forward network (FFN) are computation-heavy blocks in pre-trained transformers, PAT decreases their computational cost through token aggregation-expansion pairs. Each pair comprises a token aggregation module (TAM) and a token expansion module (TEM). For MHA and FFN blocks, TAMs extract representative tokens from their input tokens based on position anchors in 3D space. These extracted tokens, rather than the original input tokens, are processed by the blocks, thereby reducing the number of tokens involved in computation. Then, TEMs propagate the learned representations back to the original input tokens. Since TAMs are solely responsible for capturing task-specific representations, base-sharing low-rank adaptation (BSLoRA) is further introduced to enable them to learn such representations effectively with only a small number of trainable parameters. Extensive experiments on widely used benchmarks demonstrate that PAT performs comparably to state-of-the-art methods while incurring significantly lower computational overhead and fewer trainable parameters.","authors":["Zheng Liu","Xin Gao","Jinchao Zhu","Gao Huang"],"published":"2026-09-16T02:59:29Z","updated":"2026-09-16T02:59:29Z","abstract_url":"https://arxiv.org/abs/2609.18056v1","html_url":"https://arxiv.org/html/2609.18056v1","pdf_url":"https://arxiv.org/pdf/2609.18056v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18034v1","title":"IRIS: Implicit Rendering Matters for Pose-Free Novel View Synthesis","abstract":"Novel view synthesis from unposed multi-view images remains challenging, as the model must jointly learn scene representations and camera parameters without pose supervision. Existing approaches largely fall into two extremes: implicit latent-space rendering is flexible and easy to optimize, but often yields weakly grounded camera estimation; explicit 3D representations provide stronger geometric grounding, but introduce heavier parameterization and more fragile optimization. In this paper, we present IRIS, a fully self-supervised framework that provides a practical middle ground between these two paradigms. Instead of decoding free latent tokens or reconstructing fully explicit 3D primitives, IRIS represents the scene as a latent neural field and renders novel views by querying this field under self-predicted cameras. Specifically, projected features from reference views are aggregated at sampled 3D points to form point-wise latent features, which are then composed along target rays for rendering. This design preserves the flexibility and optimization stability of implicit modeling, while introducing stronger geometric structure than unconstrained latent rendering. Extensive experiments show that IRIS achieves strong novel view synthesis quality with competitive pose accuracy under fully self-supervised learning. Our project page: https://leo-frank.github.io/IRIS","authors":["Wenyu Li","Sidun Liu","Peng Qiao","Yong Dou","Tongrui Hu"],"published":"2026-09-16T02:35:22Z","updated":"2026-09-16T02:35:22Z","abstract_url":"https://arxiv.org/abs/2609.18034v1","html_url":"https://arxiv.org/html/2609.18034v1","pdf_url":"https://arxiv.org/pdf/2609.18034v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.18007v1","title":"Newer Is Not Fairer: Gender Stereotyping in Text-to-Image AI Across Model Generations","abstract":"Text-to-image generative models are widely used in professional and creative settings, yet how they represent gender across occupations -- and whether newer models are fairer -- remains poorly understood across multiple generations. We evaluate gender representation across 20 occupations, 5 prompt templates, and 4 Stable Diffusion model generations (SD 1.5, SD 2.1, SDXL, SD 3 Medium), generating 8,000 images with n = 100 per occupation-model cell (5 prompts x 20 images), and classifying all with DeepFace. Across the 8,000 open-source images, 76.4% show male subjects (95% CI [75.1%, 78.7%], p < 2.2 x 10^-16, Benjamini-Hochberg adjusted). More strikingly, 57.6% of images for historically female-coded occupations show male subjects (raw p = 3.43 x 10^-22, BH-adjusted p = 1.71 x 10^-21). All nine significant tests reported in this paper survive BH correction across 10 tests. When compared against U.S. Bureau of Labor Statistics workforce data, models underrepresent women by 20-46pp on average, with particularly large deviations for near gender-balanced occupations: scientist (48% female in BLS, 82-99% male in model outputs) and cleaner (46% female in BLS, 80-92% male in outputs). Model generations do not improve steadily: bias worsens from SD 1.5 to SDXL before partially recovering in SD 3 Medium. A preliminary comparison with GPT-image-1 on five occupations suggests lower bias than open-source models, though the practical effect is small (Cramer's V = 0.080) and the comparison is exploratory. No model achieves gender parity.","authors":["Shesh Narayan Gupta","Nik Bear Brown"],"published":"2026-09-16T01:54:12Z","updated":"2026-09-16T01:54:12Z","abstract_url":"https://arxiv.org/abs/2609.18007v1","html_url":"https://arxiv.org/html/2609.18007v1","pdf_url":"https://arxiv.org/pdf/2609.18007v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"},{"id":"2609.17953v1","title":"EDCT-Bench: Uncovering Faithfulness Gaps in VLMs via Explanation-Driven Counterfactual Testing","abstract":"Vision-Language Models (VLMs) can produce Natural Language Explanations (NLEs) that sound plausible yet remain inconsistent with the visual evidence they cite. We present Explanation-Driven Counterfactual Testing (EDCT), an intervention-based protocol that extracts visual concepts cited in a model's explanation, applies verified minimal edits to them, and tests whether the resulting answer and explanation remain consistent with the edited image. Using this protocol, we create EDCT-Bench, a comprehensive benchmark spanning three complementary domains: knowledge-intensive visual question answering (OK-VQA), safety-critical driving (DriveLM), and 3D spatial reasoning (3DSRBench). Across the evaluated VLMs, EDCT reveals substantial faithfulness gaps, with models frequently producing responses inconsistent with verified visual changes. Finally, our fine-tuning study suggests that EDCT-generated counterfactuals provide high-impact training signals.","authors":["Sihao Ding","Santosh Vasa","Aditi Ramadwar","Thomas Monninger"],"published":"2026-09-16T00:25:31Z","updated":"2026-09-16T00:25:31Z","abstract_url":"https://arxiv.org/abs/2609.17953v1","html_url":"https://arxiv.org/html/2609.17953v1","pdf_url":"https://arxiv.org/pdf/2609.17953v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-09-17T05:40:01+00:00","last_seen_at":"2026-09-17T05:40:01+00:00"}],"tracked_paper_count":61,"storage_mode":"latest_overwrite"}};
